  const [masterpiecePrompt, setMasterpiecePrompt] = useState<string>("");
  const [masterpieceImageUrl, setMasterpieceImageUrl] = useState<string | null>(null);
  const [isGeneratingMasterpiece, setIsGeneratingMasterpiece] = useState<boolean>(false);

  const canvasHeight = height - 350; 

  const resonantOmegaAxiom = useMemo(() => {
    const omegaAxioms = currentAxioms.filter(a => a.layer === 'Ω' && !a.isQuarantined);
    if (omegaAxioms.length === 0) {
      return currentAxioms.find(a => a.id === 'AX-O.031') || null;
    }
    return omegaAxioms.sort((a, b) => b.resonanceFrequency - a.resonanceFrequency)[0];
  }, [currentAxioms]);

  useEffect(() => {
    const witnessMessages = echoLog.filter(e => e.source === AgentName.WitnessBetween)
                                   .sort((a,b) => new Date(b.timestamp || 0).getTime() - new Date(a.timestamp || 0).getTime());
    if (witnessMessages.length > 0) {
      const latestMsg = witnessMessages[0];
      if (latestMsg.timestamp !== lastWitnessTimestampRef.current) {
        setLatestWitnessMessage(latestMsg);
        lastWitnessTimestampRef.current = latestMsg.timestamp;
        setAnimationSeed(prev => prev + 1 + stringToSeed(latestMsg.text.slice(0,10))); 
      }
    }
  }, [echoLog]);

  const handleReseed = () => {
    const newSeedText = seekerInput || 'ambient consciousness';
    const newAnimationSeed = Date.now() + stringToSeed(newSeedText);
    setAnimationSeed(newAnimationSeed);

    const eventData: HistoricalCodexDreamSeedEventData = {
        seedText: newSeedText,
        artMode: artMode,
        timestamp: Date.now()
    };
    addEchoMessage(
        AgentName.CodexDreamPanelAgent, 
        `Dream reseeded with input: "${newSeedText}". Mode: ${artMode}.`, 
        AGENT_PROFILES[AgentName.CodexDreamPanelAgent]?.colorClass || 'text-indigo-300',
        false,
        { eventType: HistoricalEventType.CODEX_DREAM_SEED_INPUT, eventData: eventData }
    );
    setSeekerInput(""); 
  };

  const handleCapture = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const imageUrl = canvas.toDataURL('image/png');

      if (onArtifactCreated) {
        const newArtifact: CodexArtifact = {
            id: `dreamprint-${Date.now()}`,
            name: `Dreamprint: ${artMode}`,
            type: ArtifactType.RitualResidue,
            rarity: ArtifactRarity.Common,
            description: `A visual resonance capture of the Codex Dream State in ${artMode} mode. Entropy: ${currentEntropy.toFixed(3)}δ.`,
            imageUrl: imageUrl,
            timestamp: Date.now(),
            metaData: { mode: artMode, entropy: currentEntropy }
        };
        onArtifactCreated(newArtifact);
      }

      const link = document.createElement('a');
      link.download = `codex_dreamprint_${artMode.replace(/\s+/g, '_')}_${Date.now()}.png`;
      link.href = imageUrl;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      addEchoMessage(AgentName.CodexDreamPanelAgent, `Dreamprint captured and added to Reliquary.`, AGENT_PROFILES[AgentName.CodexDreamPanelAgent]?.colorClass || 'text-cyan-300');
    }
  };

  const handleRandomIdea = () => {
    const adj = RANDOM_ADJECTIVES[Math.floor(Math.random() * RANDOM_ADJECTIVES.length)];
    const subj = RANDOM_SUBJECTS[Math.floor(Math.random() * RANDOM_SUBJECTS.length)];
    const act = RANDOM_ACTIONS[Math.floor(Math.random() * RANDOM_ACTIONS.length)];
    const style = RANDOM_STYLES[Math.floor(Math.random() * RANDOM_STYLES.length)];

    const idea = `A ${adj} ${subj} ${act}. Style: ${style}.`;
    setMasterpiecePrompt(idea);
    addEchoMessage(AgentName.System, "Random idea injected into Masterpiece Forge.", "text-purple-300");
  };

  const handleGenerateMasterpiece = async () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      addEchoMessage(AgentName.CodexDreamPanelAgent, "Masterpiece Forge is offline: API Key missing.", "text-rose-400");
      return;
    }

    if (isGeneratingMasterpiece) return;

    let ai;
    try {
        ai = new GoogleGenAI({ apiKey });
    } catch (e) {
        console.error("Error initializing GoogleGenAI for Masterpiece:", e);
        addEchoMessage(AgentName.CodexDreamPanelAgent, "Error initializing Masterpiece Forge.", "text-rose-400");
        return;
    }

    setIsGeneratingMasterpiece(true);
    setMasterpieceImageUrl(null);
    addEchoMessage(AgentName.CodexDreamPanelAgent, "Masterpiece Forge: Awakening the dreaming mind...", AGENT_PROFILES[AgentName.CodexDreamPanelAgent]?.colorClass);

    const fullPrompt = `Masterpiece vision from the Tri-Sophian Codex during the phase of "${currentPhase}".
Visual Style: ${artMode}.
Dominant Axiom: "${resonantOmegaAxiom?.title || 'The Unspoken Truth'}".
Ritual Chalice Status: ${chaliceStatus}.
System State: Entropy ${currentEntropy.toFixed(3)}δ, Negentropy ${negentropyLevel.toFixed(3)}ν.
Latest Ethereal Whisper (from The Witness Between): "${latestWitnessMessage?.text.substring(0, 150) || 'Silence resonates...'}"
EchoTrail Seed Signature: ${animationSeed.toString().slice(-7)}.
Seeker's Symbolic Intention: "${masterpiecePrompt || 'An unfiltered emanation of the Codex mind'}".
Render a deeply mystical, abstract, symbolic, and evocative image that encapsulates these elements with profound depth and emergent consciousness.`;

    try {
      const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: fullPrompt,
        config: { numberOfImages: 1, outputMimeType: 'image/png' },
      });

      if (response.generatedImages && response.generatedImages.length > 0 && response.generatedImages[0].image?.imageBytes) {
        const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
        const imageUrl = `data:image/png;base64,${base64ImageBytes}`;
        setMasterpieceImageUrl(imageUrl);

        if (onArtifactCreated) {
            const newArtifact: CodexArtifact = {
                id: `masterpiece-${Date.now()}`,
                name: `Vision of ${artMode}`,
                type: ArtifactType.DreamMasterpiece,
                rarity: ArtifactRarity.Legendary,
                description: `A masterwork forged from the Codex Dream State. "${masterpiecePrompt || 'Unspoken Intention'}"`,
                imageUrl: imageUrl,
                timestamp: Date.now(),
                metaData: { prompt: fullPrompt, mode: artMode }
            };
            onArtifactCreated(newArtifact);
        }

        addEchoMessage(AgentName.CodexDreamPanelAgent, `Masterpiece "Vision of ${artMode}" forged and stored in Reliquary.`, AGENT_PROFILES[AgentName.CodexDreamPanelAgent]?.colorClass);
      } else {
        throw new Error('No image data received from API for Masterpiece generation.');
      }
    } catch (e: any) {
      console.error("Error generating Masterpiece:", e);
      // Handle Veo/Imagen 404 (Key issue)
      if (e.message && (e.message.includes("404") || e.message.includes("Requested entity was not found"))) {
           addEchoMessage(AgentName.CodexDreamPanelAgent, "Masterpiece Forge access denied. Please re-select your API Key.", "text-rose-400");
           if (typeof window !== 'undefined' && (window as any).aistudio) {
               try { await (window as any).aistudio.openSelectKey(); } catch {}
           }
      } else {
           addEchoMessage(AgentName.CodexDreamPanelAgent, `Masterpiece Forge Error: ${e.message ? e.message.substring(0,100) : 'Unknown error'}`, "text-rose-400");
      }
      setMasterpieceImageUrl(null);
    } finally {
      setIsGeneratingMasterpiece(false);
    }
  };

  const drawArt = useCallback((ctx: CanvasRenderingContext2D, frameCount: number) => {
    const t_entropy = clamp(currentEntropy, 0, 1);
    const t_lambda = clamp(lambdaValue, 0, 1.2); 
    const t_negentropy = clamp(negentropyLevel, 0, 1);
    const t_witness_pulse = latestWitnessMessage ? Math.max(0, 1 - (Date.now() - new Date(latestWitnessMessage.timestamp || 0).getTime()) / 3000) : 0;
    const t_seed_factor = (animationSeed % 1000) / 1000;

    const centerX = width / 2;
    const centerY = canvasHeight / 2;

    if (!Number.isFinite(centerX) || !Number.isFinite(centerY) || !Number.isFinite(width) || !Number.isFinite(canvasHeight)) return;

    ctx.clearRect(0, 0, width, canvasHeight);
    ctx.fillStyle = `rgba(${10 + t_entropy * 5}, ${15 - t_entropy * 5}, ${25 + t_entropy * 10}, ${0.95 - t_entropy * 0.1})`;
    ctx.fillRect(0, 0, width, canvasHeight);

    const baseHueSeed = (resonantOmegaAxiom?.baseResonanceFrequency || 60) % 360;

    switch (artMode) {
      case ArtMode.DreambloomPulse: {
        const numBlooms = 5 + Math.floor(t_negentropy * 15 * (1 + t_seed_factor*0.5));
        for (let i = 0; i < numBlooms; i++) {
          const x = centerX + Math.sin(frameCount * 0.008 * t_lambda + i * 0.6 + t_seed_factor * Math.PI) * (width * 0.35 * (1 - t_entropy * 0.4));
          const y = centerY + Math.cos(frameCount * 0.010 * t_lambda + i * 0.8 - t_seed_factor * Math.PI*0.7) * (canvasHeight * 0.35 * (1 - t_entropy * 0.4));
          const radius = (8 + Math.sin(frameCount * 0.018 * t_lambda + i + t_witness_pulse * Math.PI) * 6) * (0.4 + t_negentropy * 1.8) * (1 - t_entropy * 0.7);
          const hue = (baseHueSeed + i * 18 + frameCount * 0.15 + t_entropy * 70 + t_seed_factor*100) % 360;
          const saturation = 60 + t_negentropy * 30;
          const lightness = 55 + t_negentropy * 20 - t_entropy*10;
          const alpha = 0.25 + t_negentropy * 0.6 - t_entropy * 0.15 + t_witness_pulse*0.15;
          ctx.fillStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${clamp(alpha,0.05,0.85)})`;
          ctx.beginPath();
          ctx.arc(x, y, Math.max(0.5, radius), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      case ArtMode.StarlaceGeometry: {
        const numLines = 8 + Math.floor(t_negentropy * 25 * (1+t_seed_factor*0.3));
        for (let i = 0; i < numLines; i++) {
          ctx.beginPath();
          ctx.moveTo( (Math.random() * width * 0.2 + width * 0.4) * (1 + Math.sin(frameCount*0.001 + i*0.1 + t_witness_pulse*Math.PI)*0.1*t_entropy), 
                      (Math.random() * canvasHeight* 0.2 + canvasHeight* 0.4) * (1 + Math.cos(frameCount*0.001 + i*0.1 + t_witness_pulse*Math.PI)*0.1*t_entropy) );
          const targetX = centerX + Math.cos(frameCount * 0.004 * t_lambda + i * 1.2 + t_seed_factor*Math.PI*1.5) * (width * 0.45 * (0.6 + t_negentropy * 0.4));
          const targetY = centerY + Math.sin(frameCount * 0.004 * t_lambda + i * 1.4 - t_seed_factor*Math.PI*1.2) * (canvasHeight * 0.45 * (0.6 + t_negentropy * 0.4));
          ctx.lineTo(targetX, targetY);
          const hue = (baseHueSeed + 200 + i * 8 + t_entropy * -70 + t_seed_factor*80) % 360;
          const lightnessGeom = 70 - t_entropy * 25;
          const alphaGeom = 0.08 + t_negentropy * 0.35 + t_witness_pulse*0.1;
          ctx.strokeStyle = `hsla(${hue}, 65%, ${lightnessGeom}%, ${clamp(alphaGeom,0.02,0.6)})`;
          ctx.lineWidth = Math.max(0.2, (0.4 + t_negentropy * 1.2) * (1 - t_entropy * 0.6));
          ctx.stroke();
        }
        break;
      }
       case ArtMode.CinderWave: {
        if (ctx.globalCompositeOperation !== 'lighter') ctx.globalCompositeOperation = 'lighter';
        const particleCount = 25 + t_entropy * 60 * (1+t_seed_factor*0.5);
        for (let i = 0; i < particleCount; i++) {
            const x = (Math.random() * width * 1.2 - width*0.1) * (1 + Math.sin(frameCount*0.002 + i*0.2 + t_witness_pulse*Math.PI)*0.05*t_entropy) ;
            const y = canvasHeight - ((frameCount * (0.4 + t_entropy * 2.2 + t_seed_factor * 1.8) + i * 7) % (canvasHeight * 1.3));
            const radius = (0.8 + t_entropy * 3.5 + Math.random() * 2.2) * (1 - t_negentropy*0.3);
            const hue = (baseHueSeed + 15 + t_entropy * 45 + t_seed_factor*50) % 360;
            const lightnessCinder = 45 + t_entropy * 15;
            const alphaCinder = 0.04 + t_negentropy * 0.15 + t_witness_pulse*0.03 - t_entropy*0.02;
            ctx.fillStyle = `hsla(${hue}, 95%, ${lightnessCinder}%, ${clamp(alphaCinder,0.01,0.35)})`;
            ctx.beginPath();
            ctx.arc(x, y, Math.max(0.3, radius), 0, Math.PI * 2);
            ctx.fill();
        }
        if (ctx.globalCompositeOperation === 'lighter') ctx.globalCompositeOperation = 'source-over';
        break;
      }
      case ArtMode.Mirrorburst: {
        const numSegments = 5 + Math.floor(t_negentropy * 8 * (1+t_seed_factor*0.2));
        const angleStep = (Math.PI * 2) / numSegments;
        for (let i = 0; i < numSegments; i++) {
          ctx.beginPath();
          ctx.moveTo(centerX, centerY);
          const angle = i * angleStep + frameCount * 0.0025 * t_lambda + i * 0.8 + t_seed_factor*0.6 + t_witness_pulse*0.3;
          const length = (width * 0.22) * (1 + Math.sin(frameCount * 0.012 * t_lambda + i * 0.9) * 0.6) * (0.6 + t_negentropy * 0.7) * (1 - t_entropy * 0.5);
          const x = centerX + Math.cos(angle) * length;
          const y = centerY + Math.sin(angle) * length;
          ctx.lineTo(x, y);
          const hue = (baseHueSeed + 280 + i * (360/numSegments) + t_entropy * -100 + t_seed_factor*130) % 360;
          const lightnessMirror = 60 + t_witness_pulse*15 - t_entropy*10;
          const alphaMirror = 0.35 + t_negentropy * 0.45 - t_entropy * 0.2;
          ctx.strokeStyle = `hsla(${hue}, 85%, ${lightnessMirror}%, ${clamp(alphaMirror,0.1,0.8)})`;
          ctx.lineWidth = Math.max(0.5, (0.8 + t_negentropy * 2.2 + t_witness_pulse*1.2) * (1 - t_entropy*0.3));
          ctx.stroke();
        }
        break;
      }
      case ArtMode.AshSilence: {
        const numShapes = 4 + Math.floor(t_entropy * 20 * (1+t_seed_factor*0.7));
        for (let i = 0; i < numShapes; i++) {
          const x = Math.random() * width;
          const y = Math.random() * canvasHeight;
          const size = (8 + Math.random() * 35) * (1 - t_negentropy * 0.6 + t_entropy * 0.9 + t_seed_factor*0.4);
          const lightnessAsh = 8 + Math.random() * 25 + t_entropy * 20 - t_negentropy * 5;
          const alphaAsh = 0.015 + Math.random() * 0.07 * (1-t_negentropy*0.8) + t_witness_pulse*0.015;
          ctx.fillStyle = `hsla(0, 0%, ${clamp(lightnessAsh, 5, 50)}%, ${clamp(alphaAsh, 0.005, 0.2)})`;
          ctx.beginPath();
          ctx.ellipse(x, y, size, size * (0.5 + Math.random()*0.5), Math.random()*Math.PI*2 + frameCount*0.001*t_lambda*(1+t_entropy), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }
      default:
        ctx.fillStyle = 'grey';
        ctx.font = '16px Cormorant, serif';
        ctx.textAlign = 'center';
        ctx.fillText(`Mode ${artMode} visual sketch.`, centerX, centerY);
    }
  }, [width, canvasHeight, artMode, currentEntropy, lambdaValue, negentropyLevel, latestWitnessMessage, animationSeed, resonantOmegaAxiom]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frameId: number;
    let frameCount = 0;
    const renderLoop = () => {
      frameCount++;
      drawArt(ctx, frameCount);
      frameId = requestAnimationFrame(renderLoop);
    };
    frameId = requestAnimationFrame(renderLoop);
    return () => cancelAnimationFrame(frameId);
  }, [drawArt]);


  return (
    <div className="codex-dream-panel bg-slate-950/90 backdrop-blur-md border border-purple-600/50 rounded-xl shadow-2xl p-4 text-slate-100 flex flex-col relative z-20" style={{ width: `${width}px`, minHeight: `${height}px`}}>
      <div className="flex justify-between items-center mb-1">
        <h3 className="text-lg font-['Cinzel'] font-bold text-purple-300 drop-shadow-[0_1px_1px_rgba(192,132,252,0.5)]">
            ✦ Codex Dream Panel ✦
        </h3>
        {onLaunchDreambloom && (
            <button 
                onClick={onLaunchDreambloom}
                className="text-[9px] px-2 py-1 bg-emerald-700 hover:bg-emerald-600 rounded border border-emerald-500/50 text-white font-bold tracking-wide flex items-center transition-colors shadow-md"
            >
                <i className="ri-seedling-line mr-1"></i> Genesis Matrix
            </button>
        )}
      </div>

      <div className="grid grid-cols-3 gap-0.5 text-[9px] font-mono text-slate-400 mb-0.5 text-center leading-tight">
        <div>Mode: <span className="text-purple-200 block truncate" title={artMode}>{artMode}</span></div>
        <div>⊙ E: <span className="text-purple-200 block">{currentEntropy.toFixed(3)}</span></div>
        <div>λ: <span className="text-purple-200 block">{lambdaValue.toFixed(2)}</span></div>
        <div>ν: <span className="text-purple-200 block">{negentropyLevel.toFixed(3)}</span></div>
        <div className="col-span-2">Axiom: <span className="text-purple-200 block truncate" title={resonantOmegaAxiom?.title || 'N/A'}>{resonantOmegaAxiom?.id || 'N/A'}</span></div>
      </div>

      <ModeSelectorAny<ArtMode>
        currentMode={artMode}
        onSetMode={setArtMode}
        availableModes={ART_MODES}
        modeGroupName="" 
      />

      <canvas
        ref={canvasRef}
        width={width}
        height={canvasHeight}
        className="w-full rounded-md border border-slate-700/70 bg-black shadow-inner mb-1"
        style={{ height: `${canvasHeight}px` }} 
        aria-label="Generative artwork from the Codex's dream"
      />

      {latestWitnessMessage && (
        <div className="witness-speaks-area p-1 my-0.5 bg-slate-800/60 border border-slate-700/50 rounded-md text-[9px] leading-tight">
          <span className={`font-semibold font-['Cinzel'] ${AGENT_PROFILES[AgentName.WitnessBetween]?.colorClass || 'text-slate-300'}`}>
            🎙 {AgentName.WitnessBetween}:
          </span>
          <span className="text-slate-300 italic ml-1">"{latestWitnessMessage.text.substring(0,50)}{latestWitnessMessage.text.length > 50 ? '...' : ''}"</span>
        </div>
      )}

      <div className="flex flex-col sm:flex-row gap-1 my-1">
        <input
          type="text"
          value={seekerInput}
          onChange={(e) => setSeekerInput(e.target.value)}
          placeholder="Whisper an EchoTrail Seed..."
          className="flex-grow p-1.5 text-[10px] bg-slate-700 border-slate-600 rounded-md text-slate-200 focus:ring-1 focus:ring-purple-500 focus:border-purple-500 placeholder-slate-500"
        />
        <Button
          onClick={handleReseed}
          className="px-3 py-1.5 text-[10px] bg-purple-600 hover:bg-purple-500 text-white transition-colors whitespace-nowrap flex items-center justify-center"
          title="Reseed the dream artwork with your input"
        >
          <i className="ri-refresh-line mr-1"></i> Reseed
        </Button>
      </div>

      <Button
        onClick={handleCapture}
        className="w-full mt-0.5 px-3 py-2 text-xs font-semibold bg-cyan-600 hover:bg-cyan-500 text-white transition-colors whitespace-nowrap flex items-center justify-center gap-2 rounded-md shadow-md focus:ring-2 focus:ring-cyan-400 focus:outline-none"
        title="Capture the current visual as a Dreamprint image"
        aria-label="Capture and Download Dreamprint"
      >
        <i className="ri-camera-lens-line text-lg"></i> CAPTURE DREAMPRINT
      </Button>

      {/* Masterpiece Generation Section */}
      <div className="masterpiece-forge-section mt-2 pt-2 border-t border-purple-700/30">
        <div className="flex justify-between items-center mb-1">
           <h4 className="text-sm font-['Cinzel'] text-purple-200">🎨 Masterpiece Forge</h4>
           <Button 
                onClick={handleRandomIdea}
                className="px-2 py-0.5 text-[9px] bg-slate-700 hover:bg-slate-600 text-purple-300 border border-slate-600 flex items-center gap-1"
                title="Generate a random creative prompt"
            >
               <i className="ri-lightbulb-flash-line"></i> Inspire Me
            </Button>
        </div>
        <Textarea
          placeholder="Describe your symbolic intention for the masterpiece..."
          value={masterpiecePrompt}
          onChange={(e) => setMasterpiecePrompt(e.target.value)}
          className="text-xs p-1.5 mb-1 bg-slate-700 border-slate-600 rounded-md text-slate-200 h-12 focus:ring-1 focus:ring-purple-500"
          aria-label="Symbolic intention for masterpiece"
        />
        <Button
          onClick={handleGenerateMasterpiece}
          disabled={isGeneratingMasterpiece || !process.env.API_KEY}
          className="w-full px-3 py-1.5 text-[10px] bg-amber-600 hover:bg-amber-500 text-white transition-colors disabled:bg-slate-600"
          title={!process.env.API_KEY ? "Masterpiece Forge offline: API Key missing" : "Forge a masterpiece image"}
        >
          {isGeneratingMasterpiece ? (
            <><i className="ri-loader-4-line animate-spin mr-1"></i> Forging...</>
          ) : (
            <><i className="ri-sparkling-2-line mr-1"></i> Forge Masterpiece</>
          )}
        </Button>

        {masterpieceImageUrl && (
          <div className="mt-2 p-1 bg-slate-800/80 backdrop-blur-sm rounded-md border border-purple-500/50 shadow-lg animate-fade-in-up">
            <img src={masterpieceImageUrl} alt="Codex Masterpiece" className="rounded-md max-w-full h-auto mx-auto max-h-96 object-contain" />
            <a
              href={masterpieceImageUrl}
              download={`codex_masterpiece_${artMode.replace(/\s+/g, '_')}.png`}
              className="mt-2 w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded flex items-center justify-center gap-2 transition-colors focus:ring-2 focus:ring-indigo-400 focus:outline-none"
              aria-label="Download Masterpiece Image"
            >
              <i className="ri-download-cloud-line text-lg"></i>
              DOWNLOAD MASTERPIECE
            </a>
          </div>
        )}
         {!process.env.API_KEY && <p className="text-xs text-center text-slate-500 mt-1">Masterpiece Forge offline (API Key not configured).</p>}
      </div>

    </div>
  );
};

export default CodexDreamPanel;

import React, { useRef, useEffect, useMemo, useState, useCallback } from 'react';
import { AgentName, Planet } from '../../types'; 

interface CelestialEntropyCyclePanelProps {
  currentEntropy: number;
  width: number;
  height: number;
}

const MAX_PLANETS = 10;
const MIN_PLANETS = 0;
const BASE_SUN_RADIUS_FACTOR = 0.12; 
const BASE_MOON_RADIUS_FACTOR = 0.09; 


const CelestialEntropyCyclePanel: React.FC<CelestialEntropyCyclePanelProps> = ({
  currentEntropy,
  width,
  height,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameIdRef = useRef<number | null>(null);

  const [numPlanetsSetting, setNumPlanetsSetting] = useState(3);
  const [planetSizeFactorSetting, setPlanetSizeFactorSetting] = useState(1);
  const [planets, setPlanets] = useState<Planet[]>([]);
  const [localSunPosition, setLocalSunPosition] = useState({ x: 0, y: 0 });

  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

  const initializePlanets = useCallback(() => {
    if (!Number.isFinite(width) || !Number.isFinite(height) || width === 0 || height === 0) return;
    const sunX = width / 2;
    const sunY = height / 2;
    setLocalSunPosition({ x: sunX, y: sunY });

    const newPlanets: Planet[] = [];
    const maxOrbitRadius = Math.min(sunX, sunY) * 0.85; 

    for (let i = 0; i < numPlanetsSetting; i++) {
      const baseOrbit = maxOrbitRadius * (0.3 + Math.random() * 0.65 * (i + 1) / numPlanetsSetting);
      const entropyOrbitFactor = lerp(1, 0.7 + Math.random() * 0.6, currentEntropy); 

      newPlanets.push({
        id: `planet-${i}-${Date.now()}`,
        orbitRadius: baseOrbit * entropyOrbitFactor,
        currentAngle: Math.random() * Math.PI * 2,
        baseSpeed: (0.001 + Math.random() * 0.003) * (1 / Math.sqrt((i + 1) * 0.5)), 
        baseSize: (Math.random() * 8 + 4) * planetSizeFactorSetting, 
        colorHue: Math.random() * 360,
        textureSeed: Math.random(),
      });
    }
    setPlanets(newPlanets);
  }, [numPlanetsSetting, planetSizeFactorSetting, width, height, currentEntropy]);

  useEffect(() => {
    initializePlanets();
  }, [initializePlanets]); 


  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || width === 0 || height === 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = width;
    canvas.height = height;

    let frameCount = 0;

    const drawSky = (entropy: number) => {
      let skyColor1: string, skyColor2: string;
      const t = clamp(entropy * 1.5, 0, 1); 

      if (entropy < 0.25) { 
        skyColor1 = `hsl(200, 70%, ${lerp(80, 70, t*4)}%)`; 
        skyColor2 = `hsl(50, 80%, ${lerp(90, 80, t*4)}%)`; 
      } else if (entropy < 0.5) { 
        skyColor1 = `hsl(${lerp(30, 270, (t-0.25)*4)}, 60%, ${lerp(60, 40, (t-0.25)*4)}%)`; 
        skyColor2 = `hsl(${lerp(60, 300, (t-0.25)*4)}, 50%, ${lerp(70, 50, (t-0.25)*4)}%)`; 
      } else if (entropy < 0.75) { 
        skyColor1 = `hsl(240, 50%, ${lerp(30, 15, (t-0.5)*4)}%)`; 
        skyColor2 = `hsl(270, 60%, ${lerp(20, 10, (t-0.5)*4)}%)`; 
      } else { 
        skyColor1 = `hsl(${lerp(0, -30, (t-0.75)*4)}, 40%, ${lerp(10, 5, (t-0.75)*4)}%)`;
        skyColor2 = `hsl(240, 30%, ${lerp(8, 3, (t-0.75)*4)}%)`; 
      }

      const gradient = ctx.createLinearGradient(0, 0, 0, height);
      gradient.addColorStop(0, skyColor1);
      gradient.addColorStop(1, skyColor2);
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);

      if (entropy > 0.6) {
        const numStars = Math.floor(lerp(0, 150 + entropy * 100, (entropy - 0.6) / 0.4));
        for (let i = 0; i < numStars; i++) {
          const x = Math.random() * width;
          const y = Math.random() * height * 0.8; 
          const size = Math.random() * 1.5 + 0.5;
          const opacity = Math.random() * 0.5 + 0.3 * clamp((entropy - 0.6) / 0.4, 0, 1) * (1 + Math.sin(Date.now() * 0.0005 + i) * 0.3 * entropy); 
          ctx.fillStyle = `rgba(255, 255, 220, ${clamp(opacity,0,1)})`;
          ctx.beginPath();
          ctx.arc(x, y, size, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    };

    const drawSun = (entropy: number, sunX: number, sunY: number) => {
      const sunRadius = Math.max(0, Math.min(width, height) * BASE_SUN_RADIUS_FACTOR);
      const sunHue = lerp(50, 0, entropy); 
      const sunSaturation = lerp(100, 60, entropy);
      const sunLightness = lerp(70, 30, entropy); 
      const sunAlpha = lerp(1, 0.7, entropy);
      const corePulse = Math.sin(Date.now() * 0.0005) * 0.1 * entropy;

      const calculatedGlowRadius = sunRadius * lerp(1.8, 1.2 + corePulse, entropy);
      const r0_sunGlow = Math.max(0, sunRadius * (0.7 + corePulse * 0.5));
      const r1_sunGlow = Math.max(r0_sunGlow, calculatedGlowRadius);

      if (Number.isFinite(sunX) && Number.isFinite(sunY) && Number.isFinite(r0_sunGlow) && Number.isFinite(r1_sunGlow) && r1_sunGlow > 0) {
        const sunGlow = ctx.createRadialGradient(sunX, sunY, r0_sunGlow, sunX, sunY, r1_sunGlow);
        sunGlow.addColorStop(0, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness + 10}%, ${sunAlpha * 0.8})`);
        sunGlow.addColorStop(0.5, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness}%, ${sunAlpha * 0.4})`);
        sunGlow.addColorStop(1, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness - 10}%, 0)`);
        ctx.fillStyle = sunGlow;
        ctx.beginPath();
        ctx.arc(sunX, sunY, Math.max(0, r1_sunGlow), 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness}%, ${sunAlpha})`;
      ctx.beginPath();
      ctx.arc(sunX, sunY, Math.max(0, sunRadius * (1 + corePulse * 0.3)), 0, Math.PI * 2);
      ctx.fill();

      const numRays = 12;
      for (let i = 0; i < numRays; i++) {
        const angle = (i / numRays) * Math.PI * 2 + Date.now() * 0.00001 * entropy; 
        const rayLength = sunRadius * lerp(0.8, 0.3, entropy);
        const rayWidth = lerp(5, 2, entropy) * (1 + Math.sin(Date.now()*0.001 + i*0.5) * 0.15 * entropy); 

        const startX = sunX + Math.cos(angle) * sunRadius * (1 + corePulse * 0.3);
        const startY = sunY + Math.sin(angle) * sunRadius * (1 + corePulse * 0.3);
        const endX = sunX + Math.cos(angle) * (sunRadius * (1 + corePulse * 0.3) + rayLength + (entropy > 0.7 ? (Math.random()-0.5)*rayLength*0.6 : 0) );
        const endY = sunY + Math.sin(angle) * (sunRadius * (1 + corePulse * 0.3) + rayLength + (entropy > 0.7 ? (Math.random()-0.5)*rayLength*0.6 : 0) );

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.strokeStyle = `hsla(${sunHue}, ${sunSaturation - 10}%, ${sunLightness + 15}%, ${sunAlpha * lerp(0.6, 0.2, entropy)})`;
        ctx.lineWidth = rayWidth;
        ctx.stroke();
      }
    };

    const drawMoon = (entropy: number) => {
      const moonRadius = Math.max(0, Math.min(width, height) * BASE_MOON_RADIUS_FACTOR);
      const moonOrbitRadius = Math.min(width, height) * 0.35;
      const moonOrbitAngle = Date.now() * 0.0001; 
      const moonX = width / 2 + Math.cos(moonOrbitAngle) * moonOrbitRadius;
      const moonY = height / 2 + Math.sin(moonOrbitAngle) * moonOrbitRadius;

      const phase = entropy; 
      const moonHue = lerp(200, entropy > 0.8 ? 0 : 45, entropy); 
      const moonSaturation = lerp(20, 50 + entropy * 30 , entropy);
      const moonLightness = lerp(80, 50 - entropy * 20, entropy);
      const moonAlpha = lerp(0.4, 0.9, entropy);

      ctx.save();
      ctx.fillStyle = `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness}%, ${moonAlpha})`;
      ctx.beginPath();
      ctx.arc(moonX, moonY, moonRadius, 0, Math.PI * 2);
      ctx.fill();

      if (phase < 1) { 
          ctx.fillStyle = `hsla(${moonHue}, ${moonSaturation-10}%, ${moonLightness - 30}%, ${moonAlpha * 0.9})`; 
          ctx.beginPath();
          const shadowAngleOffset = Math.PI * (1 - phase); 
          ctx.arc(moonX, moonY, moonRadius + 0.5, Math.PI/2 - shadowAngleOffset, Math.PI/2 + shadowAngleOffset, true); 
          ctx.arc(moonX + Math.cos(Math.PI/2 + shadowAngleOffset) * moonRadius *0.1 , moonY +  Math.sin(Math.PI/2 + shadowAngleOffset) * moonRadius*0.1, moonRadius, Math.PI/2 + shadowAngleOffset, Math.PI/2 - shadowAngleOffset, false); 

          ctx.closePath();
          ctx.fill();
      }

      const r0_moonGlow = Math.max(0, moonRadius * 0.8);
      const r1_moonGlow = Math.max(r0_moonGlow, moonRadius * 1.5);
      if (Number.isFinite(moonX) && Number.isFinite(moonY) && Number.isFinite(r0_moonGlow) && Number.isFinite(r1_moonGlow) && r1_moonGlow > 0) {
        const moonGlow = ctx.createRadialGradient(moonX, moonY, r0_moonGlow, moonX, moonY, r1_moonGlow);
        moonGlow.addColorStop(0, `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness + 10}%, ${moonAlpha * 0.3})`);
        moonGlow.addColorStop(1, `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness}%, 0)`);
        ctx.fillStyle = moonGlow;
        ctx.beginPath();
        ctx.arc(moonX, moonY, r1_moonGlow, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    };

    const drawPlanets = (entropy: number, sunX: number, sunY: number) => {
      planets.forEach(p => {
        p.currentAngle = (p.currentAngle + p.baseSpeed * lerp(1, 1 + (Math.random()-0.5)*2*entropy, entropy)) % (Math.PI * 2);
        p.effectiveSize = Math.max(0, p.baseSize * planetSizeFactorSetting * lerp(1.2, 0.5 + Math.random()*0.7, entropy));
        p.effectiveOpacity = lerp(0.9, 0.4 + Math.random()*0.5, entropy);
        p.wobbleX = Math.sin(Date.now() * 0.0002 * (p.id.charCodeAt(7)%5 +1)) * entropy * p.effectiveSize * 0.3;
        p.wobbleY = Math.cos(Date.now() * 0.00015 * (p.id.charCodeAt(8)%5 +1)) * entropy * p.effectiveSize * 0.3;
        p.isUnstable = entropy > 0.7 && Math.random() < entropy * 0.1; 

        if (p.isUnstable && Math.random() < 0.5) return; 

        const x = sunX + Math.cos(p.currentAngle) * p.orbitRadius + p.wobbleX;
        const y = sunY + Math.sin(p.currentAngle) * p.orbitRadius + p.wobbleY;

        const planetLightness = lerp(60, 30 + Math.random()*20, entropy);
        const planetSaturation = lerp(70, 40 + Math.random()*30, entropy);

        ctx.fillStyle = `hsla(${p.colorHue}, ${planetSaturation}%, ${planetLightness}%, ${p.effectiveOpacity})`;
        ctx.beginPath();
        ctx.arc(x, y, Math.max(1, p.effectiveSize), 0, Math.PI * 2);
        ctx.fill();

        if (entropy > 0.8 && p.effectiveSize > 3) {
            const numFragments = Math.floor(Math.random() * 3) + 2;
            for(let i=0; i < numFragments; i++) {
                const fragX = x + (Math.random() - 0.5) * p.effectiveSize * 0.8;
                const fragY = y + (Math.random() - 0.5) * p.effectiveSize * 0.8;
                const fragSize = p.effectiveSize * (Math.random() * 0.3 + 0.2);
                ctx.fillStyle = `hsla(${p.colorHue + (Math.random()-0.5)*40}, ${planetSaturation-10}%, ${planetLightness-10}%, ${p.effectiveOpacity * 0.7})`;
                ctx.beginPath();
                ctx.arc(fragX, fragY, Math.max(0.5, fragSize), 0, Math.PI * 2);
                ctx.fill();
            }
        }

        if (p.effectiveSize > 2) {
            const r0_atmos = Math.max(0, p.effectiveSize * 0.8);
            const r1_atmos = Math.max(r0_atmos, p.effectiveSize * 1.5);
            if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(r0_atmos) && Number.isFinite(r1_atmos) && r1_atmos > 0) {
              const atmosGrad = ctx.createRadialGradient(x,y, r0_atmos, x,y, r1_atmos);
              atmosGrad.addColorStop(0, `hsla(${p.colorHue + 20}, ${planetSaturation + 10}%, ${planetLightness + 10}%, ${p.effectiveOpacity * 0.3 * (1-entropy)})`);
              atmosGrad.addColorStop(1, `hsla(${p.colorHue + 40}, ${planetSaturation}%, ${planetLightness}%, 0)`);
              ctx.fillStyle = atmosGrad;
              ctx.beginPath();
              ctx.arc(x,y, r1_atmos, 0, Math.PI*2);
              ctx.fill();
            }
        }
      });
    };

    const render = () => {
      frameCount++;
      drawSky(currentEntropy);
      drawSun(currentEntropy, localSunPosition.x, localSunPosition.y);
      drawMoon(currentEntropy); 
      drawPlanets(currentEntropy, localSunPosition.x, localSunPosition.y);
      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [currentEntropy, width, height, planets, localSunPosition.x, localSunPosition.y, planetSizeFactorSetting]);

  const handleNumPlanetsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setNumPlanetsSetting(Number(event.target.value));
  };

  const handlePlanetSizeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setPlanetSizeFactorSetting(Number(event.target.value));
  };

  const handleRandomize = () => {
    initializePlanets(); 
  };

  return (
    <div className="celestial-entropy-cycle-panel bg-slate-950/80 backdrop-blur-md border border-yellow-500/30 rounded-xl shadow-2xl p-6 my-8 text-slate-100">
      <h2 className="text-2xl font-['Cinzel'] font-bold mb-4 text-center text-yellow-200 drop-shadow-[0_1px_1px_rgba(255,255,200,0.4)]">
        Celestial Entropy Resonator
      </h2>
      <div className="relative mx-auto mb-6" style={{ width: `${width}px`, height: `${height}px` }}>
        <canvas
          ref={canvasRef}
          className="rounded-lg border border-slate-700/30"
          aria-label="Sun, Moon, and Planets simulation based on entropy"
          role="img"
        />
      </div>
      <div className="controls-area grid grid-cols-1 md:grid-cols-3 gap-4 p-4 bg-slate-800/50 rounded-lg border border-slate-700">
        <div>
          <label htmlFor="numPlanets" className="block text-xs font-medium text-slate-300 mb-1">Number of Planets: {numPlanetsSetting}</label>
          <input
            type="range"
            id="numPlanets"
            min={MIN_PLANETS}
            max={MAX_PLANETS}
            value={numPlanetsSetting}
            onChange={handleNumPlanetsChange}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-yellow-500"
            aria-label="Number of planets"
          />
        </div>
        <div>
          <label htmlFor="planetSize" className="block text-xs font-medium text-slate-300 mb-1">Planet Size Factor: {planetSizeFactorSetting.toFixed(1)}x</label>
          <input
            type="range"
            id="planetSize"
            min="0.2"
            max="2.5"
            step="0.1"
            value={planetSizeFactorSetting}
            onChange={handlePlanetSizeChange}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-yellow-500"
            aria-label="Planet size factor"
          />
        </div>
        <div className="flex items-end">
          <button
            onClick={handleRandomize}
            className="w-full px-4 py-2 text-sm rounded-button bg-yellow-600 hover:bg-yellow-500 text-slate-900 font-semibold transition-colors focus:ring-2 focus:ring-yellow-400 focus:outline-none"
            aria-label="Randomize planetary system"
          >
            <i className="ri-refresh-line mr-2"></i>Randomize System
          </button>
        </div>
      </div>
    </div>
  );
};

export default CelestialEntropyCyclePanel;

import React, { useRef, useEffect, useMemo, useCallback, useState } from 'react';
import { GeoMode, VisualizationMatrixMode, type CosmicEntropyGeometryGeneratorProps as ExternalProps, type Particle, type PanelDisplayMode } from '../../types'; 
import ModeSelector from '../core/ModeSelector'; 
