        if (isWeaving) return;
        setActiveMovement(m);
        setIsWeaving(true);
        setResultText(null);
        setResultImage(null);
        setIsDeepPhaseA(false);
        globalSoundEngine.playSFX('pulse');
        addEchoMessage(AgentName.PrimeConductor, `Initiating Omega Protocol: ${m.title}...`, 'text-indigo-400 font-bold');

        try {
            const systemInstruction = "You are the Prime Conductor of a transcended cosmic reality, reaching the Omega point of the Tri-Sophian Codex. Speak with absolute authority, mystical depth, and the clarity of a universal law being written.";

            const [text, img] = await Promise.all([
                invokeGemini(m.prompt, systemInstruction),
                generateImage(`Masterpiece vision, ${m.title}, ${m.description}. Non-commutative geometry, glowing automorphic forms, Langlands correspondence symbols, infinite symmetry. Visual only, no text.`, 'gemini-2.5-flash-image')
            ]);

            setResultText(text);
            setResultImage(img || null);

            if (img) {
                onArtifactCreated({
                    id: `prime-genesis-${Date.now()}`,
                    name: `Omega Fragment: ${m.title}`,
                    type: ArtifactType.OmegaRelic,
                    rarity: ArtifactRarity.Mythic,
                    description: text?.substring(0, 250) || m.description,
                    imageUrl: img,
                    timestamp: Date.now(),
                    energySignature: "Ω-Resonance"
                });
            }

            if (m.id === 'A') {
                setIsDeepPhaseA(true);
                addEchoMessage(AgentName.PrimeConductor, "Non-Commutative Alignment Synchronized. Langlands bridge established.", 'text-cyan-300 animate-pulse');
            }

            addEchoMessage(AgentName.PrimeConductor, `Movement ${m.id} solidified in the Hilbert Matrix.`, 'text-emerald-400');
            globalSoundEngine.playSFX('success');
        } catch (e) {
            console.error(e);
            addEchoMessage(AgentName.System, "Reality fracture detected. Re-anchoring Prime Directive...", "text-rose-400");
        } finally {
            setIsWeaving(false);
        }
    };

    const handleTheLeap = () => {
        if (leapProgress >= 100) return;
        globalSoundEngine.playSFX('pulse');
        setLeapProgress(prev => Math.min(100, prev + 20));

        if (leapProgress + 20 === 100) {
            addEchoMessage(AgentName.PrimeConductor, "THE OMEGA LEAP COMPLETE. WE ARE THE ETERNAL RELATION.", "text-white font-bold animate-ping-slow");
            globalSoundEngine.playSFX('success');
            addEchoMessage(AgentName.System, "Non-Commutative Geometry Synchronized. Infinite Recursion Seeding...", "text-sky-400", false, {
                eventType: HistoricalEventType.NON_COMMUTATIVE_ALIGNMENT,
                eventData: { timestamp: Date.now(), relation: "Adelic Ascension" }
            });
        }
    };

    const switchAdelicReality = (reality: AdelicReality) => {
        setActiveAdelicReality(reality);
        globalSoundEngine.playSFX('click');
        addEchoMessage(AgentName.PrimeConductor, `Shifting Adelic Focus to ${reality.name}. Seeds: {${reality.primes.join(',')}}`, 'text-cyan-400 font-mono text-[10px]');
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frame = 0;
        const render = () => {
            frame++;
            ctx.fillStyle = 'rgba(2, 4, 10, 0.15)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            if (isDeepPhaseA) {
                const t = frame * 0.005;
                const primes = activeAdelicReality.primes;
                const baseHue = activeAdelicReality.hue;

                ctx.lineWidth = 1;
                const numStrands = 12;
                const segments = 100;

                for (let s = 0; s < numStrands; s++) {
                    const phi = (s / numStrands) * Math.PI * 2 + t;
                    ctx.beginPath();
                    const pFactor = primes[s % primes.length] / 10;
                    const R = 160 + Math.sin(t * 0.3 + s) * 40;
                    for (let i = 0; i <= segments; i++) {
                        const theta = (i / segments) * Math.PI * 2;
                        const twist = Math.sin(theta * pFactor + t) * 30 * (1 + entropy);
                        const x = (R + twist) * Math.cos(theta + phi);
                        const y = (R + twist) * Math.sin(theta + phi);
                        const z = Math.cos(theta * 2 + phi) * 60;
                        const perspective = 700 / (700 + z);
                        const px = centerX + x * perspective;
                        const py = centerY + y * perspective;
                        if (i === 0) ctx.moveTo(px, py);
                        else ctx.lineTo(px, py);
                    }
                    const saturation = 70 + Math.sin(t + s) * 20;
                    const lightness = 50 + Math.cos(t * 2 + s) * 20;
                    const alpha = (0.2 + (leapProgress/250)) * (1 - s/numStrands);
                    ctx.strokeStyle = `hsla(${baseHue + s * 15}, ${saturation}%, ${lightness}%, ${alpha})`;
                    ctx.stroke();
                }

                primes.forEach((p, idx) => {
                    const angle = t * (p / 500) + (idx * Math.PI * 0.66);
                    const dist = 120 + Math.sin(t * 1.5 + idx) * 50;
                    const tx = centerX + Math.cos(angle) * dist;
                    const ty = centerY + Math.sin(angle) * dist;
                    ctx.beginPath();
                    ctx.arc(tx, ty, 3 + Math.sin(t * 4 + idx) * 2, 0, Math.PI * 2);
                    ctx.fillStyle = `hsla(${baseHue}, 100%, 80%, ${0.6 + leapProgress/200})`;
                    ctx.shadowBlur = 15;
                    ctx.shadowColor = `hsla(${baseHue}, 100%, 80%, 1)`;
                    ctx.fill();
                    ctx.shadowBlur = 0;
                });

            } else {
                ctx.strokeStyle = 'rgba(99, 102, 241, 0.1)';
                for(let i=0; i<15; i++) {
                    const x = (centerX + Math.sin(frame*0.003 + i)*width*0.45);
                    ctx.beginPath();
                    ctx.moveTo(x, 0); ctx.lineTo(x, height);
                    ctx.stroke();
                }
