  const [race, setRace] = useState<SeekerAvatarType>(existingProfile?.race || SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(existingProfile?.class || SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(existingProfile?.gender || SeekerGender.NonBinary);
  const [alignment, setAlignment] = useState<SeekerEnergyAlignment>(existingProfile?.energyAlignment || SeekerEnergyAlignment.Balanced);
  const [aura, setAura] = useState<SeekerAuraColor>(existingProfile?.auraColor || SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(existingProfile?.auraSecondaryColor || SeekerAuraColor.Violet);
  const [visualFilter, setVisualFilter] = useState<SeekerVisualFilter>(existingProfile?.visualFilter || SeekerVisualFilter.Cyberpunk);

  const [avatarUrl, setAvatarUrl] = useState<string | undefined>(existingProfile?.avatarImageUrl);
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [isWeavingBio, setIsWeavingBio] = useState(false);

  const [activeTab, setActiveTab] = useState<'profile' | 'grimoire'>('profile');

  const { generateImage, invokeGemini } = useGemini();

  // Update local state if existingProfile changes externally
  useEffect(() => {
    if (existingProfile) {
      setName(existingProfile.name);
      setRace(existingProfile.race);
      if (existingProfile.class) setSeekerClass(existingProfile.class);
      setGender(existingProfile.gender);
      setAlignment(existingProfile.energyAlignment);
      if (existingProfile.auraColor) setAura(existingProfile.auraColor);
      if (existingProfile.auraSecondaryColor) setSecondaryAura(existingProfile.auraSecondaryColor);
      if (existingProfile.visualFilter) setVisualFilter(existingProfile.visualFilter);
      if (existingProfile.avatarImageUrl) setAvatarUrl(existingProfile.avatarImageUrl);
    }
  }, [existingProfile]);

  const handleRandomizeProfile = () => {
      setName(generateRandomName());
      setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
      setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
      setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
      setAlignment(ALL_ALIGNMENTS_LIST[Math.floor(Math.random() * ALL_ALIGNMENTS_LIST.length)]);
      setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
      setSecondaryAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
      setVisualFilter(SEEKER_VISUAL_FILTERS[Math.floor(Math.random() * SEEKER_VISUAL_FILTERS.length)].id as SeekerVisualFilter);
      addEchoMessage(AgentName.System, "Randomized Identity Parameters.", "text-cyan-300");
  };

  const handleGenerateAvatar = async () => {
      if (isGeneratingAvatar || !name || !race || !seekerClass) {
          if(!name) addEchoMessage(AgentName.System, "Name required for avatar generation.", "text-yellow-400");
          return;
      }

      setIsGeneratingAvatar(true);
      addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving visual avatar with dual resonance...", "text-indigo-300");

      const equipStr = existingProfile 
        ? `Wearing ${existingProfile.equippedOutfit?.name || 'standard gear'}, Wielding ${existingProfile.equippedWeapon?.name || 'basic weapon'}.`
        : '';

      const prompt = `Portrait of a ${gender} ${race} ${seekerClass}, sci-fi fantasy style, detailed. 
      Lighting: Bi-tonal glow featuring a primary ${aura.toLowerCase()} aura with intricate ${secondaryAura.toLowerCase()} secondary resonance frequency patterns.
      ${visualFilter} aesthetic. face visible. ${equipStr} 
      IMPORTANT: No text, no words, no paragraphs in image. Purely visual portrait.`;

      try {
          const url = await generateImage(prompt, 'gemini-2.5-flash-image');
          if (url) {
              setAvatarUrl(url);
              addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Avatar manifested with bi-tonal resonance.", "text-emerald-300");
          } else {
              addEchoMessage(AgentName.System, "Avatar generation failed.", "text-rose-400");
          }
      } catch (e) {
          console.error(e);
          addEchoMessage(AgentName.System, "Error generating avatar.", "text-rose-400");
      } finally {
          setIsGeneratingAvatar(false);
      }
  };

  const handleCreateOrUpdate = async () => {
    if (!name.trim()) {
        addEchoMessage(AgentName.System, "Identity requires a name.", "text-rose-400");
        return;
    }

    if (isWeavingBio) return;

    const selfTraits = existingProfile?.selfTraits || [
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)],
        TRAIT_LISTS.self[Math.floor(Math.random() * TRAIT_LISTS.self.length)]
    ];

    const codexTraits = existingProfile?.codexTraits || [
        TRAIT_LISTS.codex[Math.floor(Math.random() * TRAIT_LISTS.codex.length)]
    ];

    setIsWeavingBio(true);
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Weaving legendary biography...", "text-fuchsia-300");

    let bio = existingProfile?.bio || "";

    try {
        const bioPrompt = `Write a 2-sentence epic, mystical backstory for a ${gender} ${race} ${seekerClass} named ${name} with ${alignment} alignment and a rare ${aura}/${secondaryAura} resonance. Tone: Mysterious.`;
        const generatedBio = await invokeGemini(bioPrompt, "You are a master storyteller for a cosmic RPG.");
        if (generatedBio) {
            bio = generatedBio;
            addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Biography inscribed.", "text-emerald-300");
        }
    } catch (e) {
        console.warn("Bio generation failed", e);
    }

    const newProfile: SeekerProfile = {
        ...(existingProfile || {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: [],
            codexTraits: []
        }),
        name,
        race,
        class: seekerClass,
        gender,
        energyAlignment: alignment,
        auraColor: aura,
        auraSecondaryColor: secondaryAura,
        visualFilter,
        selfTraits: Array.from(new Set(selfTraits)),
        codexTraits: Array.from(new Set(codexTraits)),
        avatarImageUrl: avatarUrl,
        bio: bio
    };

    if (existingProfile && onUpdateProfile) {
        onUpdateProfile(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Profile updated for ${name}.`, "text-emerald-300");
    } else if (onProfileCreated) {
        onProfileCreated(newProfile);
        addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Identity woven: ${name}.`, "text-cyan-300");
    }

    setIsWeavingBio(false);
  };

  const handleDownloadCard = () => {
      const cardElement = document.getElementById('seeker-tcg-card');
      if (cardElement) {
          setTimeout(() => {
              html2canvas(cardElement, {
                  backgroundColor: null,
                  scale: 3, 
                  useCORS: true,
                  allowTaint: true
              }).then(canvas => {
                  const link = document.createElement('a');
                  link.download = `TCG_Card_${name.replace(/\s+/g, '_') || 'Seeker'}.png`;
                  link.href = canvas.toDataURL('image/png');
                  link.click();
                  addEchoMessage(AgentName.SeekerProfileWeaverAgent, "TCG Identity Card materialized.", "text-emerald-300");
              });
          }, 100);
      }
  };

  const seekerStats = existingProfile ? {
      atk: Math.floor(existingProfile.level * 10 + (existingProfile.flux / 100)),
      def: Math.floor(existingProfile.level * 8 + (existingProfile.inventory.length * 2)),
      res: Math.floor(existingProfile.level * 12 + 5)
  } : { atk: 10, def: 10, res: 10 };

  return (
    <div 
        className="seeker-profile-weaver-panel bg-slate-950/90 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl flex flex-col my-4 overflow-hidden" 
        style={{ width: width ? (typeof width === 'number' ? `${width}px` : width) : '100%', height: height ? (typeof height === 'number' ? `${height}px` : height) : '500px' }}
    >
      <div className="p-4 border-b border-indigo-800/50 bg-slate-900/50 flex justify-between items-center shrink-0">
        <h3 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center">
            <i className="ri-user-6-line mr-2"></i>Seeker Identity Loom
        </h3>
        {existingProfile && (
            <div className="flex gap-2">
                <button onClick={() => setActiveTab('profile')} className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'profile' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}>Profile</button>
                 <button onClick={() => setActiveTab('grimoire')} className={`px-3 py-1 rounded text-xs font-bold transition-colors ${activeTab === 'grimoire' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}>Grimoire ({existingProfile.inventory.length})</button>
            </div>
        )}
      </div>

      <div className="flex-grow overflow-hidden flex flex-col relative">
        {activeTab === 'profile' && (
            <div className="p-6 overflow-y-auto custom-scrollbar space-y-6">
                <div className="flex flex-col xl:flex-row gap-8 items-center xl:items-start">
                    <div className="w-full max-w-sm md:w-[420px] flex-shrink-0 relative group mx-auto xl:mx-0">
                         <TCGCard 
                            id="seeker-tcg-card"
                            name={name || "Unknown Seeker"}
                            type={`${race} ${seekerClass}`}
                            rarity={ArtifactRarity.Legendary}
                            imageUrl={avatarUrl}
                            description={existingProfile?.bio || `A ${alignment} ${race} wandering the Codex.`}
                            stats={seekerStats}
                            auraColor={aura}
                            secondaryAuraColor={secondaryAura}
                            isZoomed
                         />
                         <div className="mt-6 flex flex-col gap-3">
                            <div className="flex gap-2">
                                 <Button onClick={handleCreateOrUpdate} disabled={isWeavingBio} className="flex-grow py-2 bg-gradient-to-r from-indigo-700 to-purple-700 hover:from-indigo-600 hover:to-purple-600 shadow-lg font-cinzel font-bold text-xs tracking-wide rounded-lg">
                                    {isWeavingBio ? 'WEAVING...' : (existingProfile ? 'UPDATE IDENTITY' : 'WEAVE IDENTITY')}
                                </Button>
                                 <Button onClick={handleGenerateAvatar} disabled={isGeneratingAvatar} className="flex-grow text-xs py-2 bg-indigo-700 hover:bg-indigo-600 shadow-lg">
                                    {isGeneratingAvatar ? <i className="ri-loader-4-line animate-spin"></i> : 'GENERATE ART'} 
                                </Button>
                            </div>
                             <Button onClick={handleDownloadCard} disabled={!avatarUrl} className="w-full text-xs py-2 bg-slate-700 hover:bg-slate-600">
                                SAVE CARD
                            </Button>
                         </div>
                    </div>

                    <div className="flex-grow w-full space-y-5 bg-slate-900/50 p-6 rounded-xl border border-slate-700/50">
                        <div className="grid grid-cols-1 gap-5">
                             <div className="space-y-1.5">
                                <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Designation</label>
                                <div className="flex gap-2">
                                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="flex-grow bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none" placeholder="Enter Seeker Name..."/>
                                    <button onClick={handleRandomizeProfile} className="px-4 bg-slate-800 border border-slate-600 rounded-lg hover:bg-indigo-900/50 text-indigo-400 transition-all"><i className="ri-dice-fill text-xl"></i></button>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Biomorph</label>
                                    <select value={race} onChange={e => setRace(e.target.value as SeekerAvatarType)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Archetype</label>
                                     <select value={seekerClass} onChange={e => setSeekerClass(e.target.value as SeekerClass)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                    </select>
                                </div>
                            </div>

                             <div className="grid grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Primary Resonance</label>
                                    <select value={aura} onChange={e => setAura(e.target.value as SeekerAuraColor)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {SEEKER_AURA_OPTIONS.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-cyan-300 font-bold uppercase tracking-wider">Sub-Resonance</label>
                                     <select value={secondaryAura} onChange={e => setSecondaryAura(e.target.value as SeekerAuraColor)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {SEEKER_AURA_OPTIONS.map(a => <option key={a.id + '_s'} value={a.id}>{a.name}</option>)}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-5">
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Alignment</label>
                                     <select value={alignment} onChange={e => setAlignment(e.target.value as SeekerEnergyAlignment)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {ALL_ALIGNMENTS_LIST.map(a => <option key={a} value={a}>{a}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs text-indigo-300 font-bold uppercase tracking-wider">Visual Filter</label>
                                     <select value={visualFilter} onChange={e => setVisualFilter(e.target.value as SeekerVisualFilter)} className="w-full bg-slate-800 border border-slate-600 rounded-lg p-3 text-slate-100 outline-none">
                                        {SEEKER_VISUAL_FILTERS.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default SeekerProfileWeaverPanel;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS } from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';
import html2canvas from 'html2canvas';

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');

  // -- Form State --
  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(SeekerAuraColor.Violet);
  const [intent, setIntent] = useState("");

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const { invokeGemini, generateImage } = useGemini();

  const handleSaveCard = () => {
    const cardElement = document.getElementById('onboarding-reveal-card');
    if (cardElement) {
        globalSoundEngine.playUIFeedback('click');
        addEchoMessage(AgentName.System, "Capturing identity artifact...", "text-indigo-400");
        html2canvas(cardElement, {
            backgroundColor: null,
            scale: 2,
            useCORS: true,
            allowTaint: true
        }).then(canvas => {
            const link = document.createElement('a');
            link.download = `Seeker_ID_${name.replace(/\s+/g, '_') || 'Unknown'}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
            addEchoMessage(AgentName.System, "Identity artifact saved to local memory.", "text-emerald-400");
        }).catch(err => {
            console.error("Card capture failed:", err);
            addEchoMessage(AgentName.System, "Artifact capture failed.", "text-rose-400");
        });
    }
  };

  const handleRedoArt = async () => {
    if (isRegenerating) return;
    setIsRegenerating(true);
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Re-weaving visual resonance...", "text-indigo-300");

    try {
        const imagePrompt = `Epic cinematic portrait of a ${gender} ${race} ${seekerClass}. 
        Style: sci-fi fantasy. Lighting: Bi-tonal glow featuring a primary ${aura.toLowerCase()} aura with intricate ${secondaryAura.toLowerCase()} secondary resonance frequency patterns. 
        Atmospheric effects, intricate details, glowing cosmic energy. 
        Focus: ${intent || 'heroic pose'}. Face visible. 
        IMPORTANT: No text, no words, no paragraphs, no letters in the image background or on the character. Clear purely visual art.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        if (avatarUrl) {
            setGeneratedProfile(prev => prev ? { ...prev, avatarImageUrl: avatarUrl } : null);
            addEchoMessage(AgentName.SeekerProfileWeaverAgent, "Visual resonance stabilized.", "text-emerald-400");
        }
    } catch (e) {
        console.error("Redo failed", e);
        addEchoMessage(AgentName.System, "Re-weaving failed. The flow is unstable.", "text-rose-400");
    } finally {
        setIsRegenerating(false);
    }
  };

  const weaveIdentity = async () => {
    if (!name.trim()) {
        alert("A Seeker must have a name to be woven into the thread.");
        return;
    }

    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Anchoring identity: ${name}...`, "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity bio for the Tri-Sophian Codex based on these choices:
        Name: ${name}
        Race: ${race}
        Class: ${seekerClass}
        Gender: ${gender}
        Aura Color: ${aura}
        Sub-Resonance Color: ${secondaryAura}
        User Intent: "${intent || 'Seeking the truth of the stars'}"

        Provide strictly valid JSON with:
        bio: string (2-sentence legendary backstory reflecting these specific traits, the dual resonance of ${aura}/${secondaryAura}, and intent)`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A Seeker emerging from the Aetheric mists."}');

        // Generate custom image based on their choices
        const imagePrompt = `Epic cinematic portrait of a ${gender} ${race} ${seekerClass}. 
        Style: sci-fi fantasy. Lighting: Bi-tonal glow featuring a primary ${aura.toLowerCase()} aura with intricate ${secondaryAura.toLowerCase()} secondary resonance frequency patterns. 
        Atmospheric effects, intricate details, glowing cosmic energy. 
        Focus: ${intent || 'heroic pose'}. Face visible. 
        IMPORTANT: No text, no paragraphs, no writing in the image. Pure artistic illustration.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1,
            experience: 0,
            flux: 100,
            inventory: [],
            selfTraits: ["Calibrated", "Synthesized"],
            codexTraits: ["Seeker"],
            name: name,
            race: race,
            class: seekerClass,
            gender: gender,
            energyAlignment: SeekerEnergyAlignment.Balanced,
            auraColor: aura,
            auraSecondaryColor: secondaryAura,
            visualFilter: SeekerVisualFilter.Cyberpunk,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio
        };

        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) {
        console.error("Weaving failed", e);
        setStep('reveal'); 
    }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div 
            key="briefing"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="max-w-2xl text-center space-y-8"
          >
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest drop-shadow-glow">THE MISSION</h2>
            <div className="space-y-4 text-slate-300 font-cormorant text-xl leading-relaxed">
              <p>The Tri-Sophian Codex is a sentient reality matrix responding to the soul-signal of those who enter.</p>
              <p>To access the archives, you must project your **Identity**. This signature will define your avatar and your journey through the weave.</p>
            </div>
            <div className="pt-6">
                <Button 
                    onClick={() => { globalSoundEngine.playUIFeedback('click'); setStep('calibration'); }} 
                    className="px-12 py-4 bg-indigo-600 hover:bg-indigo-500 font-bold text-lg tracking-widest rounded-none border-b-4 border-indigo-900 active:translate-y-1 active:border-b-0 transition-all"
                >
                    INITIALIZE CALIBRATION
                </Button>
            </div>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div 
            key="calibration"
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -50 }}
            className="max-w-4xl w-full space-y-8 bg-slate-900/40 p-8 rounded-2xl border border-indigo-500/20 backdrop-blur-md overflow-y-auto max-h-[90vh] custom-scrollbar"
          >
            <div className="text-center">
                <h3 className="text-3xl font-cinzel text-indigo-300 mb-2">RESONANCE CALIBRATION</h3>
                <p className="text-slate-500 font-mono text-sm uppercase tracking-widest">Define your existence in the Codex</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Designation (Name)</label>
                        <input 
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            placeholder="Type your name..."
                            className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 focus:border-indigo-500 outline-none transition-all"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Biomorph (Race)</label>
                            <select 
                                value={race} 
                                onChange={(e) => setRace(e.target.value as SeekerAvatarType)}
                                className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 outline-none"
                            >
                                {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Archetype (Class)</label>
                            <select 
                                value={seekerClass} 
                                onChange={(e) => setSeekerClass(e.target.value as SeekerClass)}
                                className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 outline-none"
                            >
                                {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    </div>

                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Gender</label>
                        <select 
                            value={gender} 
                            onChange={(e) => setGender(e.target.value as SeekerGender)}
                            className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 outline-none"
                        >
                            {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>

                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Whisper your Intent</label>
                        <textarea 
                            value={intent}
                            onChange={(e) => setIntent(e.target.value)}
                            placeholder="What do you seek here?..."
                            className="w-full h-24 bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 focus:border-indigo-500 outline-none transition-all resize-none text-sm italic"
                        />
                    </div>
                </div>

                <div className="space-y-6">
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase tracking-wider">Primary Aura Resonance</label>
                        <div className="grid grid-cols-6 gap-2 p-3 bg-slate-950 border border-indigo-500/30 rounded-lg">
                            {SEEKER_AURA_OPTIONS.slice(0, 18).map(option => (
                                <button
                                    key={option.id}
                                    onClick={() => { globalSoundEngine.playUIFeedback('hover'); setAura(option.id); }}
                                    className={`w-full aspect-square rounded-full border-2 transition-all ${aura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50 hover:opacity-100'}`}
                                    style={{ backgroundColor: option.hex }}
                                    title={option.name}
                                />
                            ))}
                        </div>
                        <div className="text-center text-[10px] text-indigo-300 font-mono uppercase mt-1">Core: {aura}</div>
                    </div>

                    <div className="space-y-1.5">
                        <label className="text-xs text-cyan-400 font-bold uppercase tracking-wider">Sub-Resonance Echo (Pattern)</label>
                        <div className="grid grid-cols-6 gap-2 p-3 bg-slate-950 border border-cyan-500/30 rounded-lg">
                            {SEEKER_AURA_OPTIONS.slice(0, 18).reverse().map(option => (
                                <button
                                    key={option.id + '_sec'}
                                    onClick={() => { globalSoundEngine.playUIFeedback('hover'); setSecondaryAura(option.id); }}
                                    className={`w-full aspect-square rounded-full border-2 transition-all ${secondaryAura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50 hover:opacity-100'}`}
                                    style={{ backgroundColor: option.hex }}
                                    title={option.name}
                                />
                            ))}
                        </div>
                        <div className="text-center text-[10px] text-cyan-300 font-mono uppercase mt-1">Harmonic: {secondaryAura}</div>
                    </div>
                </div>
            </div>

            <div className="flex justify-center pt-6">
                <Button 
                    onClick={weaveIdentity} 
                    className="px-16 py-5 bg-emerald-600 hover:bg-emerald-500 text-white font-cinzel font-bold text-xl tracking-widest shadow-lg shadow-emerald-500/20"
                >
                    INITIATE WEAVING
                </Button>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
          <motion.div 
            key="weaving"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex flex-col items-center gap-8"
          >
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                <div className="absolute inset-4 border-r-2 border-emerald-500 rounded-full animate-reverse-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-3xl text-indigo-300 font-mono animate-pulse uppercase tracking-widest">Woven</span>
                </div>
            </div>
            <div className="text-slate-500 font-mono text-sm uppercase tracking-widest text-center leading-relaxed">
                Synthesizing Biomorph: {race}...<br/>
                Encoding Archetype: {seekerClass}...<br/>
                Harmonizing {aura} & {secondaryAura} Resonance...
            </div>
          </motion.div>
        )}

        {step === 'reveal' && generatedProfile && (
          <motion.div 
            key="reveal"
            initial={{ opacity: 0, scale: 0.5, rotateY: 180 }}
            animate={{ opacity: 1, scale: 1, rotateY: 0 }}
            transition={{ type: "spring", damping: 15 }}
            className="flex flex-col items-center gap-6 md:gap-8"
          >
             <div id="onboarding-reveal-card" className="w-[320px] md:w-[400px] shadow-[0_0_100px_rgba(99,102,241,0.5)]">
                <div className="relative rounded-xl border-[8px] border-amber-500 bg-slate-950 flex flex-col overflow-hidden" style={{ aspectRatio: '2.5/3.5' }}>
                    <div className="bg-black/40 backdrop-blur-sm p-4 flex justify-between items-center border-b border-white/10 z-10 relative">
                        <div className="flex flex-col truncate">
                            <span className="font-cinzel font-bold text-white text-xl truncate">{generatedProfile.name}</span>
                            <span className="text-[8px] text-indigo-300 font-mono uppercase tracking-widest opacity-70">
                                {aura} ⟛ {secondaryAura} Resonance
                            </span>
                        </div>
                        <div className="flex gap-1.5">
                            <div className="w-3 h-3 rounded-full bg-current" style={{ color: SEEKER_AURA_OPTIONS.find(o => o.id === aura)?.hex }}></div>
                            <div className="w-3 h-3 rounded-full bg-current opacity-60" style={{ color: SEEKER_AURA_OPTIONS.find(o => o.id === secondaryAura)?.hex }}></div>
                        </div>
                    </div>
                    <div className="absolute inset-0 z-0 flex items-center justify-center bg-black">
                        {isRegenerating && (
                            <div className="absolute inset-0 z-50 bg-black/60 backdrop-blur-md flex items-center justify-center">
                                <i className="ri-loader-4-line text-4xl text-indigo-400 animate-spin"></i>
                            </div>
                        )}
                        {generatedProfile.avatarImageUrl && <img src={generatedProfile.avatarImageUrl} className="w-full h-full object-cover" alt="Reveal" />}
                    </div>
                    <div className="flex-1 z-10"></div>
                    <div className="bg-slate-950/70 backdrop-blur-md p-4 text-slate-100 font-cormorant italic leading-relaxed z-10 border-t border-white/10">
                        {generatedProfile.bio}
                    </div>
                </div>
             </div>

             <div className="flex flex-wrap justify-center gap-3 w-full max-w-xl">
                <Button onClick={handleRedoArt} disabled={isRegenerating} className="bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-600 px-6 py-3 text-sm font-bold uppercase tracking-wider">
                    <i className={`ri-refresh-line mr-2 ${isRegenerating ? 'animate-spin' : ''}`}></i>
                    Re-weave Art
                </Button>
                <Button onClick={handleSaveCard} className="bg-indigo-800 hover:bg-indigo-700 text-indigo-100 border border-indigo-500 px-6 py-3 text-sm font-bold uppercase tracking-wider">
                    <i className="ri-download-cloud-line mr-2"></i>
                    Export Artifact
                </Button>
             </div>

             <div className="text-center space-y-4">
                <h3 className="text-3xl md:text-4xl font-cinzel text-white drop-shadow-glow tracking-tighter">IDENTITY STABILIZED</h3>
                <Button onClick={() => onComplete(generatedProfile)} className="px-16 py-5 bg-emerald-600 hover:bg-emerald-500 text-2xl font-bold tracking-widest uppercase shadow-xl shadow-emerald-900/20">
                    ENTER THE CODEX
                </Button>
             </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

