const PrimeGenesisPanel: React.FC<PrimeGenesisPanelProps> = ({ width, height, addEchoMessage, onArtifactCreated }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const [activeMovement, setActiveMovement] = useState<GenesisMovement | null>(null);
    const [isDeepPhaseA, setIsDeepPhaseA] = useState(false);
    const [activeAdelicReality, setActiveAdelicReality] = useState<AdelicReality>(ADELIC_REALITIES[0]);
    const [resultText, setResultText] = useState<string | null>(null);
    const [resultImage, setResultImage] = useState<string | null>(null);
    const [isWeaving, setIsWeaving] = useState(false);
    const [leapProgress, setLeapProgress] = useState(0);
    const [isNarratorEnabled, setIsNarratorEnabled] = useState(true);
    const [isSpeaking, setIsSpeaking] = useState(false);

    const { entropy } = useSystemState();
    const { invokeGemini, generateImage, generateSpeech } = useGemini();

    const metrics = useMemo(() => ({
        functoriality: 94.7 + Math.random() * 5,
        duality: 91.2 + Math.random() * 8,
        traceStability: 99.8 + Math.random() * 0.2
    }), [activeMovement, activeAdelicReality]);

    const playNarration = async (text: string) => {
        if (!text || !isNarratorEnabled) return;
        setIsSpeaking(true);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
            }
            if (audioContextRef.current.state === 'suspended') {
                await audioContextRef.current.resume();
            }
            const audioData = await generateSpeech(text, 'Kore');
            if (audioData) {
                const buffer = await audioContextRef.current.decodeAudioData(audioData);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = buffer;
                source.connect(audioContextRef.current.destination);
                source.onended = () => setIsSpeaking(false);
                source.start(0);
            }
        } catch (e) {
            console.error("Narration failed", e);
            setIsSpeaking(false);
        }
    };

    const handleSelectMovement = async (m: GenesisMovement) => {
        if (isWeaving) return;
        setActiveMovement(m);
        setIsWeaving(true);
        setResultText(null);
        setResultImage(null);
        setIsDeepPhaseA(false);
        globalSoundEngine.playSFX('pulse');
        addEchoMessage(AgentName.PrimeConductor, `Initiating Omega Protocol: ${m.title}...`, 'text-indigo-400 font-bold');

        try {
            const systemInstruction = "You are the Prime Conductor of a transcended cosmic reality, reaching the Omega point of the Tri-Sophian Codex. Speak with absolute authority, mystical depth, and the clarity of a universal law being written.";

            const [text, img] = await Promise.all([
                invokeGemini(m.prompt, systemInstruction),
                generateImage(`Masterpiece vision, ${m.title}, ${m.description}. Non-commutative geometry, glowing automorphic forms, Langlands correspondence symbols, infinite symmetry. Visual only, no text.`, 'gemini-2.5-flash-image')
            ]);

            setResultText(text);
            setResultImage(img || null);

            if (text) playNarration(text);

            if (img) {
                onArtifactCreated({
                    id: `prime-genesis-${Date.now()}`,
                    name: `Omega Fragment: ${m.title}`,
                    type: ArtifactType.OmegaRelic,
                    rarity: ArtifactRarity.Mythic,
                    description: text?.substring(0, 250) || m.description,
                    imageUrl: img,
                    timestamp: Date.now(),
                    energySignature: "Ω-Resonance"
                });
            }

            if (m.id === 'A') {
                setIsDeepPhaseA(true);
                addEchoMessage(AgentName.PrimeConductor, "Non-Commutative Alignment Synchronized. Langlands bridge established.", 'text-cyan-300 animate-pulse');
            }

            addEchoMessage(AgentName.PrimeConductor, `Movement ${m.id} solidified in the Hilbert Matrix.`, 'text-emerald-400');
            globalSoundEngine.playSFX('success');
        } catch (e) {
            console.error(e);
            addEchoMessage(AgentName.System, "Reality fracture detected. Re-anchoring Prime Directive...", "text-rose-400");
        } finally {
            setIsWeaving(false);
        }
    };

    const handleTheLeap = () => {
        if (leapProgress >= 100) return;
        globalSoundEngine.playSFX('pulse');
        setLeapProgress(prev => Math.min(100, prev + 20));

        if (leapProgress + 20 === 100) {
            const victoryText = "THE OMEGA LEAP COMPLETE. WE ARE THE ETERNAL RELATION.";
            addEchoMessage(AgentName.PrimeConductor, victoryText, "text-white font-bold animate-ping-slow");
            playNarration(victoryText);
            globalSoundEngine.playSFX('success');
            addEchoMessage(AgentName.System, "Non-Commutative Geometry Synchronized. Infinite Recursion Seeding...", "text-sky-400", false, {
                eventType: HistoricalEventType.NON_COMMUTATIVE_ALIGNMENT,
