import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS, SEEKER_VISUAL_FILTERS } from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';
import html2canvas from 'html2canvas';

// --- Random Name Generator Data ---
const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');

  // -- Form State --
  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(SeekerAuraColor.Violet);
  const [intent, setIntent] = useState("");

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const { invokeGemini, generateImage } = useGemini();

  const handleRandomize = () => {
    globalSoundEngine.playUIFeedback('click');
    setName(generateRandomName());
    setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
    setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
    setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
    setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setSecondaryAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    addEchoMessage(AgentName.System, "Randomized Identity Resonance.", "text-cyan-400");
  };

  const weaveIdentity = async () => {
    if (!name.trim()) {
        alert("A Seeker must have a name to be woven into the thread.");
        return;
    }
    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Anchoring identity: ${name}...`, "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity bio for the Tri-Sophian Codex based on these choices:
        Name: ${name} | Race: ${race} | Class: ${seekerClass} | Aura: ${aura}/${secondaryAura} | Intent: "${intent || 'Unknown'}"
        Provide strictly valid JSON with key "bio": string (2-sentence backstory).`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A Seeker emerging from the Aetheric mists."}');
        const imagePrompt = `Cinematic portrait, ${gender} ${race} ${seekerClass}, aura ${aura}/${secondaryAura}. ${intent}. No text.`;
        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1, experience: 0, flux: 100, inventory: [],
            selfTraits: ["Calibrated"], codexTraits: ["Seeker"],
            name, race, class: seekerClass, gender,
            energyAlignment: SeekerEnergyAlignment.Balanced,
            auraColor: aura, auraSecondaryColor: secondaryAura,
            visualFilter: SeekerVisualFilter.Standard,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio
        };
        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) { setStep('reveal'); }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div key="briefing" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }} className="max-w-2xl text-center space-y-8">
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest drop-shadow-glow">THE MISSION</h2>
            <p className="text-slate-300 font-cormorant text-xl">The Tri-Sophian Codex responds to the soul-signal of those who enter. Project your **Identity** to begin.</p>
            <Button onClick={() => setStep('calibration')} className="px-12 py-4 bg-indigo-600 font-bold text-lg tracking-widest">INITIALIZE CALIBRATION</Button>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div key="calibration" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -50 }} className="max-w-4xl w-full space-y-8 bg-slate-900/40 p-8 rounded-2xl border border-indigo-500/20 backdrop-blur-md overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div className="flex justify-between items-center">
                <h3 className="text-3xl font-cinzel text-indigo-300">RESONANCE CALIBRATION</h3>
                <button onClick={handleRandomize} className="px-4 py-2 bg-indigo-950 border border-indigo-500/50 rounded-lg text-indigo-400 hover:text-white transition-all shadow-lg animate-pulse" title="Randomize All Parameters">
                    <i className="ri-dice-fill mr-2"></i>ROLL THE FATES
                </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase">Designation (Name)</label>
                        <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase">Biomorph (Race)</label>
                            <select value={race} onChange={(e) => setRace(e.target.value as SeekerAvatarType)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100">
                                {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase">Archetype (Class)</label>
                            <select value={seekerClass} onChange={(e) => setSeekerClass(e.target.value as SeekerClass)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100">
                                {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase">Gender</label>
                        <select value={gender} onChange={(e) => setGender(e.target.value as SeekerGender)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100">
                            {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase">Whisper your Intent</label>
                        <textarea value={intent} onChange={(e) => setIntent(e.target.value)} className="w-full h-24 bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 resize-none text-sm italic" />
                    </div>
                </div>
                <div className="space-y-6">
                    <div className="space-y-1.5">
                        <label className="text-xs text-indigo-400 font-bold uppercase">Primary Aura</label>
                        <div className="grid grid-cols-6 gap-2 p-3 bg-slate-950 border border-indigo-500/30 rounded-lg">
                            {SEEKER_AURA_OPTIONS.map(option => (
                                <button key={option.id} onClick={() => setAura(option.id)} className={`w-full aspect-square rounded-full border-2 transition-all ${aura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50'}`} style={{ backgroundColor: option.hex }} />
                            ))}
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-cyan-400 font-bold uppercase">Sub-Resonance Echo</label>
                        <div className="grid grid-cols-6 gap-2 p-3 bg-slate-950 border border-cyan-500/30 rounded-lg">
                            {SEEKER_AURA_OPTIONS.slice().reverse().map(option => (
                                <button key={option.id + '_sec'} onClick={() => setSecondaryAura(option.id)} className={`w-full aspect-square rounded-full border-2 transition-all ${secondaryAura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50'}`} style={{ backgroundColor: option.hex }} />
                            ))}
                        </div>
                    </div>
                </div>
            </div>
            <div className="flex justify-center pt-6">
                <Button onClick={weaveIdentity} className="px-16 py-5 bg-emerald-600 font-cinzel font-bold text-xl tracking-widest">INITIATE WEAVING</Button>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
          <motion.div key="weaving" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-8">
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                <div className="absolute inset-4 border-r-2 border-emerald-500 rounded-full animate-reverse-spin"></div>
                <span className="absolute inset-0 flex items-center justify-center text-3xl text-indigo-300 font-mono animate-pulse">Woven</span>
            </div>
            <div className="text-slate-500 font-mono text-sm text-center">Synthesizing Biomorph: {race}...<br/>Encoding Archetype: {seekerClass}...</div>
          </motion.div>
        )}

        {step === 'reveal' && generatedProfile && (
          <motion.div key="reveal" initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} className="flex flex-col items-center gap-8">
             <div id="onboarding-reveal-card" className="w-[320px] md:w-[400px] shadow-[0_0_100px_rgba(99,102,241,0.5)]">
                <div className="relative rounded-xl border-[8px] border-amber-500 bg-slate-950 flex flex-col overflow-hidden" style={{ aspectRatio: '2.5/3.5' }}>
                    <div className="bg-black/40 p-4 border-b border-white/10 z-10">
                        <span className="font-cinzel font-bold text-white text-xl">{generatedProfile.name}</span>
                    </div>
                    <div className="absolute inset-0 z-0">{generatedProfile.avatarImageUrl && <img src={generatedProfile.avatarImageUrl} className="w-full h-full object-cover" />}</div>
                    <div className="flex-1 z-10"></div>
                    <div className="bg-slate-950/70 p-4 text-slate-100 font-cormorant italic z-10 border-t border-white/10">{generatedProfile.bio}</div>
                </div>
             </div>
             <Button onClick={() => onComplete(generatedProfile)} className="px-16 py-5 bg-emerald-600 text-2xl font-bold uppercase">ENTER THE CODEX</Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default OnboardingFunnel;

