  return (
    <div className={`bg-slate-950/80 backdrop-blur-xl rounded-xl shadow-2xl p-4 text-slate-100 my-4 border ${isBugaLocal ? 'border-yellow-500' : 'border-fuchsia-500'}`} style={{ width: '750px', height: '850px' }}>
