                x: width / 2, y: height * 0.85,
                vx: (Math.random() - 0.5) * (0.8 + currentEntropy*1.5), 
                vy: -(1.5 + Math.random() * 1.5 + (chaliceStatus === 'Overflowing' ? 1 : 0)), 
                life: 80 + Math.random() * 100, size: Math.random() * 2 + 1,
