                vx: (Math.random() - 0.5) * 0.08 * (1 + currentEntropy * 1.5), vy: (Math.random() - 0.5) * 0.08 * (1 + currentEntropy * 1.5),
                life: Infinity, size: Math.random() * 1.3 + 0.1,
