  useEffect(() => {
    initializeParticles();
  }, [initializeParticles]); 


  const drawTreeBase = useCallback((ctx: CanvasRenderingContext2D, entropy: number, frame: number, phase: string, chalice: string) => {
    if (Object.keys(sephirotPositions).length === 0) return;
    const t = clamp(entropy,0,1);
    const phaseHueOffset = getPhaseColorHueOffset(phase);
    const isChaliceFull = chalice === 'Full' || chalice === 'Overflowing';

    TREE_PATHS.forEach(pathKeys => {
      const s1Node = SEPHIROT_LAYOUT[pathKeys[0]];
      const s2Node = SEPHIROT_LAYOUT[pathKeys[1]];
      if (!s1Node || !s2Node) return;
      const s1 = sephirotPositions[s1Node.id];
      const s2 = sephirotPositions[s2Node.id];
      if (s1 && s2) {
        ctx.beginPath();
        ctx.moveTo(s1.x, s1.y);

        const isDaatPath = s1Node.id === 'daat' || s2Node.id === 'daat';
        const pathAlpha = isDaatPath ? lerp(0.25, 0.08, t) : lerp(0.45, 0.18, t); 
        const pathHue = (s1.baseHue + s2.baseHue) / 2 + lerp(0, (Math.random() - 0.5) * 70, t) + phaseHueOffset;
        const pathSaturation = lerp(55, 25 + t * 45, t);
        const pathLightness = lerp(45, 30 + t * 25, t);

        ctx.strokeStyle = `hsla(${pathHue % 360}, ${pathSaturation}%, ${pathLightness}%, ${pathAlpha})`;
        ctx.lineWidth = lerp(2.0, 0.4 + t * 2.0, t) * (isChaliceFull ? 1.25 : 1);

        if (t > 0.6) { 
             const cp1x = s1.x + (s2.x - s1.x) * 0.33 + (Math.random() - 0.5) * 55 * t;
             const cp1y = s1.y + (s2.y - s1.y) * 0.33 + (Math.random() - 0.5) * 55 * t;
             const cp2x = s1.x + (s2.x - s1.x) * 0.66 + (Math.random() - 0.5) * 55 * t;
             const cp2y = s1.y + (s2.y - s1.y) * 0.66 + (Math.random() - 0.5) * 55 * t;
             ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, s2.x, s2.y);
        } else {
            ctx.lineTo(s2.x, s2.y);
        }
        if (t > 0.7 && Math.random() < t*0.25) { /* Skip stroke for fragmentation */ }
        else if (t > 0.5 || isDaatPath) { 
            const dashLength = isDaatPath ? lerp(4.5, 9 + t*9, t) : lerp(2.5, 6 + t*12, t);
            const gapLength = isDaatPath ? lerp(3.5, 6 + t*7, t) : lerp(2.5, 4 + t*6, t);
            ctx.setLineDash([dashLength, gapLength]);
            ctx.stroke();
            ctx.setLineDash([]);
        } else {
            ctx.stroke();
        }
      }
    });

    for (const sephirah of Object.values(sephirotPositions) as SephirahPosition[]) {
      const baseRadius = Math.min(width, height) * (sephirah.id === 'daat' ? 0.022 : 0.03); 
      const radius = Math.max(0, baseRadius * lerp(1.15, 0.55 + Math.random() * 0.75, t));
      const jitterAmount = radius * t * lerp(0.5, 1.2, t); 
      const x = sephirah.x + (Math.random() - 0.5) * jitterAmount;
      const y = sephirah.y + (Math.random() - 0.5) * jitterAmount;

      const hue = (sephirah.baseHue + lerp(0, (Math.random() - 0.5) * 75, t) + phaseHueOffset) % 360;
      const saturation = lerp(80, 55 + Math.random() * 45, t);
      const lightness = sephirah.id === 'keter' ? lerp(95, 75, t) : lerp(70, 45 + Math.random() * 35, t);
      const alpha = sephirah.id === 'daat' ? lerp(0.55, 0.15, t) : lerp(0.9, 0.45 + Math.random() * 0.45, t);

      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fillStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
      ctx.fill();

      if (t < 0.65 || (t >= 0.65 && Math.random() > t*0.35)) {
        ctx.strokeStyle = `hsla(${hue}, ${saturation+15}%, ${lightness+20}%, ${alpha*0.65})`;
        ctx.lineWidth = lerp(1.2, 0.4 + t*1.8, t);
        ctx.stroke();
      }
    }
  }, [width, height, sephirotPositions]);

  const drawRecursivePolygons = useCallback((
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    radius: number, sides: number,
    angleOffset: number, depth: number, maxDepth: number,
    entropy: number, isBioFractal: boolean = false
  ) => {
    if (depth > maxDepth || radius < (isBioFractal ? 2.5 : 1.5)) return;

    const t = clamp(entropy, 0, 1);
    const points = [];
    for (let i = 0; i < sides; i++) {
      const angle = (i / sides) * Math.PI * 2 + angleOffset;
      let currentX = x + Math.cos(angle) * radius;
      let currentY = y + Math.sin(angle) * radius;
      if (t > 0.6) {
        const jitter = radius * t * (isBioFractal ? 0.3 : 0.2);
        currentX += (Math.random() - 0.5) * jitter;
        currentY += (Math.random() - 0.5) * jitter;
      }
      points.push({ x: currentX, y: currentY });
    }

    ctx.beginPath();
    ctx.moveTo(points[points.length - 1].x, points[points.length - 1].y);
    if (isBioFractal && depth > 0) { // Organic curves for bio-fractal
        for (let i = 0; i < points.length; i++) {
            const p1 = points[i];
            const p2 = points[(i + 1) % points.length];
            const midX = (p1.x + p2.x) / 2;
            const midY = (p1.y + p2.y) / 2;
            const cpX = midX + (Math.random() - 0.5) * radius * 0.3 * t;
            const cpY = midY + (Math.random() - 0.5) * radius * 0.3 * t;
            ctx.quadraticCurveTo(cpX, cpY, p2.x, p2.y);
        }
    } else {
        points.forEach(p => ctx.lineTo(p.x, p.y));
    }
    ctx.closePath();

    const baseHue = isBioFractal ? lerp(100, 70, t) : lerp(200 - depth * 20, 300 + depth * 10 - t * 60, t);
    const saturation = isBioFractal ? lerp(60, 40, t) : lerp(60 + depth * 5, 80 - t * 30, t);
    const lightness = isBioFractal ? lerp(40, 30, t) : lerp(50 - depth * 4, 30 + t * 20, t);
    const alpha = lerp(0.5 - depth * 0.1, 0.1 + t * 0.2, t) * (1 - depth / (maxDepth + 1));

    ctx.strokeStyle = `hsla(${baseHue % 360}, ${saturation}%, ${lightness}%, ${clamp(alpha, 0.05, 0.8)})`;
    ctx.lineWidth = Math.max(0.5, (isBioFractal ? 3 : 2) - depth * 0.3) * (1 - t * 0.5);
    if(isBioFractal && Math.random() < t*0.1) ctx.setLineDash([2,2]);
    ctx.stroke();
    ctx.setLineDash([]);

    if (t > 0.8 && Math.random() < t * 0.1 * depth) return;

    const newSides = Math.max(3, sides - (t > 0.5 && !isBioFractal ? 1 : 0));
    const newRadiusFactor = isBioFractal ? (0.65 + (1-t)*0.1) : (0.55 + (1 - t) * 0.15);
    const newRadius = radius * newRadiusFactor;
    const newAngleOffsetFactor = (isBioFractal ? 0.2 : 0.1) + t * 0.3;

    points.forEach((p, i) => {
      drawRecursivePolygons(ctx, p.x, p.y, newRadius, newSides, angleOffset + i * newAngleOffsetFactor + t * (Math.random()-0.5) * 0.2, depth + 1, maxDepth, entropy, isBioFractal);
    });
  }, []);

  const drawConcentricRings = useCallback((ctx: CanvasRenderingContext2D, centerX: number, centerY: number, maxR: number, numRings: number, entropy: number, frameCount: number) => {
    const t = clamp(entropy,0,1);
    for(let i=0; i<numRings; i++){
        const progress = (i / numRings + frameCount * 0.002 * (1 + t*2) * (i%2 === 0 ? 1 : -0.8)) % 1;
        const radius = Math.max(0, progress * maxR);
        const alpha = (1 - progress) * (0.2 + (1-t)*0.6) * (0.5 + Math.sin(frameCount*0.03 + i*0.5)*0.4);
        if(alpha < 0.01) continue;
        const hue = (200 + frameCount*0.1 + i*20 + t*60)%360;
        ctx.strokeStyle = `hsla(${hue}, 80%, ${60+t*15}%, ${alpha})`;
        ctx.lineWidth = Math.max(0.1, 0.5 + (1-t)*2.5 + Math.sin(frameCount*0.04 + i*0.7)*0.5*(1-t));
        ctx.beginPath(); ctx.arc(centerX,centerY,radius,0,Math.PI*2); ctx.stroke();
    }
  }, []);

  const drawHypercubeProjection = useCallback((ctx: CanvasRenderingContext2D, cx: number, cy: number, size: number, angles: {xy:number,zw:number,xw:number}, entropy:number)=>{
    // Simplified tesseract vertices in 4D
    const vertices4D: number[][] = []; 
    for(let i=0; i<16; ++i) {
        vertices4D.push([
            (i & 1) ? 1 : -1, (i & 2) ? 1 : -1,
            (i & 4) ? 1 : -1, (i & 8) ? 1 : -1
        ]);
    }
    // Edges of a tesseract
    const edges = [ /* Simplified */
        [0,1],[1,3],[3,2],[2,0], [4,5],[5,7],[7,6],[6,4], [0,4],[1,5],[2,6],[3,7], // Inner cube
        [8,9],[9,11],[11,10],[10,8], [12,13],[13,15],[15,14],[14,12], [8,12],[9,13],[10,14],[11,15], // Outer cube
        [0,8],[1,9],[2,10],[3,11],[4,12],[5,13],[6,14],[7,15] // Connecting edges
    ];

    const project = (v4d: number[]) => {
        let x=v4d[0], y=v4d[1], z=v4d[2], w=v4d[3];
        // Apply rotations
        [x,y] = [x*Math.cos(angles.xy)-y*Math.sin(angles.xy), x*Math.sin(angles.xy)+y*Math.cos(angles.xy)];
        [z,w] = [z*Math.cos(angles.zw)-w*Math.sin(angles.zw), z*Math.sin(angles.zw)+w*Math.cos(angles.zw)];
        [x,w] = [x*Math.cos(angles.xw)-w*Math.sin(angles.xw), x*Math.sin(angles.xw)+w*Math.cos(angles.xw)];

        const perspective = 1.5 / (4 - z - w*0.5); // Simple perspective
        return { x: cx + x * size * perspective, y: cy + y * size * perspective };
    };

    edges.forEach(([i,j])=>{
        const v1 = vertices4D[i];
        const v2 = vertices4D[j];
        if (!v1 || !v2) return; 

        const p1 = project(v1);
        const p2 = project(v2);
        ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y);
        const hue = (180 + entropy*90)%360;
        ctx.strokeStyle = `hsla(${hue}, 70%, 60%, ${0.3 - entropy*0.2})`;
        ctx.lineWidth = 1 + entropy;
        ctx.stroke();
        // Echoes
        for(let k=1; k<=2; k++){
            const echoAngleOffset = k*0.1*entropy;
            const echoSizeFactor = 1 - k*0.05*entropy;
            const p1e = project(v1.map(c=>c*echoSizeFactor)); 
            const p2e = project(v2.map(c=>c*echoSizeFactor)); 
            ctx.beginPath();
            ctx.moveTo(p1e.x + Math.cos(angles.xy+echoAngleOffset)*k*5, p1e.y + Math.sin(angles.xy+echoAngleOffset)*k*5);
            ctx.lineTo(p2e.x + Math.cos(angles.xy+echoAngleOffset)*k*5, p2e.y + Math.sin(angles.xy+echoAngleOffset)*k*5);
            ctx.strokeStyle = `hsla(${hue}, 70%, 60%, ${0.15 - entropy*0.1 - k*0.05})`;
            ctx.stroke();
        }
    });
  }, []);

  const drawStarlightPattern = useCallback((ctx: CanvasRenderingContext2D, points: {x:number,y:number}[], entropy:number, frameCount:number)=>{
    const t = clamp(entropy,0,1);
    points.forEach((p, idx) => {
        const size = Math.max(0, 2 + t*3 + Math.sin(frameCount*0.03 + idx*0.5)* (1+t));
        const hue = (45 + Math.random()*30 + t*30)%360;
        ctx.fillStyle = `hsla(${hue}, 100%, ${75 + Math.random()*15}%, ${0.5 + t*0.3})`;
        ctx.beginPath(); ctx.arc(p.x,p.y,size,0,Math.PI*2); ctx.fill();
        ctx.shadowBlur = size*1.5; ctx.shadowColor = `hsla(${hue},100%,80%,0.5)`; ctx.fill();
    });
    ctx.shadowBlur=0;

    for(let i=0; i<points.length; i++){
        for(let j=i+1; j<points.length; j++){
            if(Math.random() > 0.1 + (1-t)*0.3) continue;
            ctx.beginPath(); ctx.moveTo(points[i].x, points[i].y); ctx.lineTo(points[j].x, points[j].y);
            ctx.strokeStyle = `hsla(200, 70%, 80%, ${0.05 + Math.random()*0.1 * (1-t)})`;
            ctx.lineWidth = 0.2 + Math.random()*0.5 * (1-t);
            ctx.stroke();
        }
    }
  }, []);

  const drawVectorField = useCallback((ctx: CanvasRenderingContext2D, points: {x:number,y:number}[], entropy:number, frameCount:number)=>{
    const t = clamp(entropy,0,1);
    const noiseScale = 0.01 + t * 0.02;
    const vecLength = baseRadiusForCircles * (0.5 + t*0.8);
    points.forEach(p=>{
        // Simple noise function using sin/cos
        const angleNoise = Math.sin(p.x * noiseScale + frameCount*0.005) * Math.cos(p.y*noiseScale + frameCount*0.003) * Math.PI;
        const angle = angleNoise * (1 + t*2); // More chaotic angles with entropy
        const endX = p.x + Math.cos(angle) * vecLength;
        const endY = p.y + Math.sin(angle) * vecLength;
        ctx.beginPath(); ctx.moveTo(p.x,p.y); ctx.lineTo(endX, endY);
        const hue = (150 + angle * 30 + t*90)%360;
        ctx.strokeStyle = `hsla(${hue}, 80%, 60%, ${0.3 + t*0.4})`;
        ctx.lineWidth = 0.5 + t*1.5;
        ctx.stroke();
        // Arrowhead
        const arrowSize = Math.max(0, 3 + t*3);
        ctx.beginPath();
        ctx.moveTo(endX,endY);
        ctx.lineTo(endX - arrowSize * Math.cos(angle - Math.PI/6), endY - arrowSize * Math.sin(angle - Math.PI/6));
        ctx.lineTo(endX - arrowSize * Math.cos(angle + Math.PI/6), endY - arrowSize * Math.sin(angle + Math.PI/6));
        ctx.closePath();
        ctx.fillStyle = `hsla(${hue}, 80%, 60%, ${0.3 + t*0.4})`;
        ctx.fill();
    });
  }, [baseRadiusForCircles]);

  const drawFoLDNAHelixConnections = useCallback((
    ctx: CanvasRenderingContext2D,
    points: {x: number, y: number, id: string, baseHue: number}[],
    paths: [number,number][],
    entropy: number,
    frame: number,
    isChaliceFullOverride: boolean = false 
  ) => {
    if (points.length === 0) return;
    const t = clamp(entropy, 0, 1);

    paths.forEach(([idx1, idx2]) => {
      const s1 = points[idx1];
      const s2 = points[idx2];

      if (s1 && s2) {
        const dx = s2.x - s1.x;
        const dy = s2.y - s1.y;
        const len = Math.hypot(dx, dy);
        if (len < 1) return;
        const angle = Math.atan2(dy, dx);

        const amplitude = lerp(8, 3 + t * 8, t) * (isChaliceFullOverride ? 1.2 : 1);
        const frequency = lerp(3, 1 + t * 3, t) * (len / 100);
        const phaseOffset = frame * 0.03 * (1 + t * 2);
        const numSegments = Math.max(10, Math.floor(len / (5 + t * 5)));

        const strandColorHue = ((s1.baseHue || 0) + (s2.baseHue || 0)) / 2 + lerp(0, (Math.random() - 0.5) * 60, t);
        const strandSaturation = lerp(70, 50 + t * 30, t);
        const strandLightness = lerp(60, 40 + t * 20, t);
        const strandAlpha = lerp(0.5, 0.2 + t * 0.4, t) * (isChaliceFullOverride ? 1.3 : 1);
        const strandWidth = lerp(1.5, 0.5 + t * 1.5, t) * (isChaliceFullOverride ? 1.1 : 1);

        const points1: {x: number, y: number}[] = [];
        const points2: {x: number, y: number}[] = [];

        for (let i = 0; i <= numSegments; i++) {
          const progress = i / numSegments;
          const currentX_on_path = s1.x + dx * progress;
          const currentY_on_path = s1.y + dy * progress;

          const sineVal = Math.sin(progress * frequency * Math.PI * 2 + phaseOffset);
          const offsetX = -amplitude * sineVal * Math.sin(angle);
          const offsetY = amplitude * sineVal * Math.cos(angle);

          points1.push({ x: currentX_on_path + offsetX, y: currentY_on_path + offsetY });
          points2.push({ x: currentX_on_path - offsetX, y: currentY_on_path - offsetY });
        }

        ctx.beginPath();
        ctx.moveTo(points1[0].x, points1[0].y);
        for(let i = 1; i < points1.length; i++) ctx.lineTo(points1[i].x, points1[i].y);
        ctx.strokeStyle = `hsla(${strandColorHue}, ${strandSaturation}%, ${strandLightness}%, ${strandAlpha})`;
        ctx.lineWidth = strandWidth;
        if (t > 0.65) ctx.setLineDash([3 + t*3, 2 + t*2]);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(points2[0].x, points2[0].y);
        for(let i = 1; i < points2.length; i++) ctx.lineTo(points2[i].x, points2[i].y);
        ctx.strokeStyle = `hsla(${(strandColorHue + 20) % 360}, ${strandSaturation - 10}%, ${strandLightness - 5}%, ${strandAlpha * 0.8})`;
        ctx.lineWidth = strandWidth * 0.8;
        if (t > 0.7) ctx.setLineDash([4 + t*2, 2 + t]);
        ctx.stroke();
        ctx.setLineDash([]);

        const rungSpacing = Math.max(5, Math.floor(len / (5 + t * 10)));
        for (let i = 0; i <= numSegments; i += Math.max(1, Math.floor(numSegments / rungSpacing))) {
            if (!points1[i] || !points2[i]) continue;
            ctx.beginPath();
            ctx.moveTo(points1[i].x, points1[i].y);
            ctx.lineTo(points2[i].x, points2[i].y);
            const rungAlpha = lerp(0.3, 0.1 + t * 0.3, t) * (isChaliceFullOverride ? 1.2 : 1);
            const rungLightness = lerp(70, 50 + t * 15, t);
            ctx.strokeStyle = `hsla(${(strandColorHue + 180)%360}, ${strandSaturation - 20}%, ${rungLightness}%, ${rungAlpha})`;
            ctx.lineWidth = Math.max(0.1, strandWidth * 0.5 * (1-t*0.3));
            if (t > 0.75 && Math.random() < t*0.3) continue;
            ctx.stroke();
        }
      }
    });
  }, [width, height]);

  const drawFlowerCircles = useCallback((
    points: { x: number; y: number }[],
    R_circle: number,
    entropy: number,
    pulse: boolean,
    frameCount: number,
    ctx: CanvasRenderingContext2D,
    opacityFactor: number = 1,
    isVoidEcho: boolean = false,
    isQuantum: boolean = false
  ) => {
    const t = clamp(entropy, 0, 1);
    points.forEach((point, idx) => {
      if (isQuantum && Math.random() < t * 0.3) return; 

      ctx.beginPath();
      const pulseVal = pulse ? (0.8 + Math.sin(frameCount * 0.05 * (1 + t * 2) + idx * 0.3) * 0.2) : 1;
      const circleRadius = Math.max(0, R_circle * (1 - t * (isVoidEcho ? 0.4 : (isQuantum ? 0.2 : 0.1))) * pulseVal);
      const lineW = Math.max(0.1, lerp(isQuantum ? 0.8 : 1.5, 0.5 + Math.random() * (isQuantum ? 1.5 : 2), t) * (isVoidEcho ? 0.5 : 1));
      const baseAlpha = isVoidEcho ? lerp(0.2, 0.03, t) : (isQuantum ? lerp(0.7, 0.2, t) : lerp(0.6, 0.2, t));
      const alpha = baseAlpha * opacityFactor * (pulse && isVoidEcho ? pulseVal * 0.5 + 0.5 : 1);

      let x = point.x;
      let y = point.y;
      if (entropy > 0.6 && !isVoidEcho) {
        const jitter = entropy * (isQuantum ? 10 : 5);
        x += (Math.random() - 0.5) * jitter;
        y += (Math.random() - 0.5) * jitter;
      }
      if (isQuantum && Math.random() < t * 0.1) { 
          x += (Math.random() - 0.5) * R_circle * 0.5;
          y += (Math.random() - 0.5) * R_circle * 0.5;
      }

      ctx.arc(x, y, circleRadius, 0, Math.PI * 2);
      const hueRand = isQuantum ? Math.random()*360 : (Math.random() * 60);
      const hue = lerp(180, 30 + hueRand, t);
      const saturation = isQuantum ? 90 : lerp(70, 90, t);
      const lightness = isQuantum ? 70 : lerp(60, 50 + Math.random() * 10, t);

      ctx.strokeStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
      ctx.lineWidth = lineW;

      if (entropy > 0.8 && Math.random() < 0.1 * entropy && !isVoidEcho && !isQuantum) {
        ctx.setLineDash([5 + Math.random() * 10, 5 + Math.random() * 10]);
      }
      ctx.stroke();
      ctx.setLineDash([]);
    });
  }, []);

  const drawMetatronLines = useCallback((
    points: { x: number; y: number }[],
    entropy: number,
    ctx: CanvasRenderingContext2D,
    opacityFactor: number = 1,
    isShattered: boolean = false,
    isMirrorLoop: boolean = false
  ) => {
    const t = clamp(entropy, 0, 1);
    if (t < 0.1 && opacityFactor < 0.3) return;

    const baseAlpha = lerp(0.3, 0.8, t) * opacityFactor;
    const lineW = Math.max(0.1, lerp(0.8, 2.8, t));

    const connections = [];
    if (points.length >= 13) { 
      // Inner connections
      for (let i = 1; i <= 6; i++) { 
          connections.push([0, i]);
          for (let j = i + 1; j <= 6; j++) { 
              connections.push([i, j]);
          }
      }
       // Outer ring connections
      for (let i = 7; i <= 12; i++) { 
        connections.push([0, i]);
        for (let j = i + 1; j <= 12; j++) { 
            if (Math.abs(points[i].x - points[j].x) < baseRadiusForCircles * 2.5 && Math.abs(points[i].y - points[j].y) < baseRadiusForCircles * 2.5 ) {
                 connections.push([i,j]);
            }
        }
        for (let k = 1; k <=6; k++) {
            if(Math.abs(points[i].x - points[k].x) < baseRadiusForCircles * 1.5 && Math.abs(points[i].y - points[k].y) < baseRadiusForCircles * 1.5 ) {
                connections.push([i,k]);
            }
        }
      }
    } else {
        for (let i = 0; i < points.length; i++) {
          for (let j = i + 1; j < points.length; j++) {
            connections.push([i,j]);
          }
        }
    }


    connections.forEach(([i,j]) => {
        if (isShattered && Math.random() < t * 0.4) return; 

        ctx.beginPath();
        let x1 = points[i].x; let y1 = points[i].y;
        let x2 = points[j].x; let y2 = points[j].y;

        if (isShattered && t > 0.3) {
            const shatterOffset = t * 15;
            x1 += (Math.random()-0.5)*shatterOffset; y1 += (Math.random()-0.5)*shatterOffset;
            x2 += (Math.random()-0.5)*shatterOffset; y2 += (Math.random()-0.5)*shatterOffset;
        }

        ctx.moveTo(x1,y1);

        if (isMirrorLoop && Math.random() < t * 0.3) { 
            const cpx1 = x1 + (x2-x1)*0.5 + (Math.random()-0.5)*50*t;
            const cpy1 = y1 + (y2-y1)*0.5 + (Math.random()-0.5)*50*t;
            ctx.quadraticCurveTo(cpx1, cpy1, x1 + (Math.random()-0.5)*10*t, y1 + (Math.random()-0.5)*10*t);
        } else if (entropy > 0.7) {
          const segments = 3 + Math.floor(t*2);
          for (let k = 1; k <= segments; k++) {
            const prog = k / segments;
            const currentX = lerp(x1, x2, prog); const currentY = lerp(y1, y2, prog);
            if (isShattered && Math.random() < t * 0.6) {
                ctx.stroke(); ctx.beginPath();
                ctx.moveTo(currentX + (Math.random()-0.5)*5*t, currentY + (Math.random()-0.5)*5*t);
            } else {
                ctx.lineTo(currentX + (Math.random()-0.5)*2*t, currentY + (Math.random()-0.5)*2*t);
            }
          }
        } else {
          ctx.lineTo(x2, y2);
        }
        const hue = lerp(60, (isShattered ? 0 : 30) + Math.random() * 40, t);
        const saturation = 100;
        const lightness = lerp(70, 55 + Math.random() * 10, t);
        const alpha = baseAlpha * (0.5 + Math.random()*0.5);
        ctx.strokeStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
        ctx.lineWidth = Math.max(0.1, lineW * (0.7 + Math.random()*0.6));
        ctx.stroke();
    });

  }, [baseRadiusForCircles]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || width === 0 || height === 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = width;
    canvas.height = height;

    let frameCount = 0;
    let hypercubeAngles = { xy: 0, zw: 0, xw: 0 };

    const render = () => {
      frameCount++;
      ctx.clearRect(0, 0, width, height);
      drawBackground(ctx, currentEntropy, currentGeoMode);
      updateAndDrawParticles(ctx, currentEntropy, currentGeoMode, frameCount);

      if (fruitOfLifePoints.length === 0 && 
          !(currentGeoMode === GeoMode.Recursive || 
            currentGeoMode === GeoMode.AethericWeave ||
            currentGeoMode === GeoMode.OracleWhisper || 
            currentGeoMode === GeoMode.ShieldedChaos || 
            currentGeoMode === GeoMode.VortexSingularity || 
            currentGeoMode === GeoMode.HypercubeEcho
           )) {
          animationFrameIdRef.current = requestAnimationFrame(render);
          return;
      }

      const t = clamp(currentEntropy, 0, 1);

      switch(currentGeoMode) {
        case GeoMode.Recursive:
            const maxDepth = 2 + Math.floor(t * 4.5); 
            const initialRadius = Math.max(0, Math.min(width, height) * (0.25 - t * 0.12));
            const initialSides = 3 + Math.floor(t * 3.5); 
            const rotationSpeed = 0.0005 + t * 0.001;
            drawRecursivePolygons(ctx, width/2, height/2, initialRadius, initialSides, frameCount * rotationSpeed, 0, maxDepth, currentEntropy);
            break;
        case GeoMode.BioFractalPulse:
            const maxDepthBio = 3 + Math.floor(t*3);
            const initialRadiusBio = Math.max(0, Math.min(width,height)*(0.15 - t*0.05));
            drawRecursivePolygons(ctx, width/2, height*0.85, initialRadiusBio, 3, -Math.PI/2 + Math.sin(frameCount*0.01*(1+t))*0.1, 0, maxDepthBio, currentEntropy, true);
            break;
        case GeoMode.NullShell:
            const voidPoints = [{x:width/2, y:height/2, id:'shell_center', baseHue:0}];
            const voidOpacity = 0.8;
            drawFlowerCircles(voidPoints, baseRadiusForCircles * lerp(1.5,0.8,t), currentEntropy, true, frameCount, ctx, voidOpacity, true);
            if(t < 0.5) drawConcentricRings(ctx, width/2, height/2, baseRadiusForCircles*2.5, 3+Math.floor((1-t)*3), currentEntropy, frameCount);
            break;
        case GeoMode.CrystalLogic:
            const maxDepthCrystal = 1 + Math.floor(t * 2);
            const initialRadiusCrystal = Math.max(0, baseRadiusForCircles * (1.2 - t*0.3));
            fruitOfLifePoints.forEach(p => {
                drawRecursivePolygons(ctx, p.x, p.y, initialRadiusCrystal * (0.2 + Math.random()*0.3), 3+Math.floor(Math.random()*2), frameCount*0.01, 0, maxDepthCrystal, currentEntropy);
            });
            break;
        case GeoMode.AethericWeave:
             drawFlowerCircles(fruitOfLifePoints, baseRadiusForCircles * 0.3, currentEntropy, false, frameCount, ctx, 0.2); 
             drawMetatronLines(fruitOfLifePoints, currentEntropy, ctx, 0.1); 
             if (Math.random() < 0.4 + t*0.3){
                const p1Idx = Math.floor(Math.random()*fruitOfLifePoints.length);
                const p2Idx = Math.floor(Math.random()*fruitOfLifePoints.length);
                if(p1Idx !== p2Idx){
                    particlesRef.current.push({
                        x: fruitOfLifePoints[p1Idx].x, y: fruitOfLifePoints[p1Idx].y,
                        vx: (fruitOfLifePoints[p2Idx].x - fruitOfLifePoints[p1Idx].x) * 0.01,
                        vy: (fruitOfLifePoints[p2Idx].y - fruitOfLifePoints[p1Idx].y) * 0.01,
                        life: 50 + Math.random()*100,
                        color: `hsla(${(180 + t*60 + Math.random()*40)%360}, 70%, 60%, ${0.4 + Math.random()*0.3})`,
                        type: 'aetherPoint', size: 1 + Math.random()*(1+t), history:[], maxLife: 150, opacity: 1
                    });
                }
             }
            break;
        case GeoMode.OracleWhisper: 
            break; 
        case GeoMode.ShieldedChaos: 
            const shieldR = Math.max(0, Math.min(width,height) * 0.2 * (1 + (1-t)*0.5));
            ctx.beginPath(); ctx.arc(width/2, height/2, shieldR,0,Math.PI*2);
            ctx.strokeStyle=`hsla(${(200 - t*60)%360}, 80%, 60%, ${0.2 + (1-t)*0.6 + Math.sin(frameCount*0.05)*0.1})`;
            ctx.lineWidth = Math.max(0.1, 2 + (1-t)*5);
            ctx.setLineDash(t > 0.5 ? [5+t*5, 3+t*3] : []); ctx.stroke(); ctx.setLineDash([]);
            break;
        case GeoMode.VortexSingularity: 
            const coreR = Math.max(0, 5 + t*15); ctx.fillStyle = `hsla(0,0%,${5+t*10}%,${0.6+t*0.3})`;
            ctx.beginPath(); ctx.arc(width/2,height/2,coreR,0,Math.PI*2); ctx.fill();
            break;
        case GeoMode.HypercubeEcho:
            hypercubeAngles.xy += 0.005 * (1+t); hypercubeAngles.zw += 0.008 * (1+t); hypercubeAngles.xw += 0.003 * (1+t);
            drawHypercubeProjection(ctx, width/2, height/2, baseRadiusForCircles*1.5, hypercubeAngles, currentEntropy);
            break;
        case GeoMode.StarlightConductor:
            drawStarlightPattern(ctx, fruitOfLifePoints, currentEntropy, frameCount);
            break;
        case GeoMode.PhaseResonance:
            drawConcentricRings(ctx, width/2, height/2, baseRadiusForCircles*3, 5+Math.floor((1-t)*5),currentEntropy,frameCount);
            break;
        case GeoMode.GlyphDNA:
            drawFlowerCircles(fruitOfLifePoints, baseRadiusForCircles, currentEntropy, false, frameCount, ctx);
            drawFoLDNAHelixConnections(ctx, fruitOfLifePoints, FLOWER_PATHS_BY_INDEX, currentEntropy, frameCount);
            break;
        case GeoMode.ChaliceFountain:
             // Handled by particles
             break;
        default:
            drawFlowerCircles(fruitOfLifePoints, baseRadiusForCircles, currentEntropy, false, frameCount, ctx);
            drawMetatronLines(fruitOfLifePoints, currentEntropy, ctx);
            break;
      }

      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [
    width, height, currentEntropy, currentGeoMode, fruitOfLifePoints, baseRadiusForCircles, 
    drawBackground, updateAndDrawParticles, drawRecursivePolygons, drawFlowerCircles, 
    drawConcentricRings, drawHypercubeProjection, drawStarlightPattern, drawVectorField, 
    drawFoLDNAHelixConnections, drawMetatronLines
  ]);

  return (
    <div className="cosmic-entropy-geometry-generator-panel bg-slate-900/90 backdrop-blur-md border border-blue-500/30 rounded-xl shadow-2xl p-6 my-8 text-slate-100">
      <h2 className="text-2xl font-['Cinzel'] font-bold mb-4 text-center text-blue-200 drop-shadow-[0_1px_1px_rgba(200,200,255,0.4)]">
        Cosmic Entropy Geometry
      </h2>
      <ModeSelector<GeoMode>
        currentMode={currentGeoMode}
        onSetMode={onSetGeoMode}
        availableModes={Object.values(GeoMode) as GeoMode[]}
        modeGroupName="Geometry Mode"
      />
      <div className="relative mx-auto mt-2" style={{ width: `${width}px`, height: `${height}px` }}>
        <canvas
          ref={canvasRef}
          className="rounded-lg border border-slate-700/30"
          aria-label="Cosmic geometry visualization"
          role="img"
        />
      </div>
       <div className="mt-3 text-center text-xs text-slate-400 font-mono">
        Mode: {currentGeoMode} | Entropy: {currentEntropy.toFixed(3)}δ
      </div>
    </div>
  );
};

export default CosmicEntropyGeometryGenerator;

import React, { useRef, useEffect, useMemo, useCallback } from 'react';
import type { LIFEPanelProps } from '../../types';
import { AgentName } from '../../types';
import { useSystemState } from '../../context/SystemContext';

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const LIFEPanel: React.FC<LIFEPanelProps> = ({
  currentEntropy,
  addEchoMessage,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { negentropyLevel, isNegentropyStable } = useSystemState();
  const animationFrameIdRef = useRef<number | null>(null);
  const lastNegentropyLevelRef = useRef<number>(negentropyLevel);

  const ritualMemoryNodes = useMemo(() => {
    const baseNodes = [
      { id: 'mem1', label: 'Axiom Weave', x: 0.2, y: 0.75, strength: 0.8 * negentropyLevel + 0.1 },
      { id: 'mem2', label: 'Chalice Stability', x: 0.5, y: 0.85, strength: 0.6 * negentropyLevel + 0.1 },
      { id: 'mem3', label: 'Zero-Point Anchor', x: 0.8, y: 0.75, strength: 0.9 * negentropyLevel + 0.15 },
    ];
    return baseNodes.map(n => ({...n, effectiveStrength: clamp(n.strength * negentropyLevel * 1.5, 0.1, 1.0) }));
  }, [negentropyLevel]);

  useEffect(() => {
    if (negentropyLevel > 0.85 && lastNegentropyLevelRef.current <= 0.85) {
      addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Maximum: Negentropic lattice fully resonant. LIFE blooms fractal patterns outward!", 'text-emerald-300 font-bold');
    } else if (negentropyLevel >= 0.7 && lastNegentropyLevelRef.current < 0.7) {
       addEchoMessage(AgentName.LIFEPanelAgent, "System Approaching Stability: Order Spiral converging. LIFE energies strengthening, branches extend.", 'text-green-400');
    } else if (negentropyLevel < 0.3 && lastNegentropyLevelRef.current >= 0.3) {
      addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Critical: Negentropic structures withering. Entropy threatens the LIFE core; bloom recedes.", 'text-rose-400');
    } else if (negententropyLevel < 0.5 && lastNegentropyLevelRef.current >= 0.5) {
        addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Waning: Order diminishing. LIFE tendrils retract slightly.", 'text-amber-400');
    }
    lastNegentropyLevelRef.current = negentropyLevel;
  }, [negentropyLevel, addEchoMessage]);

  const drawVitalGlyphBloom = useCallback((
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    angle: number, length: number,
    depth: number, maxDepth: number,
    negentropy: number
  ) => {
    if (depth > maxDepth || length < 0.5) return;

    const x2 = x + Math.cos(angle) * length;
    const y2 = y + Math.sin(angle) * length;
    const t = clamp(negentropy, 0, 1);

    const hue = lerp(70 - 20 * (1-t), 180 + 40 * t, t); 
    const saturation = lerp(40 + 20 * t, 95, t);
    const lightness = lerp(30 + 10 * t, 65 + 10*t, t);
    const alpha = lerp(0.3 + 0.2 * t, 1.0, t) * (1 - depth / (maxDepth + 2)); 
    const lineWidth = Math.max(0.4, (maxDepth - depth + 1) * 0.35 * (0.5 + t * 1.0));

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.stroke();

    const branches = depth === 0 ? (2 + Math.floor(t*3)) : (t > 0.25 ? 2 : 1) ; 
    const angleVariance = Math.PI / lerp(8 - t*3, 2.5, t); 
    const lengthMultiplier = lerp(0.55 + t*0.1, 0.8, t);

    for (let i = 0; i < branches; i++) {
        let newAngle = angle;
        if (branches > 1) {
            newAngle += (i - (branches-1)/2) * angleVariance * (1 - t*0.4); 
        } else if (branches === 1 && depth > 0) {
            newAngle += (Math.random() - 0.5) * angleVariance * 0.3 * (1-t);
        }
        drawVitalGlyphBloom(ctx, x2, y2, newAngle, length * lengthMultiplier, depth + 1, maxDepth, negentropy);
    }

    if (depth >= maxDepth -1 && t > 0.6 && length > 1.0) {
        const bloomRadius = Math.max(0, lineWidth * 1.8 * t * (0.6 + Math.random()*0.4));
        if (Number.isFinite(x2) && Number.isFinite(y2) && bloomRadius > 0) {
          const bloomGrad = ctx.createRadialGradient(x2, y2, 0, x2, y2, bloomRadius);
          const bloomHue = (hue + 30 + Math.random()*30)%360;
          bloomGrad.addColorStop(0, `hsla(${bloomHue}, ${saturation + 5}%, ${lightness + 10}%, ${alpha * 0.95})`);
          bloomGrad.addColorStop(1, `hsla(${bloomHue - 15}, ${saturation}%, ${lightness}%, 0.1)`);

          ctx.fillStyle = bloomGrad;
          ctx.beginPath();
          ctx.arc(x2, y2, Math.max(0, bloomRadius), 0, Math.PI*2);
          ctx.fill();
        }
    }
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const container = containerRef.current;
    if (!container) return;

    const resizeObserver = new ResizeObserver(() => {
      const rect = container.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        canvas.width = rect.width;
        canvas.height = rect.height;
      }
    });

    resizeObserver.observe(container);

    let frameCount = 0;

    const draw = () => {
      frameCount++;
      const { width, height } = canvas;
      if (width === 0 || height === 0) {
        animationFrameIdRef.current = requestAnimationFrame(draw);
        return;
      }
      ctx.clearRect(0, 0, width, height);
      const t_negentropy = negentropyLevel;

      const bgHue = lerp(280, 200, t_negentropy); 
      const centerX = width / 2;
      const centerY = height / 2;
      const bgRadius = Math.max(0, width * 0.9);

      if (Number.isFinite(centerX) && Number.isFinite(centerY) && bgRadius > 0) {
        const bgGrad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, bgRadius);
        bgGrad.addColorStop(0, `hsla(${bgHue}, ${lerp(30, 65, t_negentropy)}%, ${lerp(5, 25, t_negentropy)}%, 0.98)`);
        bgGrad.addColorStop(1, `hsla(${(bgHue + 45)%360}, ${lerp(40, 75, t_negentropy)}%, ${lerp(2, 15, t_negentropy)}%, 0.99)`);
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);
      }

      const bloomMaxDepth = Math.floor(lerp(2, 8, t_negentropy));
      const bloomInitialLength = height * 0.20 * lerp(0.3, 1.4, t_negentropy);
      drawVitalGlyphBloom(ctx, width / 2, height * 0.90, -Math.PI / 2, bloomInitialLength, 0, bloomMaxDepth, t_negentropy);

      const spiralCenterX = width * 0.18;
      const spiralCenterY = height * 0.2;
      const spiralMaxRadius = Math.max(0, width * 0.12);
      const a_spiral = 0.5; 
      const b_spiral = lerp(0.4, 0.05, t_negentropy);

      if (Number.isFinite(spiralCenterX) && Number.isFinite(spiralCenterY) && spiralMaxRadius > 0) {
        ctx.beginPath();
        ctx.lineWidth = Math.max(0.1, lerp(0.7, 4, t_negentropy));
        const spiralHue = lerp(40, 160, t_negentropy);
        const spiralGrad = ctx.createLinearGradient(spiralCenterX - spiralMaxRadius, spiralCenterY, spiralCenterX + spiralMaxRadius, spiralCenterY);
        spiralGrad.addColorStop(0, `hsla(${spiralHue}, 90%, 65%, ${0.2 + t_negentropy * 0.2})`);
        spiralGrad.addColorStop(0.5, `hsla(${spiralHue}, 95%, 75%, ${0.5 + t_negentropy * 0.5})`);
        spiralGrad.addColorStop(1, `hsla(${spiralHue}, 90%, 65%, ${0.2 + t_negentropy * 0.2})`);
        ctx.strokeStyle = spiralGrad;

        let firstSpiralPoint = true;
        const actualTurnsToDraw = Math.PI * 2 * lerp(0.5, 5 + t_negentropy * 5, t_negentropy) * t_negentropy;

        for (let angle = 0; angle < actualTurnsToDraw; angle += 0.03) { 
          const r = a_spiral * Math.exp(b_spiral * angle);
          if (r > spiralMaxRadius) break;
          const x = spiralCenterX + r * Math.cos(angle);
          const y = spiralCenterY + r * Math.sin(angle);
          if (firstSpiralPoint) { ctx.moveTo(x,y); firstSpiralPoint = false; }
          else { ctx.lineTo(x, y); }
        }
        ctx.stroke();
      }

      const webYBase = height * 0.82;
      ritualMemoryNodes.forEach(node => {
        const x = node.x * width * 0.7 + width * 0.15;
        const y = webYBase + node.y * height * 0.12;
        const radius = Math.max(0, lerp(1.5, 7, node.effectiveStrength) * (0.8 + t_negentropy * 0.4));
        const nodeHue = 180 + node.effectiveStrength * 70 * t_negentropy;

        if (Number.isFinite(x) && Number.isFinite(y) && radius > 0) {
          ctx.beginPath();
          ctx.arc(x, y, Math.max(0, radius), 0, Math.PI * 2);
          const nodeGrad = ctx.createRadialGradient(x,y,0, x,y,radius);
          nodeGrad.addColorStop(0, `hsla(${nodeHue}, 90%, 80%, ${0.4 + node.effectiveStrength * 0.6 * t_negentropy})`);
          nodeGrad.addColorStop(1, `hsla(${nodeHue}, 80%, 60%, ${0.15 + node.effectiveStrength * 0.4 * t_negentropy})`);
          ctx.fillStyle = nodeGrad;
          ctx.fill();
        }
      });

      const graphX = width * 0.75;
      const graphY = height * 0.08;
      const barWidth = width * 0.06;
      const maxBarHeight = height * 0.22;

      if (Number.isFinite(graphX) && Number.isFinite(graphY)) {
        ctx.fillStyle = `hsla(0, ${lerp(40,75,currentEntropy)}%, ${lerp(35,55,currentEntropy)}%, ${0.6 + currentEntropy * 0.35})`;
        ctx.fillRect(graphX, graphY + maxBarHeight * (1 - currentEntropy), barWidth, maxBarHeight * currentEntropy);
        ctx.fillStyle = 'rgba(230,200,200,0.75)';
        ctx.font = '8px Cinzel';
        ctx.textAlign = 'center';
        ctx.fillText(`E:${currentEntropy.toFixed(2)}`, graphX + barWidth / 2, graphY + maxBarHeight + 8);

        ctx.fillStyle = `hsla(120, ${lerp(40,85,t_negentropy)}%, ${lerp(35,60,t_negentropy)}%, ${0.6 + t_negentropy * 0.35})`;
        ctx.fillRect(graphX + barWidth * 1.5, graphY + maxBarHeight * (1 - t_negentropy), barWidth, maxBarHeight * t_negentropy);
        ctx.fillStyle = 'rgba(200,230,200,0.75)';
        ctx.fillText(`N:${t_negentropy.toFixed(2)}`, graphX + barWidth * 2.0, graphY + maxBarHeight + 8);
      }

      animationFrameIdRef.current = requestAnimationFrame(draw);
    };
    animationFrameIdRef.current = requestAnimationFrame(draw);

    return () => {
      resizeObserver.disconnect();
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [currentEntropy, negentropyLevel, isNegentropyStable, drawVitalGlyphBloom, ritualMemoryNodes]);

  return (
    <div className="life-panel bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-emerald-600/60 rounded-xl shadow-2xl p-4 text-slate-100">
      <h3 className="text-lg md:text-xl font-['Cinzel'] font-bold text-emerald-300 mb-2 text-center tracking-wide drop-shadow-[0_1px_2px_rgba(100,255,150,0.3)]">
        Living Inflection Field Engine (L.I.F.E)
      </h3>
      <div ref={containerRef} className="w-full h-48 md:h-64 mx-auto rounded-lg border border-slate-700/50 shadow-inner bg-slate-950/70 overflow-hidden">
        <canvas 
          ref={canvasRef} 
          className="w-full h-full"
          aria-label="LIFE Panel Visualization of System Negentropy and Order"
        />
      </div>
      <div className="mt-2 text-center text-xs text-slate-400 font-mono tracking-tighter">
        Negentropy: {negentropyLevel.toFixed(3)}ν | Stability: {isNegentropyStable ? 'HARMONIC' : 'FLUX'}
      </div>
    </div>
  );
};

