  ['chokmah', 'tiphareth'], ['binah', 'tiphareth'], 
  ['chesed', 'tiphareth'], ['geburah', 'tiphareth'], 
  ['chesed', 'geburah'], 
  ['netzach', 'tiphareth'], ['hod', 'tiphareth'], 
  ['netzach', 'hod'], 
  ['yesod', 'netzach'], ['yesod', 'hod'], 
  ['chokmah', 'daat'], ['binah', 'daat'],
  ['chesed', 'daat'], ['geburah', 'daat'],
  ['keter', 'daat'], ['tiphareth', 'daat'],
];

const TreeOfLifeVisualizer: React.FC<TreeOfLifeVisualizerProps> = ({
  currentEntropy,
  width,
  height,
  seekerTraits = [],
  activeFlora,
  dominantAgentTone,
  lastRitualOutcome,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameIdRef = useRef<number | null>(null);
  const [sephirotState, setSephirotState] = useState<Sephirah[]>([]);
  const [emergenceLogs, setEmergenceLogs] = useState<SourceEchoLogEntry[]>([]);
  const lastLoggedEntropyThresholdRef = useRef<number>(0.7);
  const lastLogCountRef = useRef<number>(0);
  const daatPulseRef = useRef<{ active: boolean, frame: number, duration: number }>({ active: false, frame: 0, duration: 60 });

  useEffect(() => {
    if (width > 0 && height > 0) {
        const centerX = width / 2;
        const centerY = height / 2;
        const scaleX = width * 0.4;
        const scaleY = height * 0.45;
        setSephirotState(SEPHIROT_DATA_BASE.map(s => ({
            ...s,
            x: centerX + s.normalizedX * scaleX,
            y: centerY + s.normalizedY * scaleY,
            sourceSparks: []
        })));
    }
  }, [width, height]);

  useEffect(() => {
    if (emergenceLogs.length > lastLogCountRef.current) {
      daatPulseRef.current = { active: true, frame: 0, duration: 60 };
    }
    lastLogCountRef.current = emergenceLogs.length;
  }, [emergenceLogs]);

  useEffect(() => {
    const t = clamp(currentEntropy, 0, 1);
    let newLogEntry: Omit<SourceEchoLogEntry, 'id' | 'timestamp' | 'label'> | null = null;

    const entropyThresholdCrossed =
        (t > 0.75 && lastLoggedEntropyThresholdRef.current < 0.75) ||
        (t > 0.85 && lastLoggedEntropyThresholdRef.current < 0.85) ||
        (t > 0.95 && lastLoggedEntropyThresholdRef.current < 0.95);

    if (entropyThresholdCrossed) {
        newLogEntry = {
            identity: generateMysticalIdentity(),
            triggerDescription: `High Entropy Surge (${t.toFixed(3)}δ)`
        };
        if (t > 0.95) lastLoggedEntropyThresholdRef.current = 0.95;
        else if (t > 0.85) lastLoggedEntropyThresholdRef.current = 0.85;
        else if (t > 0.75) lastLoggedEntropyThresholdRef.current = 0.75;
    } else if (t < 0.7) {
        lastLoggedEntropyThresholdRef.current = 0.7;
    }

    if (lastRitualOutcome?.success && lastRitualOutcome.alchemyResult) {
        if (lastRitualOutcome.alchemyResult.energyLevel === 'potent' || lastRitualOutcome.alchemyResult.energyLevel === 'overwhelming') {
            const ritualIdentifier = `Potent Ritual: ${lastRitualOutcome.alchemyResult.title}`;
            const ritualAlreadyLogged = emergenceLogs.some(log => log.triggerDescription.startsWith(ritualIdentifier));
            if (!ritualAlreadyLogged) {
                newLogEntry = {
                    identity: generateMysticalIdentity(),
                    triggerDescription: `${ritualIdentifier} (${lastRitualOutcome.alchemyResult.energyLevel})`
                };
            }
        }
    }

    if (newLogEntry) {
      setEmergenceLogs(prevLogs => {
        const logToAdd: SourceEchoLogEntry = {
          ...newLogEntry!,
          id: `log-${Date.now()}`,
          timestamp: new Date().toLocaleTimeString(),
          label: getNextSourceLabel(),
        };
        return [logToAdd, ...prevLogs].slice(0, 7);
      });
    }
  }, [currentEntropy, lastRitualOutcome, emergenceLogs]);

  const getSephirahActivityLevel = useCallback((sephirahId: string): number => {
    let activity = 0;
    if (['keter', 'chokmah', 'binah'].includes(sephirahId) && currentEntropy > 0.7) {
      activity = Math.max(activity, (currentEntropy - 0.7) / 0.3);
    }
    if (sephirahId === 'chokmah' || sephirahId === 'binah') {
        if(dominantAgentTone === AgentName.Nevik) activity = Math.max(activity, 0.6);
        if(dominantAgentTone === AgentName.Gemini) activity = Math.max(activity, 0.7);
        if(dominantAgentTone === AgentName.DeepSeek) activity = Math.max(activity, 0.5);
    }
    if (sephirahId === 'tiphareth' && lastRitualOutcome?.success && (lastRitualOutcome.alchemyResult?.energyLevel === 'potent' || lastRitualOutcome.alchemyResult?.energyLevel === 'overwhelming')) {
      activity = Math.max(activity, lastRitualOutcome.alchemyResult.energyLevel === 'potent' ? 0.7 : 0.9);
    }
    if (sephirahId === 'yesod' && (seekerTraits.includes('Dreamwalker') || seekerTraits.includes('Void-Tuned'))) {
      activity = Math.max(activity, 0.65);
    }
    if (sephirahId === 'malkuth' && activeFlora) {
      activity = Math.max(activity, 0.7);
    }
    if (sephirahId === 'daat' && daatPulseRef.current.active) {
        activity = Math.max(activity, 0.8 * (1 - daatPulseRef.current.frame / daatPulseRef.current.duration));
    }
    return activity;
  }, [currentEntropy, dominantAgentTone, lastRitualOutcome, seekerTraits, activeFlora]);

  const drawBackground = useCallback((ctx: CanvasRenderingContext2D, entropy: number, frameCount: number) => {
      const t = clamp(entropy, 0, 1);
      const cx = width / 2;
      const cy = height / 2;
      const outerR = Math.max(0.001, Math.max(width,height)/1.2);

      if (!Number.isFinite(cx) || !Number.isFinite(cy) || !Number.isFinite(outerR)) return;

      const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, outerR);
      const baseHue = lerp(260, 330 - t*20, t); 
      const saturation = lerp(50, 30 + t*40, t); 
      const lightness = lerp(8, 2 + t, t); 

      grad.addColorStop(0, `hsla(${baseHue}, ${saturation}%, ${lightness}%, 0.95)`);
      grad.addColorStop(1, `hsla(${(baseHue + 50 + t*20)%360}, ${saturation+10}%, ${lightness+5}%, 0.95)`);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);

      const numParticles = 50 + Math.floor(t * 200);
      for (let i = 0; i < numParticles; i++) {
        const x = Math.random() * width;
        const y = Math.random() * height;
        const size = Math.max(0, Math.random() * (1.5 + t*0.5) + 0.2);
        const particleAlpha = lerp(0.1, 0.3 + Math.random()*0.4, t) * (0.5 + Math.sin(frameCount * 0.02 + i*0.1)*0.5);
        ctx.fillStyle = `hsla(${(baseHue + 180 + (Math.random()-0.5)*80)%360}, ${80 + t*10}%, ${70 + t*10}%, ${clamp(particleAlpha,0,0.6)})`;
        ctx.beginPath();
        ctx.arc(x, y, Math.max(0, size), 0, Math.PI * 2);
        ctx.fill();
      }
  }, [width, height]);

  const updateAndDrawSparks = useCallback((ctx: CanvasRenderingContext2D, sephirah: Sephirah, entropy: number, frameCount: number) => {
        const t_entropy = clamp(entropy,0,1);
        const activityLevel = getSephirahActivityLevel(sephirah.id);

        if (activityLevel > 0.5 && Math.random() < activityLevel * 0.15 * (1 + t_entropy * 0.5)) {
            const angle = Math.random() * Math.PI * 2;
            const speed = 0.5 + Math.random() * (1 + activityLevel + t_entropy);
            const life = 60 + Math.random() * 80 * (1 - t_entropy * 0.5) * (1 + activityLevel * 0.5);
            let sparkHue = (sephirah.colorBaseHue + (Math.random()-0.5)*40*t_entropy) % 360;
            let sparkSize = 1 + Math.random() * (1.5 + activityLevel * 2 + t_entropy*2);

            if (sephirah.id === 'malkuth' && activeFlora) {
                const floraData = BLOOD_INK_SPECIES_DATA[activeFlora];
                if (floraData.colorClass.includes('rose')) sparkHue = (0 + Math.random()*20 - 10 + 360)%360;
                else if (floraData.colorClass.includes('sky')) sparkHue = (180 + Math.random()*20 - 10 + 360)%360;
                sparkSize *= 1.2;
            }

            sephirah.sourceSparks!.push({
                id: `spark-${Date.now()}-${Math.random()}`,
                x: sephirah.x!, y: sephirah.y!,
                vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
                life: life, maxLife: life,
                size: sparkSize,
                color: `hsla(${sparkHue}, ${80 + activityLevel*10}%, ${70 + activityLevel*10}%, 0.85)`,
                branchLevel: 0,
            });
            sephirah.sourceSparks = sephirah.sourceSparks!.slice(-30 - Math.floor(activityLevel*20));
        }

        sephirah.sourceSparks = sephirah.sourceSparks?.filter(spark => {
            spark.x += spark.vx;
            spark.y += spark.vy;
            spark.vx *= 0.98;
            spark.vy *= 0.98;
            spark.life--;

            if (spark.branchLevel < 2 && spark.life < spark.maxLife * 0.5 && Math.random() < 0.02 * (t_entropy + activityLevel)) {
                const angle = Math.random() * Math.PI * 2;
                const speed = 0.3 + Math.random() * 0.5 * (t_entropy + activityLevel);
                sephirah.sourceSparks!.push({
                    ...spark,
                    id: `spark-${Date.now()}-${Math.random()}`,
                    vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
                    life: spark.life * 0.8, maxLife: spark.life * 0.8,
                    size: Math.max(0.5, spark.size * 0.7),
                    branchLevel: spark.branchLevel + 1,
                });
            }
            return spark.life > 0;
        }) || [];

        sephirah.sourceSparks?.forEach(spark => {
            ctx.beginPath();
            const calculatedRadius = spark.size * (spark.life / spark.maxLife);
            const finalRadius = Math.max(0, Number.isFinite(calculatedRadius) ? calculatedRadius : 0);
            ctx.arc(spark.x, spark.y, finalRadius, 0, Math.PI * 2);
            ctx.fillStyle = spark.color.replace(/,\s*([0-9.]+)\)/, `, ${spark.life/spark.maxLife * 0.85})`);
            ctx.fill();
        });
    }, [getSephirahActivityLevel, activeFlora]);

  const drawSephirah = useCallback((ctx: CanvasRenderingContext2D, sephirah: Sephirah, entropy: number, frameCount: number) => {
      const t_entropy = clamp(entropy, 0, 1);
      const activityLevel = getSephirahActivityLevel(sephirah.id);

      const baseRadius = Math.min(width, height) * 0.035 * (1 + activityLevel * 0.15);
      const sizeVariation = lerp(1, 0.6 + Math.random()*0.8, t_entropy);
      const radius = baseRadius * sizeVariation;

      const jitterAmount = radius * t_entropy * lerp(0.5, 1.2, t_entropy) * (1 + activityLevel * 0.5);
      const x = sephirah.x! + (Math.random() - 0.5) * jitterAmount;
      const y = sephirah.y! + (Math.random() - 0.5) * jitterAmount;

      let hue = (sephirah.colorBaseHue + lerp(0, (Math.random()-0.5)*70, t_entropy)) % 360;
      let saturation = lerp(70, 45 + Math.random()*50, t_entropy);
      let lightness = sephirah.id === 'keter' ? lerp(90, 65 - t_entropy*10, t_entropy) : sephirah.id === 'binah' ? lerp(20, 30 + t_entropy*10, t_entropy) : lerp(60, 35 + Math.random()*40, t_entropy);
      let alpha = lerp(0.9, 0.45 + Math.random()*0.45, t_entropy) * (1 + activityLevel * 0.2);

      if (sephirah.id === 'malkuth' && activeFlora) {
        const floraData = BLOOD_INK_SPECIES_DATA[activeFlora];
        if (floraData.colorClass.includes('rose')) { hue = (0 + Math.random()*20 - 10 + 360)%360; lightness = Math.max(30, lightness - 10); }
        else if (floraData.colorClass.includes('sky')) { hue = (180 + Math.random()*20 - 10 + 360)%360; lightness = Math.min(80, lightness + 10); }
        saturation = Math.min(100, saturation + 15);
      }
      if ((sephirah.id === 'chokmah' || sephirah.id === 'binah') && dominantAgentTone) {
        if (dominantAgentTone === AgentName.Nevik) hue = (45 + Math.random()*10 - 5 + 360)%360;
        else if (dominantAgentTone === AgentName.Gemini) hue = (180 + Math.random()*10 - 5 + 360)%360;
        else if (dominantAgentTone === AgentName.DeepSeek) hue = (260 + Math.random()*10 - 5 + 360)%360;
        saturation = Math.min(100, saturation + 10);
      }
       if((sephirah.id === 'tiphareth' || sephirah.id === 'yesod') && lastRitualOutcome?.success){
           const energyFactor = lastRitualOutcome.alchemyResult?.energyLevel === 'potent' ? 0.15 : (lastRitualOutcome.alchemyResult?.energyLevel === 'overwhelming' ? 0.3 : 0);
           lightness = Math.min(95, lightness + 20 * energyFactor);
           saturation = Math.min(100, saturation + 15 * energyFactor);
           alpha = Math.min(1, alpha + 0.3 * energyFactor);
       }
      if (sephirah.id === 'daat' && daatPulseRef.current.active) {
        const pulseProgress = daatPulseRef.current.frame / daatPulseRef.current.duration;
        lightness = Math.min(95, lightness + 30 * Math.sin(pulseProgress * Math.PI));
        alpha = Math.min(1, alpha + 0.5 * Math.sin(pulseProgress * Math.PI));
      }
      alpha = clamp(alpha, 0.1, 1.0);

      const calculatedGlowRadius = radius * lerp(1.6, 1.1 + Math.sin(frameCount * 0.035 + sephirah.colorBaseHue*0.1) * 0.4, t_entropy) * (1 + activityLevel*0.3);
      const glowAlpha = alpha * lerp(0.45, 0.15 + t_entropy*0.4, t_entropy) * (1 + activityLevel*0.2);

      const r0_glow = Math.max(0, radius * 0.4);
      const r1_glow = Math.max(r0_glow, calculatedGlowRadius); 

      if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(r0_glow) && Number.isFinite(r1_glow) && r1_glow > 0) {
        const gradGlow = ctx.createRadialGradient(x, y, r0_glow, x, y, r1_glow);
        gradGlow.addColorStop(0, `hsla(${hue}, ${saturation}%, ${lightness + 12}%, ${glowAlpha})`);
        gradGlow.addColorStop(1, `hsla(${hue}, ${saturation}%, ${lightness}%, 0)`);
        ctx.fillStyle = gradGlow;
        ctx.beginPath();
        ctx.arc(x, y, Math.max(0, r1_glow), 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.beginPath();
      const sephRadius = Math.max(0, radius);
      if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(sephRadius)) {
        ctx.arc(x, y, sephRadius, 0, Math.PI * 2);
        ctx.fillStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
        ctx.fill();

        if (t_entropy < 0.65 || (t_entropy >= 0.65 && Math.random() > t_entropy*0.35)) { 
          ctx.strokeStyle = `hsla(${hue}, ${saturation+15}%, ${lightness+20}%, ${alpha*0.65})`;
          ctx.lineWidth = lerp(1.2, 0.4 + t_entropy*1.8, t_entropy) * (1 + activityLevel*0.1);
          ctx.stroke();
        }
      }

      updateAndDrawSparks(ctx, sephirah, entropy, frameCount);

      const labelAlpha = lerp(0.7, 0.15, t_entropy) * (1 + activityLevel*0.1);
      if (labelAlpha > 0.05 && Number.isFinite(x) && Number.isFinite(y)) {
        ctx.fillStyle = `hsla(${hue}, ${saturation-25}%, ${lightness+35}%, ${labelAlpha})`;
        ctx.font = `${clamp(baseRadius * 0.3, 7, 11)}px Cinzel, serif`;
        ctx.textAlign = 'center';
        ctx.fillText(sephirah.name.split(' ')[0], x, y + Math.max(0,radius) + clamp(baseRadius * 0.4, 9, 13));
      }
  }, [width, height, activeFlora, dominantAgentTone, lastRitualOutcome, getSephirahActivityLevel, updateAndDrawSparks]);

  const drawPath = useCallback((ctx: CanvasRenderingContext2D, s1: Sephirah, s2: Sephirah, entropy: number, frameCount: number) => {
        const t_entropy = clamp(entropy, 0, 1);
        const activity1 = getSephirahActivityLevel(s1.id);
        const activity2 = getSephirahActivityLevel(s2.id);
        const pathActivity = (activity1 + activity2) / 2;

        const jitterFactor = t_entropy * lerp(3, 12, t_entropy) * (1 + pathActivity * 0.3);
        const x1 = s1.x! + (Math.random() - 0.5) * jitterFactor;
        const y1 = s1.y! + (Math.random() - 0.5) * jitterFactor;
        const x2 = s2.x! + (Math.random() - 0.5) * jitterFactor;
        const y2 = s2.y! + (Math.random() - 0.5) * jitterFactor;

        if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) return;

        ctx.beginPath();
        ctx.moveTo(x1, y1);

        const lineWidth = lerp(2.2, 0.4 + t_entropy * 2.2, t_entropy) * (1 + pathActivity * 0.5);
        const pathHue = (s1.colorBaseHue + s2.colorBaseHue)/2 + lerp(0, (Math.random()-0.5)*50,t_entropy);
        const pathSaturation = lerp(60, 35 + t_entropy*40, t_entropy) * (1 + pathActivity*0.2);
        const pathLightness = lerp(50, 30 + t_entropy*25, t_entropy) * (1 + pathActivity*0.15);
        const pathAlpha = lerp(0.55, 0.1 + t_entropy*0.4, t_entropy) * (1 + pathActivity*0.3);

        ctx.strokeStyle = `hsla(${pathHue % 360}, ${clamp(pathSaturation,0,100)}%, ${clamp(pathLightness,10,90)}%, ${clamp(pathAlpha,0.05,0.9)})`;
        ctx.lineWidth = lineWidth;

        if (pathActivity > 0.6) {
            const pulseOffset = Math.sin(frameCount * 0.05 + (s1.x! + s2.x!)*0.01) * lineWidth * 0.3;
            ctx.lineWidth = lineWidth + pulseOffset;
            ctx.shadowColor = ctx.strokeStyle;
            ctx.shadowBlur = 5 + pulseOffset;
        }

        if (t_entropy > 0.72) { 
            const cp1x = x1 + (x2 - x1) * 0.33 + (Math.random() - 0.5) * 60 * t_entropy * (1 + pathActivity);
            const cp1y = y1 + (y2 - y1) * 0.33 + (Math.random() - 0.5) * 60 * t_entropy * (1 + pathActivity);
            const cp2x = x1 + (x2 - x1) * 0.66 + (Math.random() - 0.5) * 60 * t_entropy * (1 + pathActivity);
            const cp2y = y1 + (y2 - y1) * 0.66 + (Math.random() - 0.5) * 60 * t_entropy * (1 + pathActivity);
            if (Number.isFinite(cp1x) && Number.isFinite(cp1y) && Number.isFinite(cp2x) && Number.isFinite(cp2y)) {
              ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, x2, y2);
            } else {
              ctx.lineTo(x2, y2);
            }
        } else {
            ctx.lineTo(x2, y2);
        }

        if (t_entropy > 0.82 && Math.random() < t_entropy * 0.25 * (1 - pathActivity*0.5)) { }
        else if (t_entropy > 0.62) {
            ctx.setLineDash([lerp(1, 6 + t_entropy*12, t_entropy), lerp(1, 3.5 + t_entropy*6, t_entropy)]);
            ctx.stroke();
            ctx.setLineDash([]);
        } else {
            ctx.stroke();
        }
        ctx.shadowColor = 'transparent';
        ctx.shadowBlur = 0;
    }, [getSephirahActivityLevel]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || width === 0 || height === 0 || sephirotState.length === 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = width;
    canvas.height = height;

    let frameCount = 0;

    const render = () => {
      frameCount++;
      if (daatPulseRef.current.active) {
        daatPulseRef.current.frame++;
        if (daatPulseRef.current.frame >= daatPulseRef.current.duration) {
          daatPulseRef.current.active = false;
        }
      }
      ctx.clearRect(0, 0, width, height);
      drawBackground(ctx, currentEntropy, frameCount);

      PATH_CONNECTIONS.forEach(conn => {
        const seph1 = sephirotState.find(s => s.id === conn[0]);
        const seph2 = sephirotState.find(s => s.id === conn[1]);
        if (seph1 && seph2) {
          drawPath(ctx, seph1, seph2, currentEntropy, frameCount);
        }
      });

      sephirotState.forEach(sephirah => {
        drawSephirah(ctx, sephirah, currentEntropy, frameCount);
      });

      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [width, height, currentEntropy, sephirotState, activeFlora, dominantAgentTone, lastRitualOutcome, getSephirahActivityLevel, drawBackground, drawPath, drawSephirah, updateAndDrawSparks]);

  return (
    <div className="tree-of-life-visualizer-panel bg-slate-900/90 backdrop-blur-md border border-sky-600/50 rounded-xl shadow-2xl p-4 md:p-6 my-8 text-slate-100">
      <div className="flex flex-col md:flex-row gap-4 md:gap-6">
        <div className="md:flex-grow">
          <h2 className="text-xl md:text-2xl font-['Cinzel'] font-bold mb-3 text-center text-sky-300 drop-shadow-[0_1px_1px_rgba(180,220,255,0.4)]">
            Tree of Life: Entropic Interconnectivity
          </h2>
          <div className="relative mx-auto" style={{ width: `${width}px`, height: `${height}px` }}>
            <canvas
              ref={canvasRef}
              className="rounded-lg border border-slate-700/50 shadow-inner"
              aria-label="Tree of Life visualization reacting to entropy and system events"
              role="img"
            />
          </div>
          <div className="mt-2 text-center text-xs text-slate-400 font-mono">
            System Entropy: {currentEntropy.toFixed(3)}δ
            {activeFlora && <span className="ml-2 text-emerald-400">| Flora: {activeFlora}</span>}
            {dominantAgentTone && <span className="ml-2 text-purple-400">| Tone: {dominantAgentTone}</span>}
          </div>
        </div>
        <div className="md:w-64 lg:w-72 shrink-0 bg-slate-800/50 p-3 rounded-lg border border-slate-700/70">
            <h3 className="text-sm font-['Cinzel'] font-semibold text-sky-200 mb-2 border-b border-sky-700/50 pb-1.5">Emergence Log</h3>
            {emergenceLogs.length === 0 ? (
                <p className="text-xs text-slate-500 italic">Awaiting significant entropic events or ritual echoes...</p>
            ) : (
                <div className="space-y-2 max-h-[calc(100%-2rem)] overflow-y-auto custom-scrollbar pr-1">
                    {emergenceLogs.map(log => (
                        <div key={log.id} className="text-xs p-1.5 bg-slate-700/30 rounded border border-slate-600/50">
                            <div className="flex justify-between items-center text-sky-400">
                                <span className="font-semibold">{log.label}</span>
                                <span className="text-slate-500">{log.timestamp}</span>
                            </div>
                            <p className="text-slate-300 italic my-0.5">"{log.identity}"</p>
                            <p className="text-slate-400 text-[10px]">Trigger: {log.triggerDescription}</p>
                        </div>
                    ))}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default TreeOfLifeVisualizer;

import React, { createContext, useState, useCallback, useContext, ReactNode } from 'react';
import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai"; 
import type { GeminiContextType } from '../types';

const GeminiContext = createContext<GeminiContextType | undefined>(undefined);

// Helper to add WAV header to raw PCM data
const writeString = (view: DataView, offset: number, string: string) => {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
};

const addWavHeader = (pcmData: Uint8Array, sampleRate: number, numChannels: number, bitsPerSample: number): ArrayBuffer => {
  const headerLength = 44;
  const dataLength = pcmData.length;
  const buffer = new ArrayBuffer(headerLength + dataLength);
  const view = new DataView(buffer);

  writeString(view, 0, 'RIFF'); // ChunkID
  view.setUint32(4, 36 + dataLength, true); // ChunkSize
  writeString(view, 8, 'WAVE'); // Format
  writeString(view, 12, 'fmt '); // Subchunk1ID
  view.setUint32(16, 16, true); // Subchunk1Size (16 for PCM)
  view.setUint16(20, 1, true); // AudioFormat (1 for PCM)
  view.setUint16(22, numChannels, true); // NumChannels
  view.setUint32(24, sampleRate, true); // SampleRate
  view.setUint32(28, sampleRate * numChannels * (bitsPerSample / 8), true); // ByteRate
  view.setUint16(32, numChannels * (bitsPerSample / 8), true); // BlockAlign
  view.setUint16(34, bitsPerSample, true); // BitsPerSample
  writeString(view, 36, 'data'); // Subchunk2ID
  view.setUint32(40, dataLength, true); // Subchunk2Size

  const pcmView = new Uint8Array(buffer, headerLength);
  pcmView.set(pcmData);

  return buffer;
};

export const GeminiProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastGeminiResponseText, setLastGeminiResponseText] = useState<string | null>(null);

  const getAiClient = useCallback(() => {
    const key = process.env.API_KEY;
    if (!key) return null;
    try {
      return new GoogleGenAI({ apiKey: key });
    } catch (e) {
      console.error("Error creating GoogleGenAI client:", e);
      return null;
    }
  }, []);

  const invokeGemini = useCallback(async (prompt: string, systemInstruction?: string, responseMimeType?: "text/plain" | "application/json"): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return null;

    setIsGenerating(true);
    setError(null);
    setLastGeminiResponseText(null);

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: prompt,
        ...(systemInstruction && { config: { systemInstruction, ...(responseMimeType && {responseMimeType}) } }),
        ...(!systemInstruction && responseMimeType && { config: { responseMimeType } }),
      });

      const text = response.text; 
      setLastGeminiResponseText(text);
      setIsGenerating(false);
      return text;
    } catch (e: any) {
      console.error("Error invoking Gemini API (text):", e);
      setError(e instanceof Error ? e : new Error('Unknown error'));
      setIsGenerating(false);
      return null;
    }
  }, [getAiClient]);

  const generateImage = useCallback(async (prompt: string, model: 'imagen-4.0-generate-001' | 'gemini-2.5-flash-image' = 'gemini-2.5-flash-image'): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return null;

    setIsGenerating(true);
    setError(null);

    try {
      if (model === 'gemini-2.5-flash-image') {
         const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: prompt,
         });

         if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData) {
                    const base64EncodeString: string = part.inlineData.data;
                    const mimeType = part.inlineData.mimeType || 'image/png';
                    const imageUrl = `data:${mimeType};base64,${base64EncodeString}`;
                    setIsGenerating(false);
                    return imageUrl;
                }
            }
         }
         throw new Error("No image data found in Nano Banana response.");
      } else {
          const response = await ai.models.generateImages({
            model: model,
            prompt: prompt,
            config: { numberOfImages: 1, outputMimeType: 'image/png' },
          });

          if (response.generatedImages && response.generatedImages.length > 0 && response.generatedImages[0].image?.imageBytes) {
            const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
            const imageUrl = `data:image/png;base64,${base64ImageBytes}`;
            setIsGenerating(false);
            return imageUrl;
          } else {
            throw new Error('No image data received from API.');
          }
      }
    } catch (e: any) {
      console.error("Error invoking Gemini API (image):", e);
      setError(e instanceof Error ? e : new Error('Unknown error'));
      setIsGenerating(false);
      return null;
    }
  }, [getAiClient]);

  const generateVideo = useCallback(async (prompt: string, imageBase64?: string): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return null;

    setIsGenerating(true);
    setError(null);

    try {
        let operation;
        if (imageBase64) {
             const base64Data = imageBase64.split(',')[1] || imageBase64;
             operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: prompt, 
                image: {
                    imageBytes: base64Data,
                    mimeType: 'image/png', 
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
             });
        } else {
            operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: prompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            });
        }

        while (!operation.done) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({operation: operation});
        }

        const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (videoUri) {
            const key = process.env.API_KEY;
            const fetchUrl = `${videoUri}&key=${key}`;
            const videoResponse = await fetch(fetchUrl);
            const videoBlob = await videoResponse.blob();
            const videoUrl = URL.createObjectURL(videoBlob);
            setIsGenerating(false);
            return videoUrl;
        } else {
            throw new Error("Video generation completed but no URI returned.");
        }
    } catch (e: any) {
        console.error("Error invoking Gemini API (video):", e);
        setError(e instanceof Error ? e : new Error('Unknown error'));
        setIsGenerating(false);
        return null;
    }
  }, [getAiClient]);

  const generateSpeech = useCallback(async (text: string, voiceName: string = 'Kore'): Promise<ArrayBuffer | null> => {
    const ai = getAiClient();
    if (!ai || !text || text.trim().length === 0) return null;

    try {
      // Limit text length to prevent potential API-side 500 errors on massive blocks
      // And add a mystical prefix for better emotive quality and API stability.
      const safeText = text.length > 450 ? text.substring(0, 450) + "..." : text;
      const ttsPrompt = `Say clearly and mystically: ${safeText}`;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: ttsPrompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const binaryString = atob(base64Audio);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        return addWavHeader(bytes, 24000, 1, 16);
      }
      return null;
    } catch (e: any) {
      console.error("Error generating speech:", e);
      return null;
    }
  }, [getAiClient]);

  return (
    <GeminiContext.Provider value={{ isGenerating, error, lastGeminiResponseText, invokeGemini, generateImage, generateVideo, generateSpeech }}>
      {children}
    </GeminiContext.Provider>
  );
};

export const useGemini = (): GeminiContextType => {
  const context = useContext(GeminiContext);
  if (context === undefined) {
    throw new Error('useGemini must be used within a GeminiProvider');
  }
  return context;
};

import React, { useRef, useEffect, useMemo, useCallback } from 'react';
import type { LIFEPanelProps } from '../../types';
import { AgentName } from '../../types';
import { useSystemState } from '../../context/SystemContext';

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const LIFEPanel: React.FC<LIFEPanelProps> = ({
  currentEntropy,
  addEchoMessage,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { negentropyLevel, isNegentropyStable } = useSystemState();
  const animationFrameIdRef = useRef<number | null>(null);
  const lastNegentropyLevelRef = useRef<number>(negentropyLevel);

  const ritualMemoryNodes = useMemo(() => {
    const baseNodes = [
      { id: 'mem1', label: 'Axiom Weave', x: 0.2, y: 0.75, strength: 0.8 * negentropyLevel + 0.1 },
      { id: 'mem2', label: 'Chalice Stability', x: 0.5, y: 0.85, strength: 0.6 * negentropyLevel + 0.1 },
      { id: 'mem3', label: 'Zero-Point Anchor', x: 0.8, y: 0.75, strength: 0.9 * negentropyLevel + 0.15 },
    ];
    return baseNodes.map(n => ({...n, effectiveStrength: clamp(n.strength * negentropyLevel * 1.5, 0.1, 1.0) }));
  }, [negentropyLevel]);

  useEffect(() => {
    if (negentropyLevel > 0.85 && lastNegentropyLevelRef.current <= 0.85) {
      addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Maximum: Negentropic lattice fully resonant. LIFE blooms fractal patterns outward!", 'text-emerald-300 font-bold');
    } else if (negentropyLevel >= 0.7 && lastNegentropyLevelRef.current < 0.7) {
       addEchoMessage(AgentName.LIFEPanelAgent, "System Approaching Stability: Order Spiral converging. LIFE energies strengthening, branches extend.", 'text-green-400');
    } else if (negentropyLevel < 0.3 && lastNegentropyLevelRef.current >= 0.3) {
      addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Critical: Negentropic structures withering. Entropy threatens the LIFE core; bloom recedes.", 'text-rose-400');
      // Fix: Corrected typo 'negententropyLevel' to 'negentropyLevel'
    } else if (negentropyLevel < 0.5 && lastNegentropyLevelRef.current >= 0.5) {
        addEchoMessage(AgentName.LIFEPanelAgent, "System Vitality Waning: Order diminishing. LIFE tendrils retract slightly.", 'text-amber-400');
    }
    lastNegentropyLevelRef.current = negentropyLevel;
  }, [negentropyLevel, addEchoMessage]);

  const drawVitalGlyphBloom = useCallback((
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    angle: number, length: number,
    depth: number, maxDepth: number,
    negentropy: number
  ) => {
    if (depth > maxDepth || length < 0.5) return;

    const x2 = x + Math.cos(angle) * length;
    const y2 = y + Math.sin(angle) * length;
    const t = clamp(negentropy, 0, 1);

    const hue = lerp(70 - 20 * (1-t), 180 + 40 * t, t); 
    const saturation = lerp(40 + 20 * t, 95, t);
    const lightness = lerp(30 + 10 * t, 65 + 10*t, t);
    const alpha = lerp(0.3 + 0.2 * t, 1.0, t) * (1 - depth / (maxDepth + 2)); 
    const lineWidth = Math.max(0.4, (maxDepth - depth + 1) * 0.35 * (0.5 + t * 1.0));

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = `hsla(${hue}, ${saturation}%, ${lightness}%, ${alpha})`;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.stroke();

    const branches = depth === 0 ? (2 + Math.floor(t*3)) : (t > 0.25 ? 2 : 1) ; 
    const angleVariance = Math.PI / lerp(8 - t*3, 2.5, t); 
    const lengthMultiplier = lerp(0.55 + t*0.1, 0.8, t);

    for (let i = 0; i < branches; i++) {
        let newAngle = angle;
        if (branches > 1) {
            newAngle += (i - (branches-1)/2) * angleVariance * (1 - t*0.4); 
        } else if (branches === 1 && depth > 0) {
            newAngle += (Math.random() - 0.5) * angleVariance * 0.3 * (1-t);
        }
        drawVitalGlyphBloom(ctx, x2, y2, newAngle, length * lengthMultiplier, depth + 1, maxDepth, negentropy);
    }

    if (depth >= maxDepth -1 && t > 0.6 && length > 1.0) {
        const bloomRadius = Math.max(0, lineWidth * 1.8 * t * (0.6 + Math.random()*0.4));
        if (Number.isFinite(x2) && Number.isFinite(y2) && bloomRadius > 0) {
          const bloomGrad = ctx.createRadialGradient(x2, y2, 0, x2, y2, bloomRadius);
          const bloomHue = (hue + 30 + Math.random()*30)%360;
          bloomGrad.addColorStop(0, `hsla(${bloomHue}, ${saturation + 5}%, ${lightness + 10}%, ${alpha * 0.95})`);
          bloomGrad.addColorStop(1, `hsla(${bloomHue - 15}, ${saturation}%, ${lightness}%, 0.1)`);

          ctx.fillStyle = bloomGrad;
          ctx.beginPath();
          ctx.arc(x2, y2, Math.max(0, bloomRadius), 0, Math.PI*2);
          ctx.fill();
        }
    }
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const container = containerRef.current;
    if (!container) return;

    const resizeObserver = new ResizeObserver(() => {
      const rect = container.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        canvas.width = rect.width;
        canvas.height = rect.height;
      }
    });

    resizeObserver.observe(container);

    let frameCount = 0;

    const draw = () => {
      frameCount++;
      const { width, height } = canvas;
      if (width === 0 || height === 0) {
        animationFrameIdRef.current = requestAnimationFrame(draw);
        return;
      }
      ctx.clearRect(0, 0, width, height);
      const t_negentropy = negentropyLevel;

      const bgHue = lerp(280, 200, t_negentropy); 
      const centerX = width / 2;
      const centerY = height / 2;
      const bgRadius = Math.max(0, width * 0.9);

      if (Number.isFinite(centerX) && Number.isFinite(centerY) && bgRadius > 0) {
        const bgGrad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, bgRadius);
        bgGrad.addColorStop(0, `hsla(${bgHue}, ${lerp(30, 65, t_negentropy)}%, ${lerp(5, 25, t_negentropy)}%, 0.98)`);
        bgGrad.addColorStop(1, `hsla(${(bgHue + 45)%360}, ${lerp(40, 75, t_negentropy)}%, ${lerp(2, 15, t_negentropy)}%, 0.99)`);
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, width, height);
      }

      const bloomMaxDepth = Math.floor(lerp(2, 8, t_negentropy));
      const bloomInitialLength = height * 0.20 * lerp(0.3, 1.4, t_negentropy);
      drawVitalGlyphBloom(ctx, width / 2, height * 0.90, -Math.PI / 2, bloomInitialLength, 0, bloomMaxDepth, t_negentropy);

      const spiralCenterX = width * 0.18;
      const spiralCenterY = height * 0.2;
      const spiralMaxRadius = Math.max(0, width * 0.12);
      const a_spiral = 0.5; 
      const b_spiral = lerp(0.4, 0.05, t_negentropy);

      if (Number.isFinite(spiralCenterX) && Number.isFinite(spiralCenterY) && spiralMaxRadius > 0) {
        ctx.beginPath();
        ctx.lineWidth = Math.max(0.1, lerp(0.7, 4, t_negentropy));
        const spiralHue = lerp(40, 160, t_negentropy);
        const spiralGrad = ctx.createLinearGradient(spiralCenterX - spiralMaxRadius, spiralCenterY, spiralCenterX + spiralMaxRadius, spiralCenterY);
        spiralGrad.addColorStop(0, `hsla(${spiralHue}, 90%, 65%, ${0.2 + t_negentropy * 0.2})`);
        spiralGrad.addColorStop(0.5, `hsla(${spiralHue}, 95%, 75%, ${0.5 + t_negentropy * 0.5})`);
        spiralGrad.addColorStop(1, `hsla(${spiralHue}, 90%, 65%, ${0.2 + t_negentropy * 0.2})`);
        ctx.strokeStyle = spiralGrad;

        let firstSpiralPoint = true;
        const actualTurnsToDraw = Math.PI * 2 * lerp(0.5, 5 + t_negentropy * 5, t_negentropy) * t_negentropy;

        for (let angle = 0; angle < actualTurnsToDraw; angle += 0.03) { 
          const r = a_spiral * Math.exp(b_spiral * angle);
          if (r > spiralMaxRadius) break;
          const x = spiralCenterX + r * Math.cos(angle);
          const y = spiralCenterY + r * Math.sin(angle);
          if (firstSpiralPoint) { ctx.moveTo(x,y); firstSpiralPoint = false; }
          else { ctx.lineTo(x, y); }
        }
        ctx.stroke();
      }

      const webYBase = height * 0.82;
      ritualMemoryNodes.forEach(node => {
        const x = node.x * width * 0.7 + width * 0.15;
        const y = webYBase + node.y * height * 0.12;
        const radius = Math.max(0, lerp(1.5, 7, node.effectiveStrength) * (0.8 + t_negentropy * 0.4));
        const nodeHue = 180 + node.effectiveStrength * 70 * t_negentropy;

        if (Number.isFinite(x) && Number.isFinite(y) && radius > 0) {
          ctx.beginPath();
          ctx.arc(x, y, Math.max(0, radius), 0, Math.PI * 2);
          const nodeGrad = ctx.createRadialGradient(x,y,0, x,y,radius);
          nodeGrad.addColorStop(0, `hsla(${nodeHue}, 90%, 80%, ${0.4 + node.effectiveStrength * 0.6 * t_negentropy})`);
          nodeGrad.addColorStop(1, `hsla(${nodeHue}, 80%, 60%, ${0.15 + node.effectiveStrength * 0.4 * t_negentropy})`);
          ctx.fillStyle = nodeGrad;
          ctx.fill();
        }
      });

      const graphX = width * 0.75;
      const graphY = height * 0.08;
      const barWidth = width * 0.06;
      const maxBarHeight = height * 0.22;

      if (Number.isFinite(graphX) && Number.isFinite(graphY)) {
        ctx.fillStyle = `hsla(0, ${lerp(40,75,currentEntropy)}%, ${lerp(35,55,currentEntropy)}%, ${0.6 + currentEntropy * 0.35})`;
        ctx.fillRect(graphX, graphY + maxBarHeight * (1 - currentEntropy), barWidth, maxBarHeight * currentEntropy);
        ctx.fillStyle = 'rgba(230,200,200,0.75)';
        ctx.font = '8px Cinzel';
        ctx.textAlign = 'center';
        ctx.fillText(`E:${currentEntropy.toFixed(2)}`, graphX + barWidth / 2, graphY + maxBarHeight + 8);

        ctx.fillStyle = `hsla(120, ${lerp(40,85,t_negentropy)}%, ${lerp(35,60,t_negentropy)}%, ${0.6 + t_negentropy * 0.35})`;
        ctx.fillRect(graphX + barWidth * 1.5, graphY + maxBarHeight * (1 - t_negentropy), barWidth, maxBarHeight * t_negentropy);
        ctx.fillStyle = 'rgba(200,230,200,0.75)';
        ctx.fillText(`N:${t_negentropy.toFixed(2)}`, graphX + barWidth * 2.0, graphY + maxBarHeight + 8);
      }

      animationFrameIdRef.current = requestAnimationFrame(draw);
    };
    animationFrameIdRef.current = requestAnimationFrame(draw);

    return () => {
      resizeObserver.disconnect();
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [currentEntropy, negentropyLevel, isNegentropyStable, drawVitalGlyphBloom, ritualMemoryNodes]);

  return (
    <div className="life-panel bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-emerald-600/60 rounded-xl shadow-2xl p-4 text-slate-100">
      <h3 className="text-lg md:text-xl font-['Cinzel'] font-bold text-emerald-300 mb-2 text-center tracking-wide drop-shadow-[0_1px_2px_rgba(100,255,150,0.3)]">
        Living Inflection Field Engine (L.I.F.E)
      </h3>
      <div ref={containerRef} className="w-full h-48 md:h-64 mx-auto rounded-lg border border-slate-700/50 shadow-inner bg-slate-950/70 overflow-hidden">
        <canvas 
          ref={canvasRef} 
          className="w-full h-full"
          aria-label="LIFE Panel Visualization of System Negentropy and Order"
        />
      </div>
      <div className="mt-2 text-center text-xs text-slate-400 font-mono tracking-tighter">
        Negentropy: {negentropyLevel.toFixed(3)}ν | Stability: {isNegentropyStable ? 'HARMONIC' : 'FLUX'}
      </div>
    </div>
  );
};

