const CONNECTIONS = [
  ['The Void Edge', 'Crystal Spire'],
  ['The Void Edge', 'Axiom Forge'],
  ['The Void Edge', 'Nebula Market'],
  ['The Void Edge', 'Obsidian Cathedral'],
  ['The Void Edge', 'Sector 14'],
