        setActiveProfile(null);
        setSeekerTraits([]);
        setPlacedGlyphs([]);
        setConnections([]);
        setArtifacts([]);
        setRpgState(undefined);
        setCurrentEntropy(0.1);
        setNegentropyLevel(0.5);
        setEchoLog([]);

        setStage('ONBOARDING');
