const SeekerProfileDashboardPanel: React.FC<{ 
    profile: SeekerProfile | null, 
    allProfiles: SeekerProfile[],
    onSelectProfile: (p: SeekerProfile) => void,
    onUpdateProfile: (p: SeekerProfile) => void,
    onReset: () => void,
    addEchoMessage: (s: string, t: string, c: string) => void,
    activePartyIds: string[],
    onSetParty: (ids: string[]) => void
}> = ({ profile, allProfiles, onSelectProfile, onUpdateProfile, onReset, addEchoMessage, activePartyIds, onSetParty }) => {

    const togglePartyMember = (id: string) => {
        if (activePartyIds.includes(id)) {
            onSetParty(activePartyIds.filter(pid => pid !== id));
            addEchoMessage(AgentName.System, "Identity shard dismissed from active party.", "text-slate-400");
        } else {
            if (activePartyIds.length >= 3) {
                addEchoMessage(AgentName.System, "Chrono-Leash maximum reached. Max 3 shards.", "text-rose-400");
                return;
            }
            onSetParty([...activePartyIds, id]);
            addEchoMessage(AgentName.System, "Identity shard summoned to active party.", "text-emerald-400");
        }
    };

    const handleDownload = () => {
        if (!profile) return;
        const el = document.getElementById('dashboard-active-shard');
        if (el) {
