// --- Helper: Robust JSON Parsing ---
const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    console.error("RPGNexus: JSON Parsing Failed", e);
    return null;
  }
};

// --- Helper: URL to Base64 ---
const urlToBase64 = async (url: string): Promise<string> => {
    if (url.startsWith('data:')) return url;
    try {
        const response = await fetch(url);
        const blob = await response.blob();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    } catch (e) {
        return "";
    }
};

// --- Helper: Party Summary Builder ---
const getPartySummary = (party: SeekerProfile[]): string => {
    if (party.length === 0) return "A lone wanderer";
    return party.map(p => `${p.name} (the ${p.race} ${p.class})`).join(', ');
};

interface RPGScanResultLocation {
  description: string;
  color?: string;
  risk?: string;
  icon?: string;
  genre?: string;
}

const FALLBACK_LOCATIONS: Record<string, RPGScanResultLocation> = {
  "The Void Edge": { description: "A precipice where reality dissolves into static.", color: "text-slate-400", risk: "Extreme", icon: "ri-mist-line" },
  "Crystal Spire": { description: "A tower of singing glass reaching into the Aethel.", color: "text-cyan-300", risk: "Low", icon: "ri-building-2-line" },
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Scan for Anomalies', type: 'ritual', risk: 0.2, isDynamic: false },
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width, height, addEchoMessage, activeProfile, allProfiles, onUpdateProfile, currentEntropy, onArtifactCreated, savedState, onSaveState, onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();
  const logContainerRef = useRef<HTMLDivElement>(null);

  // -- Party Derived State --
  const activeParty = useMemo(() => {
    const ids = savedState?.activePartyIds || (activeProfile ? [activeProfile.id] : []);
    return allProfiles.filter(p => ids.includes(p.id));
  }, [allProfiles, savedState?.activePartyIds, activeProfile]);

  // -- State --
  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "System Initialized. Awaiting Insertion Coordinates...", type: 'system', timestamp: Date.now() }],
    activeQuests: [],
    lastActionTimestamp: Date.now(),
    vitals: {},
    activePartyIds: activeProfile ? [activeProfile.id] : [],
    availableActions: DEFAULT_ACTIONS,
    achievements: [],
    knownLocations: [],
    currentSceneDescription: "The initialization void.",
    currentSceneImageUrl: null,
    sceneHistory: [] 
  });

  const [scanResults, setScanResults] = useState<Record<string, RPGScanResultLocation> | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [viewMode, setViewMode] = useState<'scene' | 'map'>('scene');
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);

  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    if (logContainerRef.current) logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
  }, [gameState.narrativeHistory]); 

  const handleScanSector = async () => {
    if (isScanning || isGenerating) return;
    setIsScanning(true);
    const prompt = `Generate 3 unique RPG locations for a party composed of: ${getPartySummary(activeParty)}. Entropy: ${currentEntropy.toFixed(2)}. Output strictly as JSON. Keys are location names. Values are objects with "description" (1 sentence), "risk" (Low/Extreme), "icon" (ri-* class).`;
    try {
      const response = await invokeGemini(prompt, "You are a JSON generator.");
      setScanResults(cleanAndParseJSON(response) || FALLBACK_LOCATIONS);
    } catch (err) { setScanResults(FALLBACK_LOCATIONS); }
    finally { setIsScanning(false); }
  };

  const handleTravel = async (locationName: string, locationData: Partial<RPGScanResultLocation>) => {
    if (activeParty.length === 0) { addEchoMessage(AgentName.System, "Cannot venture forth without a party member.", "text-rose-400"); return; }
    setScanResults(null); 
    setViewMode('scene');
    setIsProcessingTurn(true);

    const prompt = `Game Master. Party: ${getPartySummary(activeParty)}. Bios: ${activeParty.map(p => `${p.name}: ${p.bio}`).join(' | ')}.
    Arriving at: ${locationName}. 
    1. Vivid scene description (2 sentences).
    2. 3 Actions. 
    Return JSON: {"description": "...", "actions": [{"label": "...", "risk": 0.2}]}`;

    try {
      const response = await invokeGemini(prompt, "Return valid JSON only.");
      const data = cleanAndParseJSON<any>(response);
      if (data) {
        const imagePrompt = `Epic wide angle concept art. SCENE: ${data.description}. CHARACTERS: The party (${getPartySummary(activeParty)}) is exploring. Stylized, cinematic, no text.`;
        const refImages = await Promise.all(activeParty.map(p => urlToBase64(p.avatarImageUrl || "")));

        generateImage(imagePrompt, 'gemini-2.5-flash-image', refImages.filter(Boolean)).then(url => {
          if (url) setGameState(prev => ({ ...prev, currentSceneImageUrl: url, sceneHistory: [...prev.sceneHistory, { imageUrl: url, location: locationName as RPGGameLocation, description: data.description, timestamp: Date.now() }] }));
        });

        setGameState(prev => ({
          ...prev,
          currentLocation: locationName as RPGGameLocation,
          currentSceneDescription: data.description,
          availableActions: data.actions || DEFAULT_ACTIONS,
          narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }, { text: data.description, type: 'narration', timestamp: Date.now() }]
        }));
      }
    } catch (e) { console.error(e); }
    finally { setIsProcessingTurn(false); }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn || activeParty.length === 0) return;
    setIsProcessingTurn(true);
    setGameState(prev => ({ ...prev, narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }] }));

    const history = gameState.narrativeHistory.slice(-5).map(h => h.text).join('\n');
    const prompt = `GM. Party: ${getPartySummary(activeParty)}. Location: ${gameState.currentLocation}. Action: ${actionLabel}. 
    History: ${history}. 
    Determine result. Use party member skills. 
    Return JSON: {"resultText": "...", "vitalsDelta": {"seekerID": {"integrity": -10}}, "newActions": []}`;

    try {
        const response = await invokeGemini(prompt, "Return JSON only.");
        const outcome = cleanAndParseJSON<any>(response);
        if (outcome) {
            setGameState(prev => {
                const nextVitals = { ...prev.vitals };
                if (outcome.vitalsDelta) {
                    Object.entries(outcome.vitalsDelta).forEach(([id, delta]: [string, any]) => {
                        const current = nextVitals[id] || { integrity: 100, sanity: 100 };
                        nextVitals[id] = { 
                            integrity: Math.max(0, Math.min(100, current.integrity + (delta.integrity || 0))),
                            sanity: Math.max(0, Math.min(100, current.sanity + (delta.sanity || 0)))
                        };
                    });
                }
                return { ...prev, vitals: nextVitals, availableActions: outcome.newActions || DEFAULT_ACTIONS, narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }] };
            });
            if (isNarratorEnabled) generateSpeech(outcome.resultText);
        }
    } catch (e) {}
    finally { setIsProcessingTurn(false); }
  };

  if (!gameState.currentLocation || activeParty.length === 0) {
      return (
          <div className="h-full w-full bg-slate-950 flex flex-col items-center justify-center p-8 text-center" style={{ width, height }}>
             <h3 className="text-2xl font-cinzel text-indigo-300 mb-4">Expedition Ready</h3>
             <p className="text-slate-500 mb-8 max-w-sm">Summon at least one Identity Shard from the Expedition Hub to venture into the Codex.</p>
             {scanResults ? (
                <div className="grid grid-cols-2 gap-4">
                    {Object.entries(scanResults).map(([name, data]) => (
                        <button key={name} onClick={() => handleTravel(name, data)} className="p-4 border border-indigo-500/30 rounded-xl hover:bg-indigo-900/20 text-left transition-all">
                            <div className="font-bold text-white">{name}</div>
                            <div className="text-[10px] text-slate-500">{data.description}</div>
                        </button>
                    ))}
                </div>
             ) : (
                <Button onClick={handleScanSector} disabled={isScanning || activeParty.length === 0} className="bg-indigo-600 px-8">SCAN LOCAL AETHER</Button>
             )}
          </div>
      );
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-slate-950 flex flex-col" style={{ width, height }}>
        {viewMode === 'scene' && (
            <div className="absolute inset-0">
                {gameState.currentSceneImageUrl && <img src={gameState.currentSceneImageUrl} className="w-full h-full object-cover" />}
                <div className="absolute inset-0 bg-gradient-to-b from-slate-950/80 via-transparent to-slate-950/90 pointer-events-none"></div>
            </div>
        )}

        <div className="relative z-10 flex flex-col h-full p-4 pointer-events-none">
            <div className="flex justify-between items-start pointer-events-auto">
                <div className="bg-slate-950/80 p-3 rounded-lg border border-white/10 backdrop-blur-md">
                    <h3 className="text-indigo-300 font-bold font-cinzel">{gameState.currentLocation}</h3>
                    <div className="text-[9px] text-slate-500 font-mono">Party: {activeParty.map(p=>p.name).join(', ')}</div>
                </div>
                <button onClick={() => setViewMode(viewMode === 'scene' ? 'map' : 'scene')} className="p-3 bg-slate-950/80 border border-white/10 rounded-lg text-slate-400 hover:text-white backdrop-blur-md">
                    <i className={`ri-${viewMode === 'scene' ? 'map-2' : 'landscape'}-line`}></i>
                </button>
            </div>

            <div className="mt-auto flex flex-col lg:flex-row gap-4 pointer-events-auto h-2/3">
                <div className="lg:w-1/3 flex flex-col gap-2 overflow-y-auto custom-scrollbar-thin">
                    {gameState.availableActions.map(action => (
                        <button key={action.label} onClick={() => handleAction(action.label, action.risk)} disabled={isProcessingTurn} className="w-full text-left p-3 rounded-lg border border-slate-700 bg-slate-900/60 hover:bg-slate-800 transition-all">
                            <div className="text-sm font-bold text-slate-100">{action.label}</div>
                            <div className="text-[8px] text-slate-500 uppercase">{Math.round(action.risk * 100)}% Danger</div>
                        </button>
                    ))}
                </div>
                <div className="flex-grow bg-black/40 border border-white/5 rounded-lg p-4 overflow-y-auto custom-scrollbar font-cormorant text-lg italic text-slate-200 backdrop-blur-sm" ref={logContainerRef}>
                    {gameState.narrativeHistory.map((h, i) => (
                        <div key={i} className={`mb-4 ${h.type === 'action' ? 'text-indigo-300 font-bold font-mono text-xs not-italic' : ''}`}>
                            {h.type === 'action' && <span className="mr-2">>></span>}
                            {h.text}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    </div>
  );
};

