                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase tracking-widest">Biomorph (Race)</label>
                            <select value={race} onChange={(e) => setRace(e.target.value as SeekerAvatarType)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-3 text-slate-100 focus:border-indigo-500 outline-none">
