                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                            className="p-5 rounded-xl bg-indigo-950/20 border border-indigo-500/30 shadow-inner"
                        >
                            <div className="flex items-center gap-3 mb-3 text-indigo-300">
                                <i className="ri-dna-line text-2xl"></i>
                                <span className="font-cinzel font-bold text-lg uppercase tracking-wider">Biomorph: {activeRaceInfo?.name}</span>
                            </div>
                            <p className="text-sm text-slate-300 font-cormorant leading-relaxed italic">
                                {activeRaceInfo?.description || "Analyzing biomorphic data..."}
