                                {activeClassInfo?.description || "Deciphering archetypal role..."}
                            </p>
                            <div className="mt-4 flex gap-1.5">
                                <span className="w-1.5 h-1.5 bg-purple-500 rounded-full animate-pulse"></span>
                                <span className="w-1.5 h-1.5 bg-purple-500 rounded-full animate-pulse delay-75"></span>
                                <span className="w-1.5 h-1.5 bg-purple-500 rounded-full animate-pulse delay-150"></span>
                            </div>
                        </motion.div>
                    </AnimatePresence>

                    <div className="p-4 rounded-lg bg-black/40 border border-slate-800 text-[10px] font-mono text-slate-500 uppercase tracking-widest text-center">
                        <i className="ri-shield-check-line mr-2 text-emerald-500"></i>
