                    </div>
                </div>
            </div>

            <div className="flex justify-center pt-4">
                <Button onClick={weaveIdentity} className="px-20 py-5 bg-emerald-600 font-cinzel font-bold text-xl tracking-[0.3em] shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 transition-all rounded-sm">
                    WEAVE SHARD
                </Button>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
