import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { 
    AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS, SEEKER_VISUAL_FILTERS,
    HAIR_COLORS, EYE_COLORS, SKIN_TONES, ARMOR_TYPES, WEAPON_TYPES, SPECIAL_ABILITIES 
} from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';

// --- Random Name Generator Data ---
const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');

  // -- Form State --
  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [customClassName, setCustomClassName] = useState("");
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [age, setAge] = useState(1); 
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(SeekerAuraColor.Violet);
  const [intent, setIntent] = useState("");

  // -- New Physical/Tactical State --
  const [hairColor, setHairColor] = useState(HAIR_COLORS[0]);
  const [eyeColor, setEyeColor] = useState(EYE_COLORS[0]);
  const [skinTone, setSkinTone] = useState(SKIN_TONES[0]);
  const [armorType, setArmorType] = useState(ARMOR_TYPES[0].id);
  const [weapon, setWeapon] = useState(WEAPON_TYPES[0].id);
  const [specialAbility, setSpecialAbility] = useState(SPECIAL_ABILITIES[0].id);

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const { invokeGemini, generateImage } = useGemini();

  const isCustomClass = seekerClass === SeekerClass.Custom;
  const effectiveClassName = isCustomClass ? (customClassName || "Nameless Archetype") : seekerClass;

  const activeRaceInfo = useMemo(() => AVATAR_RACES.find(r => r.id === race), [race]);
  const activeClassInfo = useMemo(() => SEEKER_CLASSES.find(c => c.id === seekerClass), [seekerClass]);

  const handleRandomize = () => {
    globalSoundEngine.playUIFeedback('click');
    setName(generateRandomName());
    setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
    setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * (SEEKER_CLASSES.length - 1))].id as SeekerClass); 
    setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
    setAge(Math.floor(Math.random() * 499) + 1);
    setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setSecondaryAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);

    setHairColor(HAIR_COLORS[Math.floor(Math.random() * HAIR_COLORS.length)]);
    setEyeColor(EYE_COLORS[Math.floor(Math.random() * EYE_COLORS.length)]);
    setSkinTone(SKIN_TONES[Math.floor(Math.random() * SKIN_TONES.length)]);
    setArmorType(ARMOR_TYPES[Math.floor(Math.random() * ARMOR_TYPES.length)].id);
    setWeapon(WEAPON_TYPES[Math.floor(Math.random() * WEAPON_TYPES.length)].id);
    setSpecialAbility(SPECIAL_ABILITIES[Math.floor(Math.random() * SPECIAL_ABILITIES.length)].id);
  };

  const weaveIdentity = async () => {
    if (!name.trim()) return;
    setStep('weaving');
    globalSoundEngine.playSFX('pulse');

    const selectedArmor = ARMOR_TYPES.find(a=>a.id === armorType)?.name || armorType;
    const selectedWeapon = WEAPON_TYPES.find(w=>w.id === weapon)?.name || weapon;
    const selectedAbility = SPECIAL_ABILITIES.find(s=>s.id === specialAbility)?.name || specialAbility;

    try {
        const prompt = `Synthesize a unique Seeker bio for: 
        Name: ${name} | Race: ${race} | Archetype: ${effectiveClassName} | Gender: ${gender} | Age: ${age} cycles.
        Appearance: ${skinTone} skin, ${hairColor} hair, ${eyeColor} eyes.
        Loadout: Equipped with ${selectedArmor} and wielding a ${selectedWeapon}. 
        Ability: Master of ${selectedAbility}.
        Intent: "${intent}". 
        Output JSON: {"bio": "2 sentences"}`;

        const response = await invokeGemini(prompt, "Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A traveler of the stars."}');

        const visualGenderDescriptor = gender === SeekerGender.Male ? "masculine" : gender === SeekerGender.Female ? "feminine" : "androgynous";
        const imagePrompt = `A high-detail cinematic close-up portrait of a clearly ${visualGenderDescriptor} ${gender.toLowerCase()} ${race} ${effectiveClassName}. 
        Physical Traits: ${skinTone} skin tone, ${hairColor} hair, ${eyeColor} glowing eyes.
        Gear: Wearing ${selectedArmor}, wielding a ${selectedWeapon} visibly. 
        Visual age: roughly ${age} years in appearance relative to its species. 
        Aesthetic: cosmic sci-fi, glowing ${aura.toLowerCase()} and ${secondaryAura.toLowerCase()} energy resonance surrounding them. 
        Highly detailed face. Cinematic lighting. No text or logos.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            id: `seeker-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            generatedAt: Date.now(),
            level: 1, experience: 0, flux: 100, inventory: [],
            selfTraits: ["Newborn"], codexTraits: ["Seeker"],
            name, race, class: effectiveClassName, gender, age,
            energyAlignment: SeekerEnergyAlignment.Balanced,
            auraColor: aura, auraSecondaryColor: secondaryAura,
            visualFilter: SeekerVisualFilter.Standard,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio,
            skinTone, hairColor, eyeColor, armorType, weapon, specialAbility
        };
        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) { setStep('reveal'); }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div key="briefing" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }} className="max-w-2xl text-center space-y-8">
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest">IDENTITY INITIALIZATION</h2>
            <p className="text-slate-300 font-cormorant text-xl">The Codex requires an avatar of intention. Weave your first shard.</p>
            <Button onClick={() => setStep('calibration')} className="px-12 py-4 bg-indigo-600 font-bold">CALIBRATE SHARD</Button>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div key="calibration" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -50 }} className="max-w-7xl w-full space-y-8 bg-slate-900/40 p-8 rounded-2xl border border-indigo-500/20 backdrop-blur-md overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div className="flex justify-between items-center">
                <h3 className="text-3xl font-cinzel text-indigo-300">SHARD PARAMETERS</h3>
                <button onClick={handleRandomize} className="px-4 py-2 bg-indigo-950 border border-indigo-500/50 rounded-lg text-indigo-400 hover:text-white transition-all"><i className="ri-dice-fill mr-2"></i>RANDOMIZE</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                {/* Left Side: Inputs */}
                <div className="lg:col-span-7 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-1.5">
                            <label className="text-xs text-indigo-400 font-bold uppercase tracking-widest">Designation (Name)</label>
