                </div>
            </motion.div>
        )}

        {initStep === 3 && scanResults && (
            <motion.div key="step3" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="flex-grow flex flex-col overflow-hidden">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-cinzel text-cyan-300">Insertion Points Materialized</h3>
                    <Button onClick={() => setInitStep(2)} className="text-[10px] bg-slate-800 py-1">BACK TO INTENTION</Button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 overflow-y-auto custom-scrollbar pr-2 pb-4">
                    {/* Explicitly cast Object.entries results to fix 'unknown' type errors for location data mapping */}
                    {(Object.entries(scanResults) as [string, RPGScanResultLocation][]).map(([name, data]) => (
                        <button 
                            key={name}
                            onClick={() => { handleTravel(name, data); setInitStep(0); }}
                            className="flex flex-col p-5 bg-slate-800/80 border-2 border-slate-600 rounded-xl hover:bg-slate-700 hover:border-cyan-500 transition-all text-left transform hover:-translate-y-1 shadow-lg"
                        >
                            <div className="flex items-center justify-between mb-2">
                                <i className={`${data.icon} text-2xl ${data.color}`}></i>
                                <span className="text-[9px] uppercase font-bold tracking-widest bg-black/40 px-2 py-1 rounded text-slate-400">{data.risk} RISK</span>
                            </div>
                            <h4 className="font-cinzel font-bold text-base text-slate-100 mb-1">{name}</h4>
                            <p className="text-xs text-slate-400 font-cormorant leading-tight h-10 overflow-hidden line-clamp-3">{data.description}</p>
                        </button>
                    ))}
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );

  return (
    <div className="relative w-full overflow-hidden bg-slate-950 font-sans flex flex-col" style={{ width: width || '100%', height: height || '100%' }}>
        {initStep > 0 ? renderInitialization() : (
            <>
                {viewMode === 'scene' && (
                    <div className="absolute inset-0 z-0">
                        {currentSceneVideoUrl ? <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" /> : 
                        gameState.currentSceneImageUrl ? <img src={gameState.currentSceneImageUrl} className="w-full h-full object-cover" /> :
                        <div className="w-full h-full bg-slate-900" />}
                        <div className="absolute inset-0 bg-gradient-to-b from-slate-950/90 via-transparent to-slate-950/90 pointer-events-none" />
                    </div>
                )}
                {viewMode === 'map' && <div className="absolute inset-0 z-0"><LoreMapVisualizer currentLocationId={gameState.currentLocation} onTravel={(n) => handleTravel(n.id, {description: n.description})} width={1000} height={800} /></div>}

                <div className="relative z-10 flex flex-col h-full p-4 pointer-events-none">
                    <div className="flex justify-between items-start pointer-events-auto shrink-0 mb-4">
                        <div className="bg-slate-950/70 backdrop-blur-md border border-slate-700 p-3 rounded-xl shadow-xl max-w-sm">
                            <h3 className="text-indigo-300 font-bold font-cinzel text-lg flex items-center gap-2 mb-1">
                                <i className="ri-map-pin-user-fill"></i> {gameState.currentLocation}
                            </h3>
                            <div className="text-[10px] text-amber-400 font-mono uppercase tracking-widest bg-amber-950/40 px-2 py-0.5 rounded border border-amber-800/30 truncate">
                                Mission: {gameState.customMissionObjective || "Exploration"}
                            </div>
                        </div>
                        <div className="flex gap-1">
                            <button onClick={() => setViewMode(prev => prev === 'scene' ? 'map' : 'scene')} className="bg-slate-900/80 p-3 rounded-lg border border-slate-700 text-white"><i className="ri-map-2-line"></i></button>
                            <button onClick={handleEndQuest} className="bg-rose-900/80 p-3 rounded-lg border border-rose-700 text-white"><i className="ri-stop-circle-line"></i></button>
                        </div>
                    </div>

                    <div className="flex-grow flex flex-col lg:flex-row gap-4 min-h-0 relative">
                        <div className="lg:w-1/3 flex flex-col gap-2 pointer-events-auto mt-auto">
                            <div className="flex gap-2 bg-slate-950/40 p-2 rounded-lg border border-slate-700 backdrop-blur-sm">
                                <input type="text" value={customActionInput} onChange={e => setCustomActionInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAction(customActionInput)} placeholder="What do you do?" className="flex-grow bg-transparent text-sm text-slate-100 outline-none" />
                                <button onClick={() => handleAction(customActionInput)} className="text-indigo-400"><i className="ri-send-plane-fill"></i></button>
                            </div>
                            <div className="flex flex-col gap-1.5 overflow-y-auto max-h-[30vh]">
                                {gameState.availableActions.map((act, i) => (
                                    <button key={i} onClick={() => handleAction(act.label, act.risk)} className="text-left p-3 rounded-lg border border-slate-700 bg-slate-900/60 hover:bg-slate-800 transition-all">
                                        <span className="text-sm font-semibold text-slate-100">{act.label}</span>
                                        <span className="text-[8px] float-right text-slate-500 uppercase">{Math.round(act.risk*100)}% RISK</span>
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="lg:w-2/3 flex flex-col pointer-events-auto">
                            <div ref={logContainerRef} className="bg-slate-950/40 backdrop-blur-md border border-slate-700 rounded-lg p-4 overflow-y-auto flex-grow shadow-2xl">
                                {gameState.narrativeHistory.slice(-8).map((entry, i) => (
                                    <div key={i} className={`mb-3 text-sm ${entry.type === 'action' ? 'text-indigo-300 font-bold' : 'text-slate-300 font-cormorant'}`}>
                                        {entry.type === 'action' && "> "} {entry.text}
                                    </div>
                                ))}
                                {isProcessingTurn && <div className="animate-pulse text-indigo-400 text-xs font-mono">GM calculating fate...</div>}
                            </div>
                        </div>
                    </div>
                </div>
            </>
        )}
    </div>
  );
};

