  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [currentlyPlayingText, setCurrentlyPlayingText] = useState<string | null>(null);
  const [foundLoot, setFoundLoot] = useState<MarketItem | null>(null);

  const cinemaEngineRef = useRef<QuestCinemaEngine | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    return () => {
        if (cinemaEngineRef.current) cinemaEngineRef.current.dispose();
        if (audioContextRef.current) audioContextRef.current.close();
    }
  }, []);

  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  useEffect(() => {
    if (logContainerRef.current) {
        logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [gameState.narrativeHistory]); 

  const playNarrativeAudio = async (text: string) => {
    if (!text) return;
    setIsPlayingAudio(true);
    setCurrentlyPlayingText(text);
    try {
        if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();
        const audioData = await generateSpeech(text);
        if (audioData) {
            const buffer = await audioContextRef.current.decodeAudioData(audioData);
            const source = audioContextRef.current.createBufferSource();
            source.buffer = buffer;
            source.connect(audioContextRef.current.destination);
            source.onended = () => { setIsPlayingAudio(false); setCurrentlyPlayingText(null); };
            source.start(0);
        }
    } catch (e) { setIsPlayingAudio(false); setCurrentlyPlayingText(null); }
  };

  const handleScanSector = async () => {
    if (isScanning || isGenerating || !selectedStyleId) return;
    setIsScanning(true);
    globalSoundEngine.playSFX('click');

    const style = RPG_ADVENTURE_STYLES.find(s => s.id === selectedStyleId);
    const missionContext = missionInput ? `THE SEEKER PRIME MISSION IS: "${missionInput}". WEAVE THIS OBJECTIVE INTO THE LOCATIONS.` : "Standard exploration.";
    const prompt = `Generate exactly 6 unique, evocative RPG locations for a ${style?.name} campaign. 
    Entropy: ${currentEntropy.toFixed(2)}. 
    ${missionContext}
    Style focus: ${style?.name}.
    Output strictly as JSON. Keys are location names.
    Values must be objects with:
    - "description": string (1-2 sentences)
    - "color": string (Tailwind text class)
    - "risk": string ("Low", "Medium", "High", "Extreme")
    - "icon": string (RemixIcon class)
    - "genre": string ("${style?.name}")`;

    try {
      const response = await invokeGemini(prompt, "You are an RPG JSON location generator.");
      const locations = cleanAndParseJSON<Record<string, RPGScanResultLocation>>(response);
      setScanResults(locations || FALLBACK_LOCATIONS);
      setGameState(prev => ({ ...prev, customMissionObjective: missionInput }));
      setInitStep(3);
    } catch (err) {
      setScanResults(FALLBACK_LOCATIONS);
    } finally {
      setIsScanning(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: Partial<RPGScanResultLocation>) => {
    setScanResults(null); 
    setViewMode('scene');
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null);
    addEchoMessage(AgentName.RPGNexusAgent, `Vectoring to ${locationName}...`, "text-cyan-300");
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev,
      currentLocation: locationName as RPGGameLocation,
      narrativeHistory: [...prev.narrativeHistory, { text: `Arrived at ${locationName}.`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const style = RPG_ADVENTURE_STYLES.find(s => s.id === selectedStyleId);
      const missionContext = gameState.customMissionObjective ? `PRIME MISSION: "${gameState.customMissionObjective}".` : "";
      const textPrompt = `You are GM for ${style?.name}. 
      Seeker: ${activeProfile?.name} (${activeProfile?.race} ${activeProfile?.class}).
      ${missionContext}
      Location: "${locationName}" (${locationData.description}).
      Current Entropy: ${currentEntropy}.
      Provide vivid sensory description (2 sentences) and 3 logical actions.
      Return JSON: { "description": "...", "actions": [ { "id": "act_1", "label": "...", "type": "explore", "risk": 0.2 }, ... ], "quest": { "title": "...", "description": "...", "rewards": { "xp": 100 } } }`;

      const textResponseRaw = await invokeGemini(textPrompt, "Return valid JSON only.");
      const textData = cleanAndParseJSON<any>(textResponseRaw);

      if (textData) {
        const charDesc = getCharacterVisualPrompt(activeProfile);
        const imagePrompt = `Epic Environment Concept Art, ${style?.name} style. SCENE: ${textData.description}. CHARACTER: ${charDesc} exploring. Ensure character matches reference strictly. Pure visual, no text.`;
        const referenceImage = activeProfile?.avatarImageUrl ? await urlToBase64(activeProfile.avatarImageUrl) : undefined;

        generateImage(imagePrompt, 'gemini-2.5-flash-image', referenceImage).then(url => {
          if (url) {
            setGameState(prev => ({ 
                ...prev, 
                currentSceneImageUrl: url,
                sceneHistory: [...(prev.sceneHistory || []), { imageUrl: url, location: locationName as RPGGameLocation, description: textData.description, timestamp: Date.now() }] 
            }));
          }
        });

        setGameState(prev => ({
          ...prev,
          currentSceneDescription: textData.description,
          availableActions: textData.actions || DEFAULT_ACTIONS,
          activeQuests: [...prev.activeQuests, { ...textData.quest, id: `quest-${Date.now()}`, status: 'active' }].slice(-3),
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }]
        }));
        if (isNarratorEnabled) playNarrativeAudio(textData.description);
      }
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setFoundLoot(null);
    globalSoundEngine.playSFX('click');
    setGameState(prev => ({ ...prev, narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }] }));

    const style = RPG_ADVENTURE_STYLES.find(s => s.id === selectedStyleId);
    const historyContext = gameState.narrativeHistory.slice(-10).map(h => `[${h.type.toUpperCase()}] ${h.text}`).join('\n');
    const missionContext = gameState.customMissionObjective ? `PRIME MISSION: "${gameState.customMissionObjective}".` : "";

    const prompt = `GM Logic (${style?.name}). Location: ${gameState.currentLocation}. Action: "${actionLabel}". Entropy: ${currentEntropy}. ${missionContext}
    RECENT HISTORY:\n${historyContext}\nDetermine outcome: 1-2 sentence result. Provide 3 NEW logical actions with risks. 20% chance of "lootItem".
    Return JSON: { "resultText": "...", "deltaIntegrity": 0, "deltaSanity": 0, "deltaFlux": 10, "newActions": [...], "lootItem": { "name": "...", "rarity": "Rare", "type": "Relic", "description": "..." } }`;

    try {
        const response = await invokeGemini(prompt, "Return valid JSON only.");
        const outcome = cleanAndParseJSON<any>(response);
        if (outcome) {
            const newIntegrity = Math.max(0, Math.min(100, (gameState.vitals?.integrity || 100) + (outcome.deltaIntegrity || 0)));
            const newSanity = Math.max(0, Math.min(100, (gameState.vitals?.sanity || 100) + (outcome.deltaSanity || 0)));
            // Fix: Removed non-existent setDuelState call
            setGameState(prev => ({
                ...prev,
                vitals: { integrity: newIntegrity, sanity: newSanity },
                availableActions: outcome.newActions || DEFAULT_ACTIONS,
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }]
            }));
            const charDesc = getCharacterVisualPrompt(activeProfile);
            const actionImagePrompt = `Cinematic Action, ${style?.name} style. RESULT: ${outcome.resultText}. CHARACTER: ${charDesc}. Purely visual.`;
            const referenceImage = activeProfile?.avatarImageUrl ? await urlToBase64(activeProfile.avatarImageUrl) : undefined;
            generateImage(actionImagePrompt, 'gemini-2.5-flash-image', referenceImage).then(url => {
                 if (url) setGameState(prev => ({ ...prev, currentSceneImageUrl: url, sceneHistory: [...(prev.sceneHistory || []), { imageUrl: url, location: prev.currentLocation, description: outcome.resultText, timestamp: Date.now() }] }));
            });
            if (outcome.lootItem) {
                const newItem: MarketItem = { id: `loot-${Date.now()}`, name: outcome.lootItem.name, type: outcome.lootItem.type || 'Relic', rarity: outcome.lootItem.rarity || ArtifactRarity.Common, description: outcome.lootItem.description || "An interesting find.", visualPromptMod: "artifact", cost: 100, icon: 'ri-treasure-map-line' };
                setFoundLoot(newItem);
            }
            if (isNarratorEnabled) playNarrativeAudio(outcome.resultText);
        }
    } finally { setIsProcessingTurn(false); }
  };

  const handleEndQuest = () => {
    if (confirm("Conclude current campaign? State will be reset.")) {
        setGameState({ ...gameState, currentLocation: '', sceneHistory: [], narrativeHistory: [{ text: "Nexus Reset.", type: 'system', timestamp: Date.now() }] });
        setInitStep(1);
        setSelectedStyleId(null);
        setMissionInput("");
    }
  };

  const handleGenerateSceneVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      try {
          const prompt = `Subtle cinematic motion, 4k detail, ${selectedStyleId} atmosphere. No text.`;
          const videoUrl = await generateVideo(prompt, gameState.currentSceneImageUrl);
          if (videoUrl) setCurrentSceneVideoUrl(videoUrl);
      } catch (e) {
          console.error(e);
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleCompileStoryVideo = async () => {
      if (isCompilingStory || !gameState.sceneHistory?.length) return;
      setIsCompilingStory(true);
      try {
          if (!cinemaEngineRef.current) cinemaEngineRef.current = new QuestCinemaEngine();
          const slides = gameState.sceneHistory.map(s => ({ imageUrl: s.imageUrl, text: s.description }));
          const blob = await cinemaEngineRef.current.compileVideo(slides, setCompilationProgress, generateSpeech);
          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a'); a.href = url; a.download = `Quest_${Date.now()}.webm`; a.click();
          }
      } catch (e) {
          console.error(e);
      } finally {
          setIsCompilingStory(false);
      }
  };

  const renderInitialization = () => (
    <div className="flex flex-col h-full bg-slate-950 p-8 overflow-hidden relative">
      {/* Dynamic Scanlines Decor */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.03] z-0" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }}></div>

      {/* Progress HUD */}
      <div className="flex justify-between items-center mb-10 bg-slate-900/40 backdrop-blur-md p-6 rounded-[2rem] border border-white/5 shadow-2xl relative z-10">
          <div className="flex items-center gap-12">
              {[1, 2, 3].map((step) => (
                  <div key={step} className="flex items-center gap-4 group">
                      <div className={`w-10 h-10 rounded-full border-2 flex items-center justify-center font-cinzel transition-all duration-700
                          ${initStep >= step ? 'border-indigo-400 bg-indigo-600/20 text-white shadow-[0_0_20px_rgba(129,140,248,0.4)]' : 'border-slate-800 bg-slate-900 text-slate-600'}`}>
                          {step}
                      </div>
                      <div className="flex flex-col">
                          <span className={`text-[10px] font-mono tracking-widest ${initStep >= step ? 'text-indigo-400' : 'text-slate-600'}`}>PHASE</span>
                          <span className={`text-xs font-bold font-cinzel tracking-widest ${initStep >= step ? 'text-white' : 'text-slate-700'}`}>
                              {step === 1 ? 'ARCHITECTURE' : step === 2 ? 'INTENTION' : 'VECTOR SCAN'}
                          </span>
                      </div>
                      {step < 3 && <div className={`w-16 h-px ${initStep > step ? 'bg-indigo-500 shadow-[0_0_10px_#6366f1]' : 'bg-slate-800'}`} />}
                  </div>
              ))}
          </div>

          <button onClick={() => setIsFullscreen(!isFullscreen)} className="p-4 rounded-2xl bg-white/5 border border-white/10 text-slate-400 hover:text-white transition-all hover:bg-white/10">
              <i className={`ri-${isFullscreen ? 'fullscreen-exit' : 'fullscreen'}-line text-xl`}></i>
          </button>
      </div>

      <AnimatePresence mode="wait">
        {initStep === 1 && (
            <motion.div key="step1" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="flex-grow flex flex-col overflow-hidden relative z-10">
                <div className="text-center mb-8">
                    <h3 className="text-4xl font-cinzel font-bold text-white mb-2 tracking-[0.2em]">The Great Architecture</h3>
                    <p className="text-slate-500 font-cormorant italic text-lg">Select a core narrative modality to materialize your timeline.</p>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-4 overflow-y-auto custom-scrollbar pr-4 pb-12 pt-2">
                    {RPG_ADVENTURE_STYLES.map(style => (
                        <button 
                            key={style.id}
                            onClick={() => { setSelectedStyleId(style.id); setInitStep(2); globalSoundEngine.playSFX('click'); }}
                            className={`p-6 rounded-[2.5rem] border-2 text-center transition-all duration-500 group relative overflow-hidden flex flex-col items-center justify-center gap-4
                                ${selectedStyleId === style.id 
                                    ? 'bg-indigo-900/40 border-indigo-400 shadow-[0_0_40px_rgba(129,140,248,0.2)]' 
                                    : 'bg-slate-900/40 border-white/5 hover:border-indigo-500/50 hover:bg-indigo-950/20'}`}
                        >
                            <div className={`w-16 h-16 rounded-3xl bg-black/40 border border-white/10 flex items-center justify-center text-4xl transition-transform duration-500 group-hover:scale-110 group-hover:rotate-6 ${style.accent}`}>
                                <i className={style.icon}></i>
                            </div>
                            <div className="flex flex-col gap-1">
                                <div className="text-[10px] font-mono text-slate-500 uppercase tracking-widest">Construct</div>
                                <div className="text-xs font-bold font-cinzel text-slate-100 group-hover:text-white transition-colors">{style.name}</div>
                            </div>
                            {/* Decorative Corner */}
                            <div className="absolute top-0 right-0 w-8 h-8 bg-gradient-to-bl from-white/5 to-transparent rounded-bl-3xl" />
                        </button>
                    ))}
                </div>
            </motion.div>
        )}

        {initStep === 2 && (
            <motion.div key="step2" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -50 }} className="flex-grow flex flex-col items-center justify-center max-w-4xl mx-auto space-y-12 relative z-10 w-full">
                <div className="text-center space-y-4">
                    <div className="w-24 h-24 rounded-full bg-indigo-600/10 border-2 border-indigo-500/50 flex items-center justify-center text-5xl text-indigo-400 shadow-[0_0_60px_rgba(99,102,241,0.2)] mx-auto mb-6">
                        <i className="ri-quill-pen-line"></i>
                    </div>
                    <h3 className="text-5xl font-cinzel font-bold text-white tracking-widest">Define Your Intention</h3>
                    <p className="text-slate-400 text-xl italic font-cormorant">"A Seeker without intent is but a ghost in the machine."</p>
                </div>

                <div className="w-full relative group">
                    <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2rem] blur opacity-25 group-focus-within:opacity-100 transition duration-1000"></div>
                    <textarea 
                        value={missionInput}
                        onChange={(e) => setMissionInput(e.target.value)}
                        placeholder="e.g. Recover the Obsidian Rose from the Heart of the Singularity..."
                        className="w-full bg-slate-900/90 border border-white/10 rounded-[2rem] p-10 text-2xl text-slate-100 focus:outline-none resize-none h-64 italic backdrop-blur-xl transition-all font-cormorant shadow-2xl"
                    />
                </div>

                <div className="flex gap-8 w-full max-w-2xl">
                    <button onClick={() => setInitStep(1)} className="flex-1 bg-slate-800/50 hover:bg-slate-800 text-slate-400 font-cinzel font-bold py-5 rounded-2xl border border-white/5 transition-all tracking-widest uppercase text-sm">Return to Architecture</button>
                    <button 
                        onClick={handleScanSector} 
                        disabled={isScanning} 
                        className="flex-1 bg-indigo-600 hover:bg-indigo-500 text-white font-cinzel font-bold py-5 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.4)] transition-all tracking-widest uppercase text-sm flex items-center justify-center gap-3"
                    >
                        {isScanning ? <i className="ri-loader-4-line animate-spin text-2xl"></i> : <><i className="ri-radar-line text-xl"></i> Materialize Modalities</>}
                    </button>
                </div>
            </motion.div>
        )}

        {initStep === 3 && scanResults && (
            <motion.div key="step3" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex-grow flex flex-col overflow-hidden relative z-10">
                <div className="flex justify-between items-center mb-10">
                    <div className="space-y-1">
                        <h3 className="text-3xl font-cinzel font-bold text-cyan-400 tracking-widest">Vector Modalities Detected</h3>
                        <p className="text-slate-500 font-mono text-[10px] uppercase tracking-[0.4em]">Resonance Locked // Insertion Points Ready</p>
                    </div>
                    <button onClick={() => setInitStep(2)} className="px-8 py-3 bg-slate-800 hover:bg-slate-700 text-[10px] font-bold rounded-full border border-white/10 uppercase tracking-[0.3em] transition-all">Refine Intention</button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-y-auto custom-scrollbar pr-4 pb-12">
                    {(Object.entries(scanResults) as [string, RPGScanResultLocation][]).map(([name, data]) => (
                        <button 
                            key={name}
                            onClick={() => { handleTravel(name, data); setInitStep(0); }}
                            className="flex flex-col p-10 bg-slate-900/60 border-2 border-white/5 rounded-[3rem] hover:bg-indigo-900/20 hover:border-cyan-500/50 hover:shadow-[0_0_60px_rgba(34,211,238,0.15)] transition-all text-left transform hover:-translate-y-3 group relative overflow-hidden backdrop-blur-md"
                        >
                            <div className="flex items-center justify-between mb-8">
                                <div className={`w-20 h-20 rounded-[2rem] bg-black/50 border border-white/10 flex items-center justify-center text-5xl ${data.color}`}>
                                    <i className={data.icon || 'ri-map-pin-2-line'}></i>
                                </div>
                                <div className="flex flex-col items-end">
                                    <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest mb-1">Threat Assessment</span>
                                    <span className={`text-xs uppercase font-bold tracking-widest px-4 py-1.5 rounded-full border ${data.risk === 'Extreme' ? 'bg-rose-950 text-rose-400 border-rose-500/40' : data.risk === 'High' ? 'bg-orange-950 text-orange-400 border-orange-500/40' : 'bg-emerald-950 text-emerald-400 border-emerald-500/40'}`}>{data.risk}</span>
                                </div>
                            </div>
                            <h4 className="font-cinzel font-bold text-3xl text-white mb-4 group-hover:text-cyan-300 transition-colors tracking-tight">{name}</h4>
                            <p className="text-lg text-slate-400 font-cormorant leading-relaxed line-clamp-3 italic mb-8">{data.description}</p>

                            <div className="mt-auto flex items-center gap-3 text-cyan-400 font-mono text-[10px] uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                                <i className="ri-arrow-right-line"></i> Initiate Vector Travel
                            </div>

                            {/* Background Pattern */}
                            <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/[0.02] rounded-full blur-3xl group-hover:bg-cyan-400/5 transition-colors" />
                        </button>
                    ))}
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );

  const containerClasses = isFullscreen 
    ? "fixed inset-0 z-[9999] bg-slate-950" 
    : "relative w-full overflow-hidden bg-slate-950 rounded-2xl shadow-2xl border border-white/5";

  return (
    <div className={containerClasses} style={{ width: isFullscreen ? '100vw' : width || '100%', height: isFullscreen ? '100vh' : height || '100%' }}>
        {initStep > 0 ? renderInitialization() : (
            <div className="h-full w-full relative flex flex-col overflow-hidden">
                {/* BACKGROUND LAYER */}
                <div className="absolute inset-0 z-0">
                    <AnimatePresence mode="wait">
                        <motion.div key={gameState.currentSceneImageUrl} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1.5 }} className="w-full h-full">
                            {currentSceneVideoUrl ? (
                                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
                            ) : gameState.currentSceneImageUrl ? (
                                <img src={gameState.currentSceneImageUrl} className="w-full h-full object-cover" />
                            ) : (
                                <div className="w-full h-full bg-slate-900 animate-pulse" />
                            )}
                        </motion.div>
                    </AnimatePresence>
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-slate-950/80" />
                    <div className="absolute inset-0 bg-black/20" />
                </div>

                {/* MAP OVERLAY LAYER */}
                {viewMode === 'map' && (
                    <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-xl animate-fade-in">
                         <div className="absolute top-6 left-6 z-10">
                            <button onClick={() => setViewMode('scene')} className="p-4 rounded-full bg-slate-800 border border-white/20 text-white hover:bg-slate-700 shadow-2xl">
                                <i className="ri-close-line text-2xl"></i>
                            </button>
                         </div>
                         <LoreMapVisualizer 
                             currentLocationId={gameState.currentLocation} 
                             onTravel={(n) => { handleTravel(n.id, {description: n.description}); setViewMode('scene'); }} 
                             width={window.innerWidth} 
                             height={window.innerHeight} 
                         />
                    </div>
                )}

                {/* IMMERSIVE HUD LAYER */}
                <div className="relative z-10 flex flex-col h-full pointer-events-none p-6 md:p-10">

                    {/* Top HUD */}
                    <div className="flex justify-between items-start pointer-events-auto shrink-0 mb-8">
                        <div className="bg-slate-900/40 backdrop-blur-xl border border-white/10 p-6 rounded-3xl shadow-2xl max-w-lg transition-transform hover:scale-105 duration-500">
                            <div className="flex items-center gap-4 mb-3">
                                <div className="w-12 h-12 rounded-2xl bg-indigo-600/20 border border-indigo-400/30 flex items-center justify-center text-2xl text-indigo-300">
                                    <i className="ri-map-pin-user-line"></i>
                                </div>
                                <div>
                                    <h3 className="text-2xl font-cinzel font-bold text-white tracking-widest">{gameState.currentLocation}</h3>
                                    <p className="text-[10px] font-mono text-cyan-400 uppercase tracking-[0.3em]">Sector Registered // Secure Link</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-6 mt-4">
                                <div className="flex-1">
                                    <div className="flex justify-between text-[10px] font-mono text-slate-400 uppercase mb-1"><span>Integrity</span><span>{gameState.vitals.integrity}%</span></div>
                                    <div className="h-1.5 bg-slate-800 rounded-full overflow-hidden"><motion.div animate={{ width: `${gameState.vitals.integrity}%` }} className="h-full bg-rose-500" /></div>
                                </div>
                                <div className="flex-1">
                                    <div className="flex justify-between text-[10px] font-mono text-slate-400 uppercase mb-1"><span>Sanity</span><span>{gameState.vitals.sanity}%</span></div>
                                    <div className="h-1.5 bg-slate-800 rounded-full overflow-hidden"><motion.div animate={{ width: `${gameState.vitals.sanity}%` }} className="h-full bg-purple-500" /></div>
                                </div>
