                            className="p-5 rounded-xl bg-indigo-950/20 border border-indigo-500/30 shadow-inner min-h-[140px]"
                        >
                            <div className="flex items-center gap-3 mb-3 text-indigo-300">
                                <i className="ri-dna-line text-2xl"></i>
                                <span className="font-cinzel font-bold text-lg uppercase tracking-wider">Biomorph: {activeRaceInfo?.name}</span>
                            </div>
                            <p className="text-sm text-slate-300 font-cormorant leading-relaxed italic">
                                {activeRaceInfo?.description || "Analyzing biomorphic data..."}
                            </p>
                        </motion.div>
                    </AnimatePresence>

                    <AnimatePresence mode="wait">
                        <motion.div 
                            key={`class-${seekerClass}`}
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                            className="p-5 rounded-xl bg-purple-950/20 border border-purple-500/30 shadow-inner min-h-[140px]"
                        >
                            <div className="flex items-center gap-3 mb-3 text-purple-300">
                                <i className="ri-sparkling-2-line text-2xl"></i>
                                <span className="font-cinzel font-bold text-lg uppercase tracking-wider">Archetype: {activeClassInfo?.name}</span>
                            </div>
                            <p className="text-sm text-slate-300 font-cormorant leading-relaxed italic">
                                {activeClassInfo?.description || "Deciphering archetypal role..."}
                            </p>
                        </motion.div>
                    </AnimatePresence>

                    <div className="p-4 rounded-lg bg-black/40 border border-slate-800 text-[10px] font-mono text-slate-500 uppercase tracking-widest text-center">
                        <i className="ri-shield-check-line mr-2 text-emerald-500"></i>
                        Parameters Verified for Insertion
                    </div>

                    <div className="flex-grow flex items-end pt-4">
                        <Button onClick={weaveIdentity} className="w-full py-6 bg-emerald-600 font-cinzel font-bold text-xl tracking-[0.3em] shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 transition-all rounded-sm">
                            WEAVE SHARD
                        </Button>
                    </div>
                </div>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
          <motion.div key="weaving" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-8 text-indigo-300">
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                <span className="absolute inset-0 flex items-center justify-center text-2xl font-mono animate-pulse">WEAVING</span>
            </div>
            <p className="font-mono text-xs uppercase tracking-widest text-slate-500">Syncing with Gemini Dreaming...</p>
          </motion.div>
        )}

        {step === 'reveal' && generatedProfile && (
          <motion.div key="reveal" initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} className="flex flex-col items-center gap-8">
             <div className="w-[320px] md:w-[400px]">
                <div className="relative rounded-xl border-[8px] border-amber-500 bg-slate-950 flex flex-col overflow-hidden shadow-[0_0_50px_rgba(245,158,11,0.3)]" style={{ aspectRatio: '2.5/3.5' }}>
                    <div className="bg-black/60 p-4 border-b border-white/10 z-10 flex justify-between items-center">
                        <div className="flex flex-col">
                            <span className="font-cinzel font-bold text-white text-xl tracking-wider">{generatedProfile.name}</span>
                            <span className="text-[8px] font-mono text-amber-500 uppercase">{generatedProfile.gender} // Cycle {generatedProfile.age}</span>
                        </div>
                        <div className="text-[10px] font-mono text-amber-500 px-2 py-0.5 rounded border border-amber-500/30">SHARD 01</div>
                    </div>
                    <div className="absolute inset-0 z-0">{generatedProfile.avatarImageUrl && <img src={generatedProfile.avatarImageUrl} className="w-full h-full object-cover" />}</div>
                    <div className="flex-1 z-10"></div>
                    <div className="bg-slate-950/90 p-5 text-slate-100 font-cormorant italic z-10 border-t border-white/10 text-lg leading-relaxed shadow-[0_-10px_30px_rgba(0,0,0,0.8)]">
                        {generatedProfile.bio}
                    </div>
                </div>
             </div>
             <Button onClick={() => onComplete(generatedProfile)} className="px-16 py-5 bg-emerald-600 text-2xl font-cinzel font-bold tracking-widest shadow-lg shadow-emerald-500/20">ENTER CODEX</Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

