import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerBodyType, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS, ALL_ALIGNMENTS_LIST, STARTER_WEAPONS, STARTER_OUTFITS, SEEKER_BODY_TYPES, EYE_COLORS, HAIR_COLORS, SKIN_TONES } from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';

const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
}

export const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');

  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [age, setAge] = useState(25);
  const [bodyType, setBodyType] = useState<SeekerBodyType>(SeekerBodyType.Mesomorphic);
  const [alignment, setAlignment] = useState<SeekerEnergyAlignment>(SeekerEnergyAlignment.Balanced);
  const [weaponId, setWeaponId] = useState(STARTER_WEAPONS[0].id);
  const [outfitId, setOutfitId] = useState(STARTER_OUTFITS[0].id);
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(SeekerAuraColor.Violet);
  const [intent, setIntent] = useState("");

  const [eyeColor, setEyeColor] = useState(EYE_COLORS[0]);
  const [hairColor, setHairColor] = useState(HAIR_COLORS[0]);
  const [skinTone, setSkinTone] = useState(SKIN_TONES[0]);

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const { invokeGemini, generateImage } = useGemini();

  const activeRaceInfo = useMemo(() => AVATAR_RACES.find(r => r.id === race), [race]);
  const activeClassInfo = useMemo(() => SEEKER_CLASSES.find(c => c.id === seekerClass), [seekerClass]);
  const activeWeapon = useMemo(() => STARTER_WEAPONS.find(w => w.id === weaponId), [weaponId]);
  const activeOutfit = useMemo(() => STARTER_OUTFITS.find(o => o.id === outfitId), [outfitId]);

  const handleRandomize = () => {
    globalSoundEngine.playUIFeedback('click');
    setName(generateRandomName());
    setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
    setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
    setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
    setAge(Math.floor(Math.random() * 900) + 1);
    setBodyType(SEEKER_BODY_TYPES[Math.floor(Math.random() * SEEKER_BODY_TYPES.length)]);
    setAlignment(ALL_ALIGNMENTS_LIST[Math.floor(Math.random() * ALL_ALIGNMENTS_LIST.length)]);
    setWeaponId(STARTER_WEAPONS[Math.floor(Math.random() * STARTER_WEAPONS.length)].id);
    setOutfitId(STARTER_OUTFITS[Math.floor(Math.random() * STARTER_OUTFITS.length)].id);
    setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setSecondaryAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setEyeColor(EYE_COLORS[Math.floor(Math.random() * EYE_COLORS.length)]);
    setHairColor(HAIR_COLORS[Math.floor(Math.random() * HAIR_COLORS.length)]);
    setSkinTone(SKIN_TONES[Math.floor(Math.random() * SKIN_TONES.length)]);
    addEchoMessage(AgentName.System, "Randomized Identity Resonance.", "text-cyan-400");
  };

  const weaveIdentity = async () => {
    if (!name.trim()) {
        alert("A Seeker must have a name to be woven into the thread.");
        return;
    }
    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Anchoring identity: ${name}...`, "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity bio for the Tri-Sophian Codex based on these choices:
        Name: ${name} | Race: ${race} | Class: ${seekerClass} | Gender: ${gender} | Age: ${age} cycles | Build: ${bodyType} | Alignment: ${alignment}
        Eyes: ${eyeColor} | Hair: ${hairColor} | Skin: ${skinTone}
        Starting Gear: ${activeWeapon?.name} and ${activeOutfit?.name}
        Aura: ${aura}/${secondaryAura} | Intent: "${intent || 'Unknown'}"
        Provide strictly valid JSON with key "bio": string (2-sentence backstory).`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A Seeker emerging from the Aetheric mists."}');

        const imagePrompt = `High-detail cinematic portrait of a ${age} cycle old ${gender} ${race} ${seekerClass}. 
        Physicality: ${bodyType} build with ${skinTone} skin, ${hairColor} hair, and ${eyeColor} eyes.
        Equipment: Wearing ${activeOutfit?.name} (${activeOutfit?.visualPromptMod}), Wielding ${activeWeapon?.name} (${activeWeapon?.visualPromptMod}).
        Visual style: cosmic sci-fi, bioluminescent ${aura.toLowerCase()} and ${secondaryAura.toLowerCase()} aura. 
        Intention: ${intent}. No text in image.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1, experience: 0, flux: 100, 
            inventory: [activeWeapon!, activeOutfit!],
            selfTraits: ["Calibrated"], codexTraits: ["Seeker"],
            name, race, class: seekerClass, gender, age, bodyType,
            eyeColor, hairColor, skinTone,
            energyAlignment: alignment,
            auraColor: aura, auraSecondaryColor: secondaryAura,
            visualFilter: SeekerVisualFilter.Standard,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio,
            equippedWeapon: activeWeapon,
            equippedOutfit: activeOutfit
        };
        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) { setStep('reveal'); }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div key="briefing" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }} className="max-w-2xl text-center space-y-8">
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest drop-shadow-glow">IDENTITY INITIALIZATION</h2>
            <p className="text-slate-300 font-cormorant text-xl">The Tri-Sophian Codex responds to the soul-signal of those who enter. Project your **Identity** to begin.</p>
            <Button onClick={() => setStep('calibration')} className="px-12 py-4 bg-indigo-600 font-bold text-lg tracking-widest">INITIALIZE CALIBRATION</Button>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div key="calibration" initial={{ opacity: 0, x: 50 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -50 }} className="max-w-7xl w-full space-y-6 bg-slate-900/40 p-8 rounded-2xl border border-indigo-500/20 backdrop-blur-md overflow-y-auto max-h-[95vh] custom-scrollbar">
            <div className="flex justify-between items-center mb-2">
                <h3 className="text-3xl font-cinzel text-indigo-300">RESONANCE CALIBRATION</h3>
                <button onClick={handleRandomize} className="px-4 py-2 bg-indigo-950 border border-indigo-500/50 rounded-lg text-indigo-400 hover:text-white transition-all shadow-lg animate-pulse" title="Randomize All Parameters">
                    <i className="ri-dice-fill mr-2"></i>ROLL THE FATES
                </button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                {/* Left Side: Customization Sections */}
                <div className="lg:col-span-8 space-y-6">

                    {/* Identification */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Designation</label>
                            <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 focus:border-indigo-500 outline-none text-sm" placeholder="Name..."/>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Biomorph</label>
                            <select value={race} onChange={(e) => setRace(e.target.value as SeekerAvatarType)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 focus:border-indigo-500 outline-none text-sm">
                                {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Archetype</label>
                            <select value={seekerClass} onChange={(e) => setSeekerClass(e.target.value as SeekerClass)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 focus:border-indigo-500 outline-none text-sm">
                                {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    </div>

                    {/* Biology */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 bg-black/20 p-4 rounded-xl border border-white/5 shadow-inner">
                        <div className="space-y-1">
                            <label className="text-[10px] text-sky-400 font-bold uppercase tracking-widest">Build</label>
                            <select value={bodyType} onChange={(e) => setBodyType(e.target.value as SeekerBodyType)} className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-xs outline-none">
                                {SEEKER_BODY_TYPES.map(bt => <option key={bt} value={bt}>{bt.split(' ')[0]}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-sky-400 font-bold uppercase tracking-widest">Skin Tone</label>
                            <select value={skinTone} onChange={(e) => setSkinTone(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-xs outline-none">
                                {SKIN_TONES.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-sky-400 font-bold uppercase tracking-widest">Hair Color</label>
                            <select value={hairColor} onChange={(e) => setHairColor(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-xs outline-none">
                                {HAIR_COLORS.map(h => <option key={h} value={h}>{h}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-sky-400 font-bold uppercase tracking-widest">Eye Color</label>
                            <select value={eyeColor} onChange={(e) => setEyeColor(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-xs outline-none">
                                {EYE_COLORS.map(eye => <option key={eye} value={eye}>{eye}</option>)}
                            </select>
                        </div>
                    </div>

                    {/* Orientation & Age */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Gender Orientation</label>
                            <select value={gender} onChange={(e) => setGender(e.target.value as SeekerGender)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 outline-none text-sm">
                                {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Origin Age: {age} Cycles</label>
                            <div className="pt-3 px-2">
                                <input type="range" min="1" max="999" value={age} onChange={(e) => setAge(parseInt(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
                                <div className="flex justify-between text-[8px] text-slate-500 font-mono mt-1 uppercase"><span>Newborn</span><span>Ancient</span></div>
                            </div>
                        </div>
                    </div>

                    {/* Equipment & Intent */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="space-y-1">
                            <label className="text-[10px] text-rose-400 font-bold uppercase tracking-widest">Weapon</label>
                            <select value={weaponId} onChange={(e) => setWeaponId(e.target.value)} className="w-full bg-slate-950 border border-rose-500/30 rounded-lg p-2 text-slate-100 focus:border-rose-500 outline-none text-xs">
                                {STARTER_WEAPONS.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest">Armor</label>
                            <select value={outfitId} onChange={(e) => setOutfitId(e.target.value)} className="w-full bg-slate-950 border border-emerald-500/30 rounded-lg p-2 text-slate-100 focus:border-emerald-500 outline-none text-xs">
                                {STARTER_OUTFITS.map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Energy Alignment</label>
                            <select value={alignment} onChange={(e) => setAlignment(e.target.value as SeekerEnergyAlignment)} className="w-full bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 focus:border-indigo-500 outline-none text-xs">
                                {ALL_ALIGNMENTS_LIST.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                        </div>
                    </div>

                    <div className="space-y-1">
                        <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Intent</label>
                        <textarea value={intent} onChange={(e) => setIntent(e.target.value)} className="w-full h-12 bg-slate-950 border border-indigo-500/30 rounded-lg p-2 text-slate-100 resize-none text-xs italic focus:border-indigo-500 outline-none" placeholder="What drives your journey through the Codex?" />
                    </div>

                    {/* Auras */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-black/20 p-4 rounded-xl border border-white/5">
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Primary Aura</label>
                            <div className="grid grid-cols-6 gap-1.5 p-2 bg-slate-950/50 border border-indigo-500/20 rounded-lg">
                                {SEEKER_AURA_OPTIONS.map(option => (
                                    <button key={option.id} onClick={() => setAura(option.id)} className={`w-full aspect-square rounded-full border-2 transition-all ${aura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50 hover:opacity-100'}`} style={{ backgroundColor: option.hex }} title={option.name} />
                                ))}
                            </div>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-purple-400 font-bold uppercase tracking-widest">Secondary Sync</label>
                            <div className="grid grid-cols-6 gap-1.5 p-2 bg-slate-950/50 border border-purple-500/20 rounded-lg">
                                {SEEKER_AURA_OPTIONS.slice().reverse().map(option => (
                                    <button key={option.id + '_sec'} onClick={() => setSecondaryAura(option.id)} className={`w-full aspect-square rounded-full border-2 transition-all ${secondaryAura === option.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-50 hover:opacity-100'}`} style={{ backgroundColor: option.hex }} title={option.name} />
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Right Side: Readout & Action */}
                <div className="lg:col-span-4 flex flex-col space-y-4">
                    <h4 className="text-xs font-mono text-slate-500 uppercase tracking-widest border-b border-white/10 pb-2">Codex Readout</h4>

                    <div className="space-y-3 flex-grow">
                        <AnimatePresence mode="wait">
                            <motion.div key={`race-${race}`} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="p-4 rounded-xl bg-indigo-950/20 border border-indigo-500/30">
                                <div className="flex items-center gap-2 mb-1 text-indigo-300">
                                    <i className="ri-dna-line text-xl"></i>
                                    <span className="font-cinzel font-bold text-sm uppercase">Biomorph</span>
                                </div>
                                <p className="text-xs text-slate-400 font-cormorant leading-snug italic line-clamp-3">{activeRaceInfo?.description}</p>
                            </motion.div>
                        </AnimatePresence>

                        <AnimatePresence mode="wait">
                            <motion.div key={`class-${seekerClass}`} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="p-4 rounded-xl bg-purple-950/20 border border-purple-500/30">
                                <div className="flex items-center gap-2 mb-1 text-purple-300">
                                    <i className="ri-sparkling-2-line text-xl"></i>
                                    <span className="font-cinzel font-bold text-sm uppercase">Archetype</span>
                                </div>
                                <p className="text-xs text-slate-400 font-cormorant leading-snug italic line-clamp-3">{activeClassInfo?.description}</p>
                            </motion.div>
                        </AnimatePresence>

                        <div className="grid grid-cols-1 gap-3">
                            <div className="p-3 rounded-lg bg-rose-950/10 border border-rose-500/20 flex gap-3">
                                <div className="p-1.5 rounded bg-rose-950/40 text-rose-300"><i className={activeWeapon?.icon || 'ri-sword-line'}></i></div>
                                <div><div className="text-[10px] font-bold font-cinzel text-rose-200">{activeWeapon?.name}</div><p className="text-[8px] text-slate-500 line-clamp-1">{activeWeapon?.description}</p></div>
                            </div>
                            <div className="p-3 rounded-lg bg-emerald-950/10 border border-emerald-500/20 flex gap-3">
                                <div className="p-1.5 rounded bg-emerald-950/40 text-emerald-300"><i className={activeOutfit?.icon || 'ri-shield-user-line'}></i></div>
                                <div><div className="text-[10px] font-bold font-cinzel text-emerald-200">{activeOutfit?.name}</div><p className="text-[8px] text-slate-500 line-clamp-1">{activeOutfit?.description}</p></div>
                            </div>
                        </div>
                    </div>

                    <div className="p-3 rounded-lg bg-black/40 border border-slate-800 text-[9px] font-mono text-slate-500 uppercase tracking-widest text-center">
                        <i className="ri-shield-check-line mr-2 text-emerald-500"></i>
                        Ready for Insertion
                    </div>

                    <Button onClick={weaveIdentity} className="w-full py-6 bg-emerald-600 font-cinzel font-bold text-xl tracking-[0.4em] shadow-xl shadow-emerald-500/20 hover:bg-emerald-500 transition-all rounded-sm">
                        WEAVE SHARD
                    </Button>
                </div>
            </div>
          </motion.div>
        )}

        {step === 'weaving' && (
          <motion.div key="weaving" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-8 text-indigo-300">
            <div className="relative w-48 h-48">
                <div className="absolute inset-0 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                <span className="absolute inset-0 flex items-center justify-center text-2xl font-mono animate-pulse">WEAVING</span>
            </div>
            <p className="font-mono text-[10px] uppercase tracking-widest text-slate-500">Syncing with Gemini Dreaming...</p>
          </motion.div>
        )}

        {step === 'reveal' && generatedProfile && (
          <motion.div key="reveal" initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} className="flex flex-col items-center gap-8">
             <div className="w-[320px] md:w-[400px]">
                <div className="relative rounded-xl border-[8px] border-amber-500 bg-slate-950 flex flex-col overflow-hidden shadow-[0_0_50px_rgba(245,158,11,0.3)]" style={{ aspectRatio: '2.5/3.5' }}>
                    <div className="bg-black/60 p-4 border-b border-white/10 z-10 flex justify-between items-center">
                        <div className="flex flex-col">
                            <span className="font-cinzel font-bold text-white text-xl tracking-wider">{generatedProfile.name}</span>
                            <span className="text-[8px] font-mono text-amber-500 uppercase">{generatedProfile.gender} // Cycle {generatedProfile.age} // {generatedProfile.bodyType?.split(' ')[0]}</span>
                        </div>
                        <div className="text-[10px] font-mono text-amber-500 px-2 py-0.5 rounded border border-amber-500/30">SHARD 01</div>
                    </div>
                    <div className="absolute inset-0 z-0">{generatedProfile.avatarImageUrl && <img src={generatedProfile.avatarImageUrl} className="w-full h-full object-cover" />}</div>
                    <div className="flex-1 z-10"></div>
                    <div className="bg-slate-950/90 p-5 text-slate-100 font-cormorant italic z-10 border-t border-white/10 text-lg leading-relaxed shadow-[0_-10px_30px_rgba(0,0,0,0.8)]">
                        {generatedProfile.bio}
                    </div>
                </div>
             </div>
             <Button onClick={() => onComplete(generatedProfile)} className="px-16 py-5 bg-emerald-600 text-2xl font-cinzel font-bold tracking-widest shadow-lg shadow-emerald-500/20">ENTER CODEX</Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

