      setIsCompilingStory(true);
      setCompilationProgress(0);
      try {
          if (!cinemaEngineRef.current) cinemaEngineRef.current = new QuestCinemaEngine();
          const slides = gameState.sceneHistory.map(s => ({ imageUrl: s.imageUrl, text: s.description }));
          const blob = await cinemaEngineRef.current.compileVideo(slides, setCompilationProgress, generateSpeech);
          if (blob) {
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a'); a.href = url; a.download = `Quest_${Date.now()}.webm`; a.click();
