  // Helper: Improved wrap text for canvas
  const wrapText = (ctx: CanvasRenderingContext2D, text: string, maxWidth: number) => {
    const words = text.split(' ');
    const lines = [];
    let currentLine = words[0];

    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
  };

  const handleExportComic = async () => {
    if (isExportingComic || !gameState.sceneHistory?.length) return;
    setIsExportingComic(true);
    addEchoMessage(AgentName.RPGNexusAgent, "Synthesizing Chronicle Strip...", "text-amber-300");

    try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const panelWidth = 1600;
        const panelHeight = 900;
        const margin = 60;
        const totalScenes = gameState.sceneHistory.length;

        // Capture Player Card if available
        let playerCardImg: HTMLCanvasElement | null = null;
        const playerCardEl = document.getElementById('seeker-tcg-card') || document.getElementById('dashboard-seeker-card');
        if (playerCardEl) {
            playerCardImg = await html2canvas(playerCardEl as HTMLElement, { scale: 1.5, backgroundColor: null });
        }

        // Calculate total canvas height: (Header) + (Card if any) + (Scenes)
        let totalHeight = margin * 2;
        const headerHeight = 200;
        totalHeight += headerHeight;

        const cardHeight = playerCardImg ? 600 : 0;
        if (playerCardImg) totalHeight += cardHeight + margin;

        totalHeight += (panelHeight + margin) * totalScenes;

        canvas.width = panelWidth + margin * 2;
        canvas.height = totalHeight;

        // Background
        ctx.fillStyle = '#020617'; // slate-950
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        let currentY = margin;

        // 1. Draw Title Header
        ctx.fillStyle = '#6366f1'; // indigo-500
        ctx.font = 'bold 80px Cinzel, serif';
        ctx.textAlign = 'center';
        ctx.fillText("TRI-SOPHIAN CHRONICLES", canvas.width / 2, currentY + 80);

        ctx.font = '30px Cinzel, serif';
        ctx.fillStyle = '#94a3b8'; // slate-400
        ctx.fillText(`Materialized from the Aether • Entropy: ${currentEntropy.toFixed(3)}δ`, canvas.width / 2, currentY + 130);
        currentY += headerHeight;

        // 2. Draw Player Card
        if (playerCardImg) {
            const displayWidth = 430;
            const displayHeight = 600;
            ctx.drawImage(playerCardImg, (canvas.width - displayWidth) / 2, currentY, displayWidth, displayHeight);

            // Border for card
            ctx.strokeStyle = '#f59e0b'; // amber-500
            ctx.lineWidth = 4;
            ctx.strokeRect((canvas.width - displayWidth) / 2, currentY, displayWidth, displayHeight);
            currentY += cardHeight + margin;
        }

        // 3. Draw Scenes
        for (let i = 0; i < totalScenes; i++) {
            const scene = gameState.sceneHistory[i];
            const img = new Image();
            img.crossOrigin = "anonymous";
            img.src = scene.imageUrl;

            await new Promise((resolve) => {
                img.onload = () => {
                    // Image
                    const drawWidth = panelWidth;
                    const drawHeight = panelHeight;
                    const x = margin;
                    const y = currentY;

                    // Shadow for panel
                    ctx.shadowColor = 'black';
                    ctx.shadowBlur = 40;
                    ctx.drawImage(img, x, y, drawWidth, drawHeight);
                    ctx.shadowBlur = 0;

                    // Text Overlay Box
                    const boxHeight = 220;
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
                    ctx.fillRect(x, y + drawHeight - boxHeight, drawWidth, boxHeight);

                    // Border
                    ctx.strokeStyle = '#334155';
                    ctx.lineWidth = 15;
                    ctx.strokeRect(x, y, drawWidth, drawHeight);

                    // Location Tag
                    ctx.fillStyle = '#6366f1';
                    ctx.font = 'bold 24px mono';
                    ctx.textAlign = 'left';
                    ctx.fillText(`LOCATION: ${scene.location.toUpperCase()}`, x + 40, y + drawHeight - boxHeight + 45);

                    // Wrap & Draw Narrative Text
                    ctx.font = 'italic 34px Cormorant, serif';
                    ctx.fillStyle = '#f8fafc';
                    ctx.textAlign = 'left';
                    const lines = wrapText(ctx, scene.description, drawWidth - 80);
                    lines.forEach((line, lineIdx) => {
                        if (lineIdx < 3) {
                            ctx.fillText(line, x + 40, y + drawHeight - boxHeight + 100 + (lineIdx * 45));
                        }
                    });

                    currentY += panelHeight + margin;
                    resolve(true);
                };
                img.onerror = () => resolve(false);
            });
        }

        const link = document.createElement('a');
        link.download = `Codex_Adventure_${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png', 0.9);
        link.click();
        addEchoMessage(AgentName.RPGNexusAgent, "Adventure Chronicle Exported.", "text-emerald-400");
    } catch (e) {
        console.error("Comic Export Error", e);
    } finally {
        setIsExportingComic(false);
    }
  };

  const handleExportPDF = async () => {
