            orientation: 'landscape',
            unit: 'px',
            format: [1280, 720]
        });

        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();

        // 1. Title Page
        doc.setFillColor(15, 23, 42);
        doc.rect(0, 0, pageWidth, pageHeight, 'F');

        doc.setTextColor(99, 102, 241);
        doc.setFont('times', 'bold');
        doc.setFontSize(60);
        doc.text("TRI-SOPHIAN CHRONICLES", pageWidth / 2, pageHeight / 2 - 40, { align: 'center' });

        doc.setTextColor(148, 163, 184);
        doc.setFontSize(24);
        doc.text(`Fragmented Records of Seeker ${activeProfile?.name || 'Unknown'}`, pageWidth / 2, pageHeight / 2 + 10, { align: 'center' });

        // 2. Player Card Page
        const playerCardEl = document.getElementById('seeker-tcg-card') || document.getElementById('dashboard-seeker-card');
        if (playerCardEl) {
            const cardCanvas = await html2canvas(playerCardEl as HTMLElement, { scale: 2 });
            doc.addPage();
            doc.setFillColor(15, 23, 42);
            doc.rect(0, 0, pageWidth, pageHeight, 'F');

            const cardW = 350;
            const cardH = 490;
            doc.addImage(cardCanvas.toDataURL('image/jpeg', 0.8), 'JPEG', (pageWidth - cardW) / 2, (pageHeight - cardH) / 2, cardW, cardH);

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(18);
            doc.text("IDENTIFICATION SHARD", pageWidth / 2, 60, { align: 'center' });
        }

        // 3. Adventure Pages
        for (let i = 0; i < gameState.sceneHistory.length; i++) {
            const scene = gameState.sceneHistory[i];
            const base64 = await urlToBase64(scene.imageUrl);

            doc.addPage();
            doc.setFillColor(15, 23, 42);
            doc.rect(0, 0, pageWidth, pageHeight, 'F');

            // Background Image (centered/coverish)
            doc.addImage(base64, 'JPEG', 0, 0, pageWidth, pageHeight);

            // Text Box
            doc.setFillColor(0, 0, 0);
            doc.setGState(new (doc as any).GState({ opacity: 0.8 }));
            doc.rect(50, pageHeight - 180, pageWidth - 100, 150, 'F');
            doc.setGState(new (doc as any).GState({ opacity: 1.0 }));

            doc.setTextColor(99, 102, 241);
            doc.setFontSize(20);
            doc.text(`CHAPTER ${i + 1}: ${scene.location.toUpperCase()}`, 80, pageHeight - 145);

            doc.setTextColor(255, 255, 255);
            doc.setFontSize(16);
            doc.setFont('times', 'italic');
            const lines = doc.splitTextToSize(scene.description, pageWidth - 160);
            doc.text(lines, 80, pageHeight - 115);
        }

        doc.save(`TriSophian_Adventure_${Date.now()}.pdf`);
        addEchoMessage(AgentName.RPGNexusAgent, "Chronicle PDF Inscribed.", "text-emerald-400");
    } catch (e) {
        console.error("PDF Export Error", e);
    } finally {
        setIsExportingPDF(false);
