                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-y-auto custom-scrollbar pr-4 pb-12">
                    {(Object.entries(scanResults) as [string, RPGScanResultLocation][]).map(([name, data]) => (
                        <button 
                            key={name}
                            onClick={() => { handleTravel(name, data); setInitStep(0); }}
                            className="flex flex-col p-10 bg-slate-900/10 border-2 border-white/5 rounded-[3rem] hover:bg-indigo-900/20 hover:border-cyan-500/50 hover:shadow-[0_0_60px_rgba(34,211,238,0.15)] transition-all text-left transform hover:-translate-y-3 group relative overflow-hidden backdrop-blur-md"
                        >
                            <div className="flex items-center justify-between mb-8">
                                <div className={`w-20 h-20 rounded-[2rem] bg-black/20 border border-white/10 flex items-center justify-center text-5xl ${data.color}`}>
                                    <i className={data.icon || 'ri-map-pin-2-line'}></i>
                                </div>
                                <div className="flex flex-col items-end">
                                    <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest mb-1">Threat Assessment</span>
                                    <span className={`text-xs uppercase font-bold tracking-widest px-4 py-1.5 rounded-full border ${data.risk === 'Extreme' ? 'bg-rose-950/20 text-rose-400 border-rose-500/40' : data.risk === 'High' ? 'bg-orange-950/20 text-orange-400 border-orange-500/40' : 'bg-emerald-950/20 text-emerald-400 border-emerald-500/40'}`}>{data.risk}</span>
                                </div>
                            </div>
                            <h4 className="font-cinzel font-bold text-3xl text-white mb-4 group-hover:text-cyan-300 transition-colors tracking-tight">{name}</h4>
                            <p className="text-lg text-slate-400 font-cormorant leading-relaxed line-clamp-3 italic mb-8">{data.description}</p>

                            <div className="mt-auto flex items-center gap-3 text-cyan-400 font-mono text-[10px] uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                                <i className="ri-arrow-right-line"></i> Initiate Vector Travel
                            </div>

                            <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/[0.02] rounded-full blur-3xl group-hover:bg-cyan-400/5 transition-colors" />
                        </button>
                    ))}
                </div>
            </motion.div>
        )}
      </AnimatePresence>
    </div>
  );

  const containerClasses = isFullscreen 
    ? "fixed inset-0 z-[9999] bg-slate-950" 
    : "relative w-full overflow-hidden bg-slate-950 rounded-2xl shadow-2xl border border-white/5";

  return (
    <div className={containerClasses} style={{ width: isFullscreen ? '100vw' : width || '100%', height: isFullscreen ? '100vh' : height || '100%' }}>
        {initStep > 0 ? renderInitialization() : (
            <div className="h-full w-full relative flex flex-col overflow-hidden">
                {/* BACKGROUND LAYER */}
                <div className="absolute inset-0 z-0">
                    <AnimatePresence mode="wait">
                        <motion.div key={gameState.currentSceneImageUrl} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1.5 }} className="w-full h-full">
                            {currentSceneVideoUrl ? (
                                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover" />
                            ) : gameState.currentSceneImageUrl ? (
                                <img src={gameState.currentSceneImageUrl} className="w-full h-full object-cover" />
                            ) : (
                                <div className="w-full h-full bg-slate-900 animate-pulse" />
                            )}
                        </motion.div>
                    </AnimatePresence>
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-slate-950/80" />
                    <div className="absolute inset-0 bg-black/10" />
                </div>

                {/* MAP OVERLAY LAYER */}
                {viewMode === 'map' && (
                    <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-xl animate-fade-in">
                         <div className="absolute top-6 left-6 z-10">
                            <button onClick={() => setViewMode('scene')} className="p-4 rounded-full bg-slate-800/10 border border-white/20 text-white hover:bg-slate-700 shadow-2xl">
                                <i className="ri-close-line text-2xl"></i>
                            </button>
                         </div>
                         <LoreMapVisualizer 
                             currentLocationId={gameState.currentLocation} 
                             onTravel={(n) => { handleTravel(n.id, {description: n.description}); setViewMode('scene'); }} 
                             width={window.innerWidth} 
                             height={window.innerHeight} 
                         />
                    </div>
                )}

                {/* IMMERSIVE HUD LAYER */}
                <div className="relative z-10 flex flex-col h-full pointer-events-none p-6 md:p-10">

                    {/* Top HUD */}
                    <div className="flex flex-col md:flex-row justify-between items-start pointer-events-auto shrink-0 mb-8 gap-4">
                        <div className="bg-slate-900/10 backdrop-blur-xl border border-white/10 p-6 rounded-3xl shadow-2xl max-w-lg transition-transform hover:scale-105 duration-500">
                            <div className="flex items-center gap-4 mb-3">
                                <div className="w-12 h-12 rounded-2xl bg-indigo-600/10 border border-indigo-400/30 flex items-center justify-center text-2xl text-indigo-300">
                                    <i className="ri-map-pin-user-line"></i>
                                </div>
                                <div>
                                    <h3 className="text-2xl font-cinzel font-bold text-white tracking-widest">{gameState.currentLocation}</h3>
                                    <p className="text-[10px] font-mono text-cyan-400 uppercase tracking-[0.3em]">Sector Registered // Secure Link</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-6 mt-4">
                                <div className="flex-1">
                                    <div className="flex justify-between text-[10px] font-mono text-slate-400 uppercase mb-1"><span>Integrity</span><span>{gameState.vitals.integrity}%</span></div>
                                    <div className="h-1.5 bg-slate-800/10 rounded-full overflow-hidden"><motion.div animate={{ width: `${gameState.vitals.integrity}%` }} className="h-full bg-rose-500" /></div>
                                </div>
                                <div className="flex-1">
                                    <div className="flex justify-between text-[10px] font-mono text-slate-400 uppercase mb-1"><span>Sanity</span><span>{gameState.vitals.sanity}%</span></div>
                                    <div className="h-1.5 bg-slate-800/10 rounded-full overflow-hidden"><motion.div animate={{ width: `${gameState.vitals.sanity}%` }} className="h-full bg-purple-500" /></div>
                                </div>
                            </div>
                        </div>

                        <div className="flex flex-col gap-3">
                            <div className="flex gap-2 p-2 bg-black/10 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl">
                                <button onClick={() => setViewMode('map')} className="p-4 rounded-xl bg-slate-800/10 hover:bg-indigo-600 text-white transition-all" title="View Map"><i className="ri-map-2-line text-xl"></i></button>
                                <button onClick={() => setIsFullscreen(!isFullscreen)} className="p-4 rounded-xl bg-slate-800/10 hover:bg-slate-700 text-white transition-all" title="Fullscreen Toggle"><i className={`ri-${isFullscreen ? 'fullscreen-exit' : 'fullscreen'}-line text-xl`}></i></button>
                                <button onClick={handleEndQuest} className="p-4 rounded-xl bg-rose-900/10 hover:bg-rose-600 text-white transition-all" title="Reset Quest"><i className="ri-stop-circle-line text-xl"></i></button>
                            </div>

                            <div className="flex flex-wrap gap-2 justify-end bg-slate-900/10 backdrop-blur-xl p-3 rounded-2xl border border-white/5">
                                <span className="text-[10px] font-mono text-amber-500 uppercase tracking-widest w-full text-right mb-1">Dramatics</span>
                                <button onClick={handleExportComic} disabled={isExportingComic} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800/10 border border-amber-500/30 text-amber-100 hover:bg-amber-600 transition-all text-[10px] font-bold uppercase tracking-widest" title="Export Journey as Comic Strip">
                                    <i className="ri-book-open-line text-lg"></i> COMIC
                                </button>
                                <button onClick={handleExportPDF} disabled={isExportingPDF} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800/10 border border-sky-500/30 text-sky-100 hover:bg-sky-600 transition-all text-[10px] font-bold uppercase tracking-widest" title="Export Journey as PDF Book">
                                    <i className="ri-file-pdf-line text-lg"></i> PDF
                                </button>
                                <button onClick={handleCompileStoryVideo} disabled={isCompilingStory} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800/10 border border-emerald-500/30 text-emerald-100 hover:bg-emerald-600 transition-all text-[10px] font-bold uppercase tracking-widest" title="Compile Journey as Movie">
                                    <i className="ri-movie-line text-lg"></i> MOVIE
                                </button>
                                <button onClick={handleGenerateSceneVideo} disabled={isAnimatingScene} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800/10 border border-fuchsia-500/30 text-fuchsia-100 hover:bg-fuchsia-600 transition-all text-[10px] font-bold uppercase tracking-widest" title="Animate Current Scene">
                                    <i className="ri-clapperboard-line text-lg"></i> ANIMATE
                                </button>
                                <button onClick={() => setIsNarratorEnabled(!isNarratorEnabled)} className={`p-2 rounded-xl border transition-all ${isNarratorEnabled ? 'bg-emerald-600 border-emerald-400' : 'bg-slate-900/10 border-white/10'}`} title="Toggle Oracle Narration">
                                    <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line text-lg`}></i>
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className="flex-grow min-h-0" />

                    {/* Bottom Console */}
                    <div className="flex flex-col lg:flex-row gap-8 items-end pointer-events-auto max-h-[45%]">

                        <div className="lg:w-1/2 w-full flex flex-col min-h-0 overflow-hidden">
                             <div ref={logContainerRef} className="bg-slate-950/10 backdrop-blur-2xl border border-white/5 rounded-[2.5rem] p-8 overflow-y-auto custom-scrollbar shadow-2xl flex flex-col gap-6">
                                {gameState.narrativeHistory.map((entry, i) => (
                                    <motion.div key={i} initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className={`text-lg leading-relaxed drop-shadow-md ${entry.type === 'action' ? 'text-indigo-400 font-bold font-cinzel' : 'text-slate-100 font-cormorant italic'}`}>
                                        {entry.type === 'action' ? `> ${entry.text.toUpperCase()}` : entry.text}
                                    </motion.div>
                                ))}
                                {isProcessingTurn && (
                                    <div className="flex items-center gap-3 text-indigo-400 animate-pulse font-mono text-xs uppercase tracking-widest">
                                        <i className="ri-quill-pen-line text-xl"></i> Materializing fate...
                                    </div>
                                )}
                             </div>
                        </div>

                        <div className="lg:w-1/2 w-full flex flex-col gap-4">
                            <div className="flex flex-wrap gap-3">
                                {gameState.availableActions.map((act, i) => {
                                     let riskColor = "bg-emerald-600/10 hover:bg-emerald-500/25 border-emerald-400/30";
                                     if(act.risk > 0.6) riskColor = "bg-rose-700/10 hover:bg-rose-600/25 border-rose-500/30";
                                     else if(act.risk > 0.3) riskColor = "bg-amber-600/10 hover:bg-amber-500/25 border-amber-400/30";

                                     return (
                                        <button 
                                            key={i} 
                                            onClick={() => handleAction(act.label, act.risk)}
                                            className={`flex-grow px-8 py-4 rounded-2xl border-b-4 font-cinzel font-bold text-white shadow-xl transition-all hover:-translate-y-1 active:translate-y-0.5 backdrop-blur-md ${riskColor}`}
                                        >
                                            <div className="flex justify-between items-center gap-4">
                                                <span className="tracking-widest uppercase text-sm">{act.label || 'empty'}</span>
                                                <span className="text-[10px] font-mono opacity-60 bg-black/10 px-2 py-0.5 rounded-full">{typeof act.risk === 'number' ? Math.round(act.risk*100) : 0}% RISK</span>
                                            </div>
                                        </button>
                                     );
                                })}
                            </div>

                            <div className="flex gap-4 p-4 bg-slate-900/10 backdrop-blur-2xl border border-white/10 rounded-[2rem] shadow-2xl group focus-within:border-indigo-500/50 transition-colors">
                                <input 
                                    type="text" 
                                    value={customActionInput} 
                                    onChange={e => setCustomActionInput(e.target.value)} 
                                    onKeyDown={e => e.key === 'Enter' && handleAction(customActionInput)} 
                                    placeholder="Enter your next move..." 
                                    className="flex-grow bg-transparent text-xl text-white outline-none placeholder:text-slate-500 font-cormorant" 
                                />
                                <button onClick={() => handleAction(customActionInput)} className="w-14 h-14 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white flex items-center justify-center transition-transform hover:scale-110">
                                    <i className="ri-send-plane-fill text-2xl"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {foundLoot && (
                    <div className="absolute inset-0 z-[100] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-10 animate-fade-in">
                        <motion.div initial={{ scale: 0.8, rotate: -5 }} animate={{ scale: 1, rotate: 0 }} className="bg-slate-900/10 border-4 border-emerald-500/50 rounded-[3rem] p-12 text-center max-w-xl shadow-[0_0_100px_rgba(52,211,153,0.4)] backdrop-blur-xl">
                            <h3 className="text-4xl font-cinzel font-bold text-emerald-400 mb-6 tracking-widest">RELIC MATERIALIZED</h3>
                            <div className="text-9xl mb-8 text-emerald-200 animate-bounce"><i className={foundLoot.icon}></i></div>
                            <h4 className="text-2xl font-bold text-white mb-2">{foundLoot.name}</h4>
                            <p className="text-lg text-slate-400 font-cormorant italic mb-10">{foundLoot.description}</p>
                            <Button onClick={() => { if(activeProfile) onUpdateProfile({...activeProfile, inventory: [...activeProfile.inventory, foundLoot!]}); setFoundLoot(null); }} className="w-full py-6 text-2xl font-cinzel font-bold bg-emerald-600 hover:bg-emerald-500 shadow-2xl">
                                CLAIM ARTIFACT
                            </Button>
                        </motion.div>
                    </div>
                )}
            </div>
        )}
    </div>
  );
};

export default RPGNexusPanel;

import React, { useState, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '../ui/Button';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { SeekerProfile, SeekerAvatarType, SeekerClass, SeekerGender, SeekerBodyType, SeekerEnergyAlignment, SeekerAuraColor, SeekerVisualFilter, AgentName } from '../../types';
import { AVATAR_RACES, SEEKER_CLASSES, ALL_GENDERS_LIST, SEEKER_AURA_OPTIONS, ALL_ALIGNMENTS_LIST, STARTER_WEAPONS, STARTER_OUTFITS, SEEKER_BODY_TYPES, EYE_COLORS, HAIR_COLORS, SKIN_TONES } from '../../constants';
import { globalSoundEngine } from '../../lib/SoundEngine';

const NAME_PREFIXES = ["Xyl", "Chron", "Vor", "Zyn", "Kael", "Thal", "Om", "Lyra", "Vex", "Ser", "Dra", "Myr", "Pyr", "Cyp", "Nek", "Sol", "Zen", "Rin", "Kys", "Tor", "Ael", "Fen", "Grim"];
const NAME_SUFFIXES = ["os", "ia", "ex", "on", "is", "us", "ar", "or", "a", "yn", "ix", "um", "ra", "th", "en", "ir", "ae", "io", "ak", "ul"];

const RANDOM_INTENTS = [
    "To recover the lost resonance of my ancestors.",
    "To find the gap in the code where silence is born.",
    "To burn brighter than the dying stars of Herculis.",
    "To weave a new thread into the unraveling Aethel.",
    "To dismantle the Prime Axioms and see what lies beneath.",
    "To hunt the anomaly that swallowed my home sector.",
    "To find the source of the golden frequency.",
    "To escape the recursive loops of my own memory.",
    "To become a living glyph in the heart of the Codex."
];

const generateRandomName = () => {
    const prefix = NAME_PREFIXES[Math.floor(Math.random() * NAME_PREFIXES.length)];
    const suffix = NAME_SUFFIXES[Math.floor(Math.random() * NAME_SUFFIXES.length)];
    return prefix + suffix;
};

interface OnboardingFunnelProps {
  onComplete: (profile: SeekerProfile) => void;
  addEchoMessage: (s: string, t: string, c: string) => void;
  onImportRequested?: (file: File) => Promise<void>; // Added for import feature
}

export const OnboardingFunnel: React.FC<OnboardingFunnelProps> = ({ onComplete, addEchoMessage, onImportRequested }) => {
  const [step, setStep] = useState<'briefing' | 'calibration' | 'weaving' | 'reveal'>('briefing');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [name, setName] = useState("");
  const [race, setRace] = useState<SeekerAvatarType>(SeekerAvatarType.Human);
  const [seekerClass, setSeekerClass] = useState<SeekerClass>(SeekerClass.Gatewalker);
  const [gender, setGender] = useState<SeekerGender>(SeekerGender.NonBinary);
  const [age, setAge] = useState(25);
  const [bodyType, setBodyType] = useState<SeekerBodyType>(SeekerBodyType.Mesomorphic);
  const [alignment, setAlignment] = useState<SeekerEnergyAlignment>(SeekerEnergyAlignment.Balanced);
  const [weaponId, setWeaponId] = useState(STARTER_WEAPONS[0].id);
  const [outfitId, setOutfitId] = useState(STARTER_OUTFITS[0].id);
  const [aura, setAura] = useState<SeekerAuraColor>(SeekerAuraColor.Azure);
  const [secondaryAura, setSecondaryAura] = useState<SeekerAuraColor>(SeekerAuraColor.Violet);
  const [intent, setIntent] = useState("");

  const [eyeColor, setEyeColor] = useState(EYE_COLORS[0]);
  const [hairColor, setHairColor] = useState(HAIR_COLORS[0]);
  const [skinTone, setSkinTone] = useState(SKIN_TONES[0]);

  const [generatedProfile, setGeneratedProfile] = useState<SeekerProfile | null>(null);
  const { invokeGemini, generateImage } = useGemini();

  const activeRaceInfo = useMemo(() => AVATAR_RACES.find(r => r.id === race), [race]);
  const activeClassInfo = useMemo(() => SEEKER_CLASSES.find(c => c.id === seekerClass), [seekerClass]);
  const activeWeapon = useMemo(() => STARTER_WEAPONS.find(w => w.id === weaponId), [weaponId]);
  const activeOutfit = useMemo(() => STARTER_OUTFITS.find(o => o.id === outfitId), [outfitId]);

  const handleRandomize = () => {
    globalSoundEngine.playUIFeedback('click');
    setName(generateRandomName());
    setRace(AVATAR_RACES[Math.floor(Math.random() * AVATAR_RACES.length)].id as SeekerAvatarType);
    setSeekerClass(SEEKER_CLASSES[Math.floor(Math.random() * SEEKER_CLASSES.length)].id as SeekerClass);
    setGender(ALL_GENDERS_LIST[Math.floor(Math.random() * ALL_GENDERS_LIST.length)]);
    setAge(Math.floor(Math.random() * 900) + 1);
    setBodyType(SEEKER_BODY_TYPES[Math.floor(Math.random() * SEEKER_BODY_TYPES.length)]);
    setAlignment(ALL_ALIGNMENTS_LIST[Math.floor(Math.random() * ALL_ALIGNMENTS_LIST.length)]);
    setWeaponId(STARTER_WEAPONS[Math.floor(Math.random() * STARTER_WEAPONS.length)].id);
    setOutfitId(STARTER_OUTFITS[Math.floor(Math.random() * STARTER_OUTFITS.length)].id);
    setAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setSecondaryAura(SEEKER_AURA_OPTIONS[Math.floor(Math.random() * SEEKER_AURA_OPTIONS.length)].id as SeekerAuraColor);
    setEyeColor(EYE_COLORS[Math.floor(Math.random() * EYE_COLORS.length)]);
    setHairColor(HAIR_COLORS[Math.floor(Math.random() * HAIR_COLORS.length)]);
    setSkinTone(SKIN_TONES[Math.floor(Math.random() * SKIN_TONES.length)]);
    setIntent(RANDOM_INTENTS[Math.floor(Math.random() * RANDOM_INTENTS.length)]);
    addEchoMessage(AgentName.System, "Randomized Identity Resonance.", "text-cyan-400");
  };

  const handleFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && onImportRequested) {
        await onImportRequested(e.target.files[0]);
    }
  };

  const weaveIdentity = async () => {
    if (!name.trim()) {
        alert("A Seeker must have a name to be woven into the thread.");
        return;
    }
    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    addEchoMessage(AgentName.SeekerProfileWeaverAgent, `Anchoring identity: ${name}...`, "text-indigo-400");

    try {
        const prompt = `Synthesize a unique RPG Seeker identity bio for the Tri-Sophian Codex based on these choices:
        Name: ${name} | Race: ${race} | Class: ${seekerClass} | Gender: ${gender} | Age: ${age} cycles | Build: ${bodyType} | Alignment: ${alignment}
        Eyes: ${eyeColor} | Hair: ${hairColor} | Skin: ${skinTone}
        Weapon: ${activeWeapon?.name} (${activeWeapon?.description})
        Armor: ${activeOutfit?.name} (${activeOutfit?.description})
        Aura: ${aura}/${secondaryAura} | Intent: "${intent || 'Unknown'}"
        Provide strictly valid JSON with key "bio": string (2-sentence backstory).`;

        const response = await invokeGemini(prompt, "You are an identity synthesizer. Output JSON only.", "application/json");
        const data = JSON.parse(response || '{"bio": "A Seeker emerging from the Aetheric mists."}');

        const imagePrompt = `High-detail cinematic full-body RPG character portrait of a ${age} cycle old ${gender} ${race} ${seekerClass}. 
        PHYSICAL TRAITS: ${bodyType} build, ${skinTone} skin tone, ${hairColor} hair, and piercing ${eyeColor} eyes.
        EQUIPMENT: Wearing ${activeOutfit?.name} (${activeOutfit?.visualPromptMod}) and wielding ${activeWeapon?.name} (${activeWeapon?.visualPromptMod}).
        VISUAL STYLE: Cosmic sci-fi fantasy, bioluminescent ${aura.toLowerCase()} and ${secondaryAura.toLowerCase()} auras intermingling. 
        Intention: ${intent}. Dark cinematic lighting. No text in image.`;

        const avatarUrl = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const profile: SeekerProfile = {
            generatedAt: Date.now(),
            level: 1, experience: 0, flux: 100, 
            inventory: [activeWeapon!, activeOutfit!],
            selfTraits: ["Calibrated"], codexTraits: ["Seeker"],
            name, race, class: seekerClass, gender, age, bodyType,
            eyeColor, hairColor, skinTone,
            energyAlignment: alignment,
            auraColor: aura, auraSecondaryColor: secondaryAura,
            visualFilter: SeekerVisualFilter.Standard,
            avatarImageUrl: avatarUrl || "",
            bio: data.bio,
            equippedWeapon: activeWeapon,
            equippedOutfit: activeOutfit
        };
        setGeneratedProfile(profile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) { setStep('reveal'); }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950 flex items-center justify-center p-6 overflow-hidden">
      <AnimatePresence mode="wait">
        {step === 'briefing' && (
          <motion.div key="briefing" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }} className="max-w-2xl text-center space-y-8">
            <h2 className="text-4xl font-cinzel font-bold text-indigo-300 tracking-widest drop-shadow-glow">IDENTITY INITIALIZATION</h2>
            <p className="text-slate-300 font-cormorant text-xl">The Tri-Sophian Codex responds to the soul-signal of those who enter. Project your **Identity** to begin.</p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
                <Button onClick={() => setStep('calibration')} className="px-12 py-4 bg-indigo-600 font-bold text-lg tracking-widest rounded-sm shadow-xl shadow-indigo-500/20">INITIALIZE CALIBRATION</Button>
                <Button onClick={() => fileInputRef.current?.click()} className="px-12 py-4 bg-slate-800 border border-slate-700 font-bold text-lg tracking-widest rounded-sm hover:bg-slate-700 transition-all">RESTORE REALITY SHARD</Button>
                <input type="file" ref={fileInputRef} onChange={handleFileImport} style={{display: 'none'}} accept=".json" />
            </div>
          </motion.div>
        )}

        {step === 'calibration' && (
