      <button onClick={() => { onToggleSigilOverlay(); closeAllMenus(); }} className={`w-full text-left px-4 py-2 text-sm transition flex items-center ${showSigilOverlay ? 'text-purple-300 bg-purple-700/30' : 'text-slate-300 hover:bg-slate-800'}`}><i className={`mr-2 ${showSigilOverlay ? 'ri-shield-star-fill' : 'ri-shield-star-line'}`}></i>{showSigilOverlay ? 'Deactivate Ceremonial' : 'Activate Ceremonial'}</button>
      <div className="my-1 border-t border-slate-700"></div>
