      {onOpenSaveLoadModal && (
          <button onClick={() => { onOpenSaveLoadModal(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-emerald-300 hover:bg-slate-800 transition flex items-center">
              <i className="ri-save-3-line mr-2"></i>Chronicle Vault (Save/Load)
