    if (hydrated.ritualState) {
        setPlacedGlyphs(hydrated.ritualState.placedGlyphs || []);
        setConnections(hydrated.ritualState.connections || []);
    }
    if (hydrated.artifacts) setArtifacts(hydrated.artifacts);
    if (hydrated.activeProfile) {
        setActiveProfile(hydrated.activeProfile);
        setSeekerTraits(hydrated.activeProfile.selfTraits);
    }
    if (hydrated.rpgState) setRpgState(hydrated.rpgState);
  }

  const effectiveSystemEntropy = Math.max(0, Math.min(1, currentEntropy));

  const dominantAgentTone = useMemo(() => {
      if (echoLog.length > 0) {
          const lastSource = echoLog[0].source;
          if (Object.values(AgentName).includes(lastSource as AgentName)) {
              return lastSource as AgentName;
          }
      }
      return null;
  }, [echoLog]);


  const addEchoMessage = useCallback((source: string, text: string, colorClass: string = 'text-slate-300', isAutoEcho: boolean = false, meta?: any) => {
    const newMessage: EchoMessage = {
      id: `echo-${Date.now()}-${Math.random()}`,
      source,
      text,
      colorClass,
      isAutoEcho,
      meta,
      timestamp: new Date().toISOString()
    };
    setEchoLog(prev => [newMessage, ...prev].slice(0, 100)); 
  }, []);

  const addArtifact = useCallback((artifact: CodexArtifact) => {
    setArtifacts(prev => [artifact, ...prev]);
    addEchoMessage(AgentName.ChronicleReliquaryAgent, `Artifact Acquired: ${artifact.name}`, 'text-amber-300');
  }, [addEchoMessage]);

  const handleUpdateProfile = useCallback((profile: SeekerProfile) => {
    setActiveProfile(profile);
    setSeekerTraits(profile.selfTraits); 
  }, []);

  const handleResetProfile = async () => {
    if(confirm("Sever this identity? All progress will be lost and you will return to the Synthesis Loom.")) {
        // Sync reset of all core identifiers
        setActiveProfile(null);
        setSeekerTraits([]);
        setRpgState(undefined);
        setPlacedGlyphs([]);
        setConnections([]);
        setArtifacts([]);
        setCurrentEntropy(0.1);
        setEchoLog([]);

        // Purge storage
        await deleteSave('autosave');

        // Force back to onboarding
        setStage('ONBOARDING');

        addEchoMessage(AgentName.System, "Identity Shard Severed. Chrono-Loop Reset.", "text-rose-400");
        globalSoundEngine.playSFX('fail');
    }
  }

  const handleSaveRPGState = useCallback((state: RPGGameState) => {
      setRpgState(state);
  }, []);

  const handleSystemMetricsUpdate = useCallback((entropyDelta: number, negentropyDelta: number) => {
    setCurrentEntropy(prev => Math.min(1, Math.max(0, prev + entropyDelta)));
    setNegentropyLevel(prev => Math.min(1, Math.max(0, prev + negentropyDelta)));
  }, []);

  const handleRitualActivated = (success: boolean, details: string, type?: string, alchemyResult?: RitualAlchemyResult) => {
    addEchoMessage(AgentName.RitualEngine, success ? `Ritual Successful: ${details}` : `Ritual Fizzled: ${details}`, success ? 'text-emerald-400' : 'text-rose-400');
    setLastRitualOutcome({ success, details, type, alchemyResult });
    if (success) {
      setCurrentEntropy(prev => Math.max(0, prev - 0.05));
      setNegentropyLevel(prev => Math.min(1, prev + 0.05));
    } else {
      setCurrentEntropy(prev => Math.min(1, prev + 0.02));
      setNegentropyLevel(prev => Math.max(0, prev - 0.02));
    }
  };

  const handleLoadSlot = async (slotId: string) => {
      const hydrated = await loadGame(slotId);
       if (hydrated) {
            applyHydratedState(hydrated);
            setStage('ACTIVE');
            addEchoMessage(AgentName.System, `Timeline restored from ${slotId}.`, 'text-cyan-300');
        }
  };

  const handleImportSave = useCallback(async (file: File) => {
    try {
      const success = await importSave(file);
      if (success) {
        addEchoMessage(AgentName.System, "Reality shard imported successfully.", "text-emerald-300");
        const hydrated = await loadGame('imported_save');
        if (hydrated) {
            applyHydratedState(hydrated);
            setStage('ACTIVE');
            addEchoMessage(AgentName.System, "Reality Shard Integrated. Resuming Timeline.", "text-cyan-400");
        }
      }
    } catch (e) {
      addEchoMessage(AgentName.System, "Import sequence failed. Data integrity compromised.", "text-rose-400");
    }
  }, [importSave, addEchoMessage, loadGame]);

  const onLaunchModule = (moduleId: string) => {
    setActiveModal(moduleId);
  };

  const closeModal = () => {
    setActiveModal(null);
  };

  if (stage === 'BOOT' || isHydrating) {
    return <BootSequence onComplete={() => setStage(activeProfile ? 'ACTIVE' : 'ONBOARDING')} />;
  }

  if (stage === 'ONBOARDING' && !activeProfile) {
      return <OnboardingFunnel onComplete={(profile) => { handleUpdateProfile(profile); setStage('ACTIVE'); }} addEchoMessage={addEchoMessage} onImportRequested={handleImportSave} />;
  }

  return (
    <SystemStateProvider value={{ entropy: effectiveSystemEntropy, activeTraits: seekerTraits, playbackStatus: 'playing', activeGlyph: null, negentropyLevel, isNegentropyStable }}>
      <div className="app-container min-h-screen bg-slate-950 text-slate-200 font-sans flex flex-col overflow-hidden relative">
        <MagicalMouseTrail /> 
        <Header 
          currentEntropy={effectiveSystemEntropy}
          negentropy={negentropyLevel}
          lambda={1.0} 
          onProvokeThornedRose={() => addEchoMessage('System', 'Thorned Rose Provoked', 'text-rose-400')}
          onTuneFrequency={() => addEchoMessage('System', 'Frequency Tuned', 'text-sky-300')}
          onRecallAncestor={() => {}} onBurnPetals={() => {}} onAwakenLotusDream={() => {}} onPulseAstralJasmine={() => {}} onGraftThorns={() => {}}
          onToggleAutoEcho={() => {}} onAmplifyVoices={() => {}} onSeedDream={() => {}} isAutoEchoPaused={false}
          onInvokeGeminiOracle={() => {}} onContextualOracleQuery={() => {}}
          onToggleAshfall={() => {}} showAshfall={false}
          showLogicWebDebug={false} onToggleLogicWebDebug={() => {}}
          isAuditing={false} onToggleAuditMode={() => {}} isAuditModeLocked={false}
          currentCodexModeId={codexModeId} activateCodexMode={setCodexModeId}
          onDumpThreadSummary={() => {}} showSigilOverlay={false} onToggleSigilOverlay={() => {}}
          onTraceThreadcoil={() => {}} onReEnterJunction={() => {}} onExtractSigil={() => {}}
          isBugaModeActive={false} onToggleBugaMode={() => {}}
          isMuted={false} onToggleMute={() => globalSoundEngine.toggleMute(true)}
          onLaunchNexus={() => onLaunchModule('rpg_nexus')}
          onExportSave={exportSave}
          onImportSave={handleImportSave}
          onOpenSaveLoadModal={() => setIsSaveLoadModalOpen(true)} 
          saveStatus={saveStatus} 
          lastSavedTime={lastSavedTime} 
        />

        <main className="flex-grow flex flex-col lg:grid lg:grid-cols-12 gap-4 p-4 overflow-hidden relative z-10">

          <aside className="lg:col-span-3 flex flex-col gap-4 overflow-y-auto custom-scrollbar pr-1">
             <SeekerAuraDisplay 
                seekerTraits={activeProfile?.selfTraits || []}
                currentEntropy={effectiveSystemEntropy}
                dominantAgentTone={dominantAgentTone}
                lastRitualOutcome={lastRitualOutcome}
                width={350}
                height={350}
                activeAuraColor={activeProfile?.auraColor}
                activeSecondaryAuraColor={activeProfile?.auraSecondaryColor}
              />
              <SeekerVitalsPanel 
                activeProfile={activeProfile}
                rpgState={rpgState}
              />
              <CommunityResonancePanel addEchoMessage={addEchoMessage} seekerFaction={activeProfile?.faction} />
              <ProtocolDuelPanel width={350} height={500} activeProfile={activeProfile} onUpdateProfile={handleUpdateProfile} addEchoMessage={addEchoMessage} />
              <BloodInkFloraChamber activeSpeciesName={null} allSpeciesData={{}} />
              <BugaGlyphCodexPanel width={350} height={500} />
              <PeptideSimulationPanel addEchoMessage={addEchoMessage} width={350} height={400} />
          </aside>

          <section className="lg:col-span-6 flex flex-col gap-6 overflow-y-auto custom-scrollbar px-1">

            {activeProfile && (
                <SeekerProfileDashboardPanel 
                    profile={activeProfile} 
                    onReset={handleResetProfile} 
                    onExportShard={exportSave}
                    addEchoMessage={addEchoMessage} 
                />
            )}

            <RPGNexusPanel 
              width={700} 
              height={700} 
              addEchoMessage={addEchoMessage} 
              activeProfile={activeProfile} 
              onUpdateProfile={handleUpdateProfile} 
              currentEntropy={effectiveSystemEntropy} 
              systemMode={codexModeId} 
              onArtifactCreated={addArtifact} 
              artifacts={artifacts} 
              savedState={rpgState} 
              onSaveState={handleSaveRPGState} 
              onUpdateSystemMetrics={handleSystemMetricsUpdate} 
            />

            <PrimeGenesisPanel width={700} height={1450} addEchoMessage={addEchoMessage} onArtifactCreated={addArtifact} />

            <CodexDreamPanel 
              currentEntropy={effectiveSystemEntropy} 
              currentAxioms={ALL_CANONICAL_AXIOMS} 
              lambdaValue={1.0} 
              negentropyLevel={negentropyLevel} 
              echoLog={echoLog} 
              addEchoMessage={addEchoMessage} 
              width={700} height={700} 
              currentPhase="Synthesis" 
              chaliceStatus="Stable" 
              onArtifactCreated={addArtifact}
            />

            <MutationLoomPanel glyphMutationNodes={[]} onWeaveGlyphs={async () => undefined} mutationLoomState={mutationLoomState} setMutationLoomState={setMutationLoomState} addEchoMessage={addEchoMessage} isGeminiGenerating={isGeminiGenerating} />

            <RitualCanvasContainer 
              addEchoMessage={addEchoMessage} 
              placedGlyphs={placedGlyphs} setPlacedGlyphs={setPlacedGlyphs} 
              connections={connections} setConnections={setConnections} 
              onRitualActivated={handleRitualActivated} 
              availableAxiomElements={AXIOM_RITUAL_ELEMENTS} 
              invokeGemini={invokeGemini} 
              isGeminiGenerating={isGeminiGenerating} 
              onAnalyzeForRewrite={() => {}} 
            />

            <TemporalOperationsConsolePanel width={700} height={800} addEchoMessage={addEchoMessage} />
            <GlyphComposerPanel addEchoMessage={addEchoMessage} isBugaModeActive={false} />
            <CodexPandiumPanel width={700} height={600} />
          </section>

          <aside className="lg:col-span-3 flex flex-col gap-4 overflow-y-auto custom-scrollbar pl-1">
            <EntropicHeartPanel currentEntropy={effectiveSystemEntropy} />
            <LIFEPanel currentEntropy={effectiveSystemEntropy} addEchoMessage={addEchoMessage} />
            <HarmonicCorePanel lambdaValue={1.0} status="Stabilized" eleganceIndex={0.98} />
            <EntropyDiagnosticsPanel baseEntropy={currentEntropy} effectiveEntropy={effectiveSystemEntropy} masterEntropyOverridePercent={0} entropyHistory={[currentEntropy]} playbackTime={0} isPlaying={true} />

            <div className="p-4 bg-slate-900/10 border border-slate-700 rounded-xl backdrop-blur-sm">
               <h4 className="font-cinzel text-indigo-300 mb-2 uppercase tracking-widest text-xs">System Directory</h4>
               <SystemModulesPanel onLaunchModule={onLaunchModule} />
            </div>

            <DriftDifferentialOverlay currentEntropy={effectiveSystemEntropy} glyphDriftHistory={[]} glyphMutationNodes={[]} currentRitualContext="System Analysis" isGeminiGenerating={isGeminiGenerating} addEchoMessage={addEchoMessage} logGeminiNarrativeDriftEvent={() => {}} />
            <CelestialAnomalyWeaverPanel width={350} height={450} addEchoMessage={addEchoMessage} />
            <CelestialEntropyCyclePanel currentEntropy={effectiveSystemEntropy} width={350} height={450} />
            <CosmicResonanceDashboardPanel width={350} height={500} addEchoMessage={addEchoMessage} />
            <FlowerOfLifeEntropyExplorer currentEntropy={effectiveSystemEntropy} width={350} height={500} currentDisplayMode={geoMode} onSetDisplayMode={(m) => setGeoMode(m as GeoMode)} />
            <ExoticMechanismsPanel currentEntropy={effectiveSystemEntropy} width={350} height={500} addEchoMessage={addEchoMessage} />
            <EntropyDimensionDiagramPanel currentEntropy={effectiveSystemEntropy} width={350} height={500} isFractalModeEnabled={true} />
            <CrystalFormationPanel width={350} height={400} currentEntropy={effectiveSystemEntropy} />

            <EchoScribePanel echoes={echoLog} />
            <ChronicleReliquaryPanel width={350} height={500} artifacts={artifacts} addEchoMessage={addEchoMessage} />
            <AxiomResonanceViewerPanel axioms={ALL_CANONICAL_AXIOMS} panelHeight={400} />

            <DatachegaResthetPanel addEchoMessage={addEchoMessage} />
            <AethelWeftCodexUpdatePanel panelHeight={500} />
            <TabletOfThePhoenixPanel panelHeight={300} />
            <ShatterpointTracePanel objective="Trace System Roots" triggerGlyph="Null" axiomaticLinks={[]} traceParameters={{temporal_filter:'None', entropy_signature:'Stable', search_depth:'Deep', paradox_safety:'High'}} oracleCommentary="System trace active." />
          </aside>

        </main>

        <CodexFooterBar phase="Synthesis" mode={codexModeId} status="System Active" currentEntropy={effectiveSystemEntropy} currentCodexModeId={codexModeId} onApplyOmegaAnchor={() => setCurrentEntropy(e => Math.max(0, e - 0.1))} />
        <Footer />

        <PanelModal
          isOpen={!!activeModal}
          onClose={closeModal}
          title={activeModal ? activeModal.replace(/_/g, ' ').toUpperCase() : 'MODULE'}
          width={activeModal === 'agent_directory' ? 850 : 1200}
        >
          <div className="p-4 text-center">Module visualization active in main hub.</div>
        </PanelModal>

        <SaveLoadModal 
           isOpen={isSaveLoadModalOpen}
           onClose={() => setIsSaveLoadModalOpen(false)}
           onSave={saveGame}
           onLoad={handleLoadSlot}
           fetchSlots={getSaveSlots}
        />

      </div>
    </SystemStateProvider>
  );
};

export default App;

