// --- Audio Decoding Helpers ---
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PrimeGenesisPanel: React.FC<PrimeGenesisPanelProps> = ({ width, height, addEchoMessage, onArtifactCreated }) => {
    const audioContextRef = useRef<AudioContext | null>(null);
    const [activeMovement, setActiveMovement] = useState<GenesisMovement | null>(null);
    const [resultText, setResultText] = useState<string | null>(null);
    const [resultImage, setResultImage] = useState<string | null>(null);
    const [isWeaving, setIsWeaving] = useState(false);
    const [isNarratorEnabled, setIsNarratorEnabled] = useState(true);
    const [isSpeaking, setIsSpeaking] = useState(false);

    const { invokeGemini, generateImage, generateSpeech } = useGemini();

    const playNarration = async (text: string) => {
        if (!text || !isNarratorEnabled) return;
        setIsSpeaking(true);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

            const audioData = await generateSpeech(text, 'Kore');
            if (audioData) {
                const buffer = await decodeAudioData(new Uint8Array(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = buffer;
                source.connect(audioContextRef.current.destination);
                source.onended = () => setIsSpeaking(false);
                source.start(0);
            }
        } catch (e) { 
            console.error("Prime Narration Error", e);
            setIsSpeaking(false); 
        }
    };

    const handleSelectMovement = async (m: GenesisMovement) => {
        if (isWeaving) return;
        setActiveMovement(m);
        setIsWeaving(true);
        setResultText(null);
        setResultImage(null);
        globalSoundEngine.playSFX('pulse');
        addEchoMessage(AgentName.PrimeConductor, `Initiating Omega Protocol: ${m.title}...`, 'text-indigo-400 font-bold');

        try {
            const [text, img] = await Promise.all([
                invokeGemini(m.prompt, "You are the Prime Conductor of a transcended cosmic reality."),
                generateImage(`Masterpiece vision, ${m.title}. Non-commutative geometry. No text.`, 'gemini-2.5-flash-image')
            ]);
            setResultText(text);
            setResultImage(img);
            if (text) playNarration(text);
            // Fixed: use string literal for type
            if (img) onArtifactCreated({ id: `prime-${Date.now()}`, name: `Fragment: ${m.title}`, type: 'OmegaRelic', rarity: ArtifactRarity.Mythic, description: m.description, imageUrl: img, timestamp: Date.now() });
            addEchoMessage(AgentName.PrimeConductor, `Movement ${m.id} solidified in the Hilbert Matrix.`, 'text-emerald-400');
        } catch (e) { addEchoMessage(AgentName.System, "Fracture detected. Re-anchoring...", "text-rose-400"); } finally { setIsWeaving(false); }
    };

    return (
        <div className="bg-slate-950 flex flex-col relative overflow-hidden rounded-2xl border border-indigo-500/20 shadow-2xl" style={{ width, height: `${height}px` }}>
            <div className="relative z-10 p-12 flex flex-col h-full overflow-hidden">
                <header className="mb-10 text-center shrink-0">
                    <div className="flex justify-center gap-4 mb-4">
                        <div className="inline-block px-4 py-1 rounded-full border border-indigo-500/30 bg-indigo-500/10 text-[10px] font-mono text-indigo-400 uppercase tracking-[0.4em]">Terminal // 0xΩ</div>
                        <button onClick={() => setIsNarratorEnabled(!isNarratorEnabled)} className={`px-4 py-1 rounded-full border text-[10px] font-mono tracking-widest ${isNarratorEnabled ? 'bg-emerald-900/40 border-emerald-500 text-emerald-400' : 'bg-slate-900 border-slate-700 text-slate-500'}`}>
                            NARRATOR: {isNarratorEnabled ? 'ON' : 'OFF'}
                        </button>
                    </div>
                    <h2 className="text-7xl font-cinzel font-bold text-white tracking-[0.3em]">PRIME GENESIS</h2>
                </header>

                <div className="flex-grow grid grid-cols-1 lg:grid-cols-2 gap-12 min-h-0 overflow-hidden">
                    <div className="flex flex-col gap-4 overflow-y-auto custom-scrollbar pr-4">
                        {MOVEMENTS.map(m => (
                            <button key={m.id} onClick={() => handleSelectMovement(m)} disabled={isWeaving} className={`p-6 rounded-2xl border-2 text-left transition-all ${activeMovement?.id === m.id ? 'bg-indigo-950 border-indigo-400 shadow-xl' : 'bg-slate-900/50 border-slate-800 hover:border-indigo-500'}`}>
                                <h4 className="text-xl font-bold font-cinzel text-indigo-200">{m.id}. {m.title}</h4>
                                <p className="text-xs text-slate-500 italic mt-2">{m.description}</p>
                            </button>
                        ))}
                    </div>
                    <div className="flex flex-col h-full overflow-hidden">
                        <AnimatePresence mode="wait">
                            {activeMovement && (
                                <motion.div key="res" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="h-full flex flex-col gap-6 overflow-hidden">
                                    <div className="relative aspect-[16/10] rounded-3xl border-2 border-indigo-500/40 overflow-hidden bg-black shadow-2xl shrink-0">
