import React, { useState, useRef } from 'react';
import { CodexModeId, AppTheme } from '../types'; 
import { THEME_DATA } from '../constants';

interface HeaderProps {
  currentEntropy: number;
  negentropy: number;
  lambda: number;
  currentTheme?: AppTheme;
  onSetTheme?: (theme: AppTheme) => void;
  onProvokeThornedRose: () => void;
  onTuneFrequency: () => void;
  onRecallAncestor: () => void;
  onBurnPetals: () => void;
  onAwakenLotusDream: () => void;
  onPulseAstralJasmine: () => void;
  onGraftThorns: () => void;
  onToggleAutoEcho: () => void;
  onAmplifyVoices: () => void;
  onSeedDream: () => void;
  isAutoEchoPaused: boolean;
  onInvokeGeminiOracle: () => void;
  onContextualOracleQuery: () => void; 
  onToggleAshfall: () => void;
  showAshfall: boolean;
  showLogicWebDebug: boolean;
  onToggleLogicWebDebug: () => void;
  isAuditing: boolean;
  onToggleAuditMode: () => void;
  isAuditModeLocked: boolean; 
  currentCodexModeId: CodexModeId;
  activateCodexMode: (modeId: CodexModeId) => void;
  onDumpThreadSummary: () => void; 
  showSigilOverlay: boolean; 
  onToggleSigilOverlay: () => void; 
  onTraceThreadcoil: () => void;
  onReEnterJunction: () => void;
  onExtractSigil: () => void;
  isBugaModeActive: boolean;
  onToggleBugaMode: () => void;
  isMuted: boolean;
  onToggleMute: () => void;
  onApplyOmegaAnchor?: () => void;
  onSystemRestore?: () => void;
  isOmegaAnchorDisabled?: boolean;
  onLaunchNexus: () => void;
  onExportSave?: () => void;
  onImportSave?: (file: File) => void;
  onOpenSaveLoadModal?: () => void;
  saveStatus?: 'idle' | 'saving' | 'saved' | 'error';
  lastSavedTime?: number | null;
}

export const Header: React.FC<HeaderProps> = ({ 
  currentEntropy,
  negentropy,
  lambda,
  currentTheme,
  onSetTheme,
  onProvokeThornedRose,
  onTuneFrequency,
  onRecallAncestor,
  onBurnPetals,
  onAwakenLotusDream,
  onPulseAstralJasmine,
  onGraftThorns,
  onToggleAutoEcho,
  onAmplifyVoices,
  onSeedDream,
  isAutoEchoPaused,
  onInvokeGeminiOracle,
  onContextualOracleQuery,
  onToggleAshfall,
  showAshfall,
  showLogicWebDebug,
  onToggleLogicWebDebug,
  isAuditing,
  onToggleAuditMode,
  isAuditModeLocked,
  currentCodexModeId,
  activateCodexMode,
  onDumpThreadSummary,
  showSigilOverlay, 
  onToggleSigilOverlay, 
  onTraceThreadcoil,
  onReEnterJunction,
  onExtractSigil,
  isBugaModeActive, 
  onToggleBugaMode,
  isMuted,
  onToggleMute,
  onApplyOmegaAnchor,
  onSystemRestore,
  isOmegaAnchorDisabled,
  onLaunchNexus,
  onExportSave,
  onImportSave,
  onOpenSaveLoadModal,
  saveStatus = 'idle',
  lastSavedTime
}) => {
  const [isFloraMenuOpen, setIsFloraMenuOpen] = useState(false);
  const [isSystemMenuOpen, setIsSystemMenuOpen] = useState(false);
  const [isCodexModeMenuOpen, setIsCodexModeMenuOpen] = useState(false);
  const [isThemeMenuOpen, setIsThemeMenuOpen] = useState(false);
  const [isOracleMenuOpen, setIsOracleMenuOpen] = useState(false); 
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const availableModesForSwitching: {id: CodexModeId, name: string, icon: string}[] = [
    {id: CodexModeId.ORIGIN_STATE, name: "Δ.OriginState", icon: "ri-omega"},
    {id: CodexModeId.REFLECTION_MODE, name: "Σ.ReflectionMode", icon: "ri-reflect-fill"},
    {id: CodexModeId.SYMBIOTIC_WEAVE, name: "Δ.SymbioticWeave", icon: "ri-links-line"},
    {id: CodexModeId.VEIL_MODE, name: "Θ.VeilMode", icon: "ri-eye-off-line"},
    {id: CodexModeId.SYNTHESIS_MODE, name: "Φ.SynthesisMode", icon: "ri-node-tree"},
    {id: CodexModeId.TARDIS_SYNCHRONICITY, name: "Temporal Loom Nav.", icon: "ri-route-line"}, 
    {id: CodexModeId.FLAME_CORE, name: "Δ.Ω.FLAMECORE", icon: "ri-fire-fill"},
  ];

  const closeAllMenus = () => {
    setIsFloraMenuOpen(false);
    setIsSystemMenuOpen(false);
    setIsCodexModeMenuOpen(false);
    setIsThemeMenuOpen(false);
    setIsOracleMenuOpen(false);
    setIsMobileMenuOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && onImportSave) {
        onImportSave(e.target.files[0]);
    }
    if (fileInputRef.current) fileInputRef.current.value = "";
    closeAllMenus();
  };

  const SystemMetricsHUD = () => (
    <div className="flex items-center gap-3 bg-slate-900/40 backdrop-blur-md p-1.5 rounded-lg border border-slate-700/50 shadow-inner">
      <div className="flex flex-col items-center min-w-[50px]">
        <span className="text-[9px] text-slate-500 uppercase tracking-wider font-bold mb-0.5">Entropy</span>
        <div className="flex items-center gap-1.5">
          <div className={`w-2 h-2 rounded-full ${currentEntropy > 0.6 ? 'bg-red-500 animate-pulse' : 'bg-blue-400 animate-pulse-slow'}`}></div>
          <span className={`text-xs font-mono font-bold ${currentEntropy > 0.6 ? 'text-red-400' : 'text-blue-300'}`}>
            {currentEntropy.toFixed(3)}δ
          </span>
        </div>
      </div>
      <div className="w-px h-6 bg-slate-700/50"></div>
      <div className="flex flex-col items-center min-w-[50px]">
        <span className="text-[9px] text-slate-500 uppercase tracking-wider font-bold mb-0.5">Vitality</span>
        <div className="flex items-center gap-1.5">
          <div className={`w-2 h-2 rounded-sm ${negentropy < 0.3 ? 'bg-yellow-500 animate-pulse' : 'bg-emerald-500 animate-pulse-slow'}`}></div>
          <span className={`text-xs font-mono font-bold ${negentropy < 0.3 ? 'text-yellow-400' : 'text-emerald-300'}`}>
            {negentropy.toFixed(3)}ν
          </span>
        </div>
      </div>
    </div>
  );

  const renderSaveStatus = () => {
      if (saveStatus === 'saving') {
          return <span className="text-[10px] text-amber-400 animate-pulse ml-2"><i className="ri-save-line mr-1"></i>Saving...</span>;
      } else if (saveStatus === 'error') {
          return <span className="text-[10px] text-rose-400 ml-2"><i className="ri-error-warning-line mr-1"></i>Save Error</span>;
      } else if (saveStatus === 'saved') {
          return <span className="text-[10px] text-emerald-400 ml-2"><i className="ri-check-line mr-1"></i>Synced</span>;
      }
      return null;
  }

  return (
    <header className="bg-slate-900/60 backdrop-blur-xl border-b border-slate-800/80 py-2 px-4 md:px-6 sticky top-0 z-50">
      <input type="file" ref={fileInputRef} onChange={handleFileChange} style={{display: 'none'}} accept=".json" />
      <div className="w-full flex justify-between items-center flex-wrap gap-y-2">
        <div className="flex items-center gap-4">
            <h1 className="text-lg md:text-2xl font-cinzel font-bold text-slate-100 flex items-center gap-2">
            <i className="ri-ancient-gate-fill text-indigo-500"></i>
            <span className="hidden md:inline">Tri-Sophian Codex</span>
            </h1>
            <div className="hidden lg:flex items-center">
                <SystemMetricsHUD />
                {renderSaveStatus()}
            </div>
        </div>

        <div className="flex items-center space-x-2 md:space-x-3"> 
          <div className="relative">
            <button onClick={() => setIsThemeMenuOpen(!isThemeMenuOpen)} className="rounded-button bg-slate-800 hover:bg-slate-700 text-slate-200 px-3 py-1.5 text-xs md:text-sm transition flex items-center border border-slate-700">
              <i className="ri-palette-line mr-2"></i>
              <span className="hidden sm:inline">Resonance</span>
              <i className={`ri-arrow-down-s-line ml-1 transform transition-transform ${isThemeMenuOpen ? 'rotate-180' : ''}`}></i>
            </button>
            {isThemeMenuOpen && (
              <div className="absolute right-0 mt-2 w-48 rounded-md shadow-2xl bg-slate-900 border border-slate-700 ring-1 ring-black ring-opacity-5 py-1 z-50">
                {THEME_DATA.map(theme => (
                  <button 
                    key={theme.id} 
                    onClick={() => { onSetTheme?.(theme.id); setIsThemeMenuOpen(false); }} 
                    className={`w-full text-left px-4 py-2 text-sm transition flex items-center ${currentTheme === theme.id ? 'bg-slate-800 font-bold' : 'hover:bg-slate-800 text-slate-300'}`}
                  >
                    <i className={`${theme.icon} mr-2 ${theme.color}`}></i>{theme.name}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="relative">
            <button onClick={() => setIsCodexModeMenuOpen(!isCodexModeMenuOpen)} className="rounded-button bg-purple-700 hover:bg-purple-600 text-white px-3 py-1.5 text-xs md:text-sm transition whitespace-nowrap flex items-center">
              <i className="ri-compass-discover-line mr-1 md:mr-2"></i>
              <span className="hidden md:inline">Codex Mode</span>
              <i className={`ri-arrow-down-s-line ml-1 transform transition-transform ${isCodexModeMenuOpen ? 'rotate-180' : ''}`}></i>
            </button>
            {isCodexModeMenuOpen && (
              <div className="absolute right-0 mt-2 w-56 rounded-md shadow-2xl bg-slate-900 border border-slate-700 ring-1 ring-black ring-opacity-5 py-1 z-50">
                {availableModesForSwitching.map(mode => (
                   <button key={mode.id} onClick={() => { activateCodexMode(mode.id); setIsCodexModeMenuOpen(false); }} className={`w-full text-left px-4 py-2 text-sm transition flex items-center ${currentCodexModeId === mode.id ? 'text-amber-300 bg-amber-800 font-semibold' : 'text-slate-300 hover:bg-slate-800'}`}>
                    <i className={`${mode.icon} mr-2 ${currentCodexModeId === mode.id ? 'text-amber-400' : 'text-slate-400'}`}></i>{mode.name}
                  </button>
                ))}
              </div>
            )}
          </div>

          <button onClick={onToggleMute} className={`rounded-button p-2 text-sm transition ${isMuted ? 'text-slate-500' : 'text-slate-200 hover:bg-slate-800'}`}>
            <i className={`ri-${isMuted ? 'volume-mute-line' : 'volume-up-line'}`}></i>
          </button>
        </div>
      </div>
    </header>
  );
};

