import SeekerProfileWeaverPanel from './components/panels/SeekerProfileWeaverPanel';

const App: React.FC = () => {
  const [booting, setBooting] = useState(true);
  const [stage, setStage] = useState<'ONBOARDING' | 'MAIN'>('ONBOARDING');
  const [activeProfile, setActiveProfile] = useState<SeekerProfile | null>(null);
  const [seekerTraits, setSeekerTraits] = useState<string[]>([]);
  const [rpgState, setRpgState] = useState<RPGGameState | undefined>(undefined);
  const [placedGlyphs, setPlacedGlyphs] = useState<PlacedGlyph[]>([]);
  const [connections, setConnections] = useState<CanvasConnection[]>([]);
  const [artifacts, setArtifacts] = useState<CodexArtifact[]>([]);
  const [currentEntropy, setCurrentEntropy] = useState(0.1);
  const [echoLog, setEchoLog] = useState<EchoMessage[]>([]);
  const [currentCodexModeId, setCurrentCodexModeId] = useState<CodexModeId>(CodexModeId.ORIGIN_STATE);
  const [currentTheme, setCurrentTheme] = useState<AppTheme>(AppTheme.OBSIDIAN);

  // Modal State
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);

  const { invokeGemini, isGenerating: isGeminiGenerating } = useGemini();

  const stateSnapshot = useMemo(() => ({
    activeProfile,
    echoLog,
    currentEntropy,
    appTheme: currentTheme,
    artifacts
  }), [activeProfile, echoLog, currentEntropy, currentTheme, artifacts]);

  const { hydrateState, deleteSave, saveGame } = useCodexPersistence(['ActiveProfile', 'AppTheme', 'Artifacts'], stateSnapshot);

  useEffect(() => {
    hydrateState().then(hydrated => {
      if (hydrated) {
        if (hydrated.activeProfile) {
          setActiveProfile(hydrated.activeProfile);
          setStage('MAIN');
        }
        if (hydrated.appTheme) {
          setCurrentTheme(hydrated.appTheme);
        }
        if (hydrated.artifacts) {
          setArtifacts(hydrated.artifacts);
        }
      }
    });
  }, [hydrateState]);

  const addEchoMessage = useCallback((source: string, text: string, colorClass: string = "text-slate-300") => {
    const newMessage: EchoMessage = {
      id: `echo-${Date.now()}-${Math.random()}`,
      source,
      text,
      colorClass,
      timestamp: new Date().toLocaleTimeString()
    };
    setEchoLog(prev => [newMessage, ...prev].slice(0, 100));
  }, []);

  const handleResetProfile = async () => {
    if(confirm("Sever this identity? All progress will be lost and you will return to the Synthesis Loom.")) {
        setStage('ONBOARDING');
        setActiveProfile(null);
        setSeekerTraits([]);
        setRpgState(undefined);
        setPlacedGlyphs([]);
        setConnections([]);
        setArtifacts([]);
        setCurrentEntropy(0.1);
        setEchoLog([]);
        await deleteSave('autosave');
        addEchoMessage(AgentName.System, "Identity Shard Severed. Chrono-Loop Reset.", "text-rose-400");
        globalSoundEngine.playSFX('fail');
    }
  };

  const handleProfileComplete = (profile: SeekerProfile) => {
    setActiveProfile(profile);
    setStage('MAIN');
    addEchoMessage(AgentName.System, `Welcome, Seeker ${profile.name}.`, "text-cyan-400");
    globalSoundEngine.init();
    globalSoundEngine.playSFX('success');
  };

  const handleLaunchModule = (id: string) => {
    setActiveModuleId(id);
    addEchoMessage(AgentName.System, `Launching Module: ${id.replace(/_/g, ' ').toUpperCase()}`, "text-indigo-400");
    globalSoundEngine.playUIFeedback('click');
  };

  const activeThemeConfig = useMemo(() => {
    return THEME_DATA.find(t => t.id === currentTheme) || THEME_DATA[0];
  }, [currentTheme]);

  const renderActiveModule = () => {
    if (!activeModuleId) return null;

    switch (activeModuleId) {
      case 'prime_genesis':
        return <PrimeGenesisPanel width={1000} height={700} addEchoMessage={addEchoMessage} onArtifactCreated={(a) => setArtifacts(prev => [a, ...prev])} />;
      case 'rpg_nexus':
        return <SeekerProfileWeaverPanel width={1100} height={750} addEchoMessage={addEchoMessage} existingProfile={activeProfile} onUpdateProfile={setActiveProfile} />;
      case 'protocol_duel':
        return <ProtocolDuelPanel width={900} height={700} activeProfile={activeProfile} onUpdateProfile={setActiveProfile} addEchoMessage={addEchoMessage} />;
      case 'flux_farm':
        return <FluxFarmPanel width={1000} height={700} activeProfile={activeProfile} onUpdateProfile={setActiveProfile} currentEntropy={currentEntropy} addEchoMessage={addEchoMessage} />;
      case 'dreambloom':
        return <DreambloomGenesisPanel interpretations={[]} onConjurePulse={() => {}} isAutoActive={false} onToggleAuto={() => {}} isLoading={false} addEchoMessage={addEchoMessage} />;
      case 'mutation_loom':
        return <MutationLoomPanel glyphMutationNodes={[]} onWeaveGlyphs={async () => undefined} mutationLoomState={{glyph1Id:null, glyph2Id:null, isWeaving:false, entropyInjection:0, traitFocus:[]}} setMutationLoomState={() => {}} addEchoMessage={addEchoMessage} isGeminiGenerating={isGeminiGenerating} />;
      case 'glyph_composer':
        return <GlyphComposerPanel addEchoMessage={addEchoMessage} isBugaModeActive={false} />;
      case 'emerald_tablet':
        return <EmeraldTabletDecryptionPanel currentSystemEntropy={currentEntropy} currentEleganceIndex={0.9} addEchoMessage={addEchoMessage} width={1000} height={700} />;
      case 'celestial_anomaly':
        return <CelestialAnomalyWeaverPanel width={1000} height={700} addEchoMessage={addEchoMessage} />;
      case 'crystal_garden':
        return <CrystalFormationPanel width={800} height={600} currentEntropy={currentEntropy} />;
      case 'geometry_explorer':
        return <CosmicEntropyGeometryGenerator currentEntropy={currentEntropy} currentPhase="Standard" chaliceStatus="Stable" width={800} height={600} currentGeoMode={GeoMode.CrystalLogic} onSetGeoMode={() => {}} />;
      case 'exotic_mechanisms':
        return <ExoticMechanismsPanel currentEntropy={currentEntropy} width={800} height={600} addEchoMessage={addEchoMessage} />;
      case 'celestial_entropy':
        return <CelestialEntropyCyclePanel currentEntropy={currentEntropy} width={800} height={600} />;
      case 'dimension_diagram':
        return <EntropyDimensionDiagramPanel currentEntropy={currentEntropy} width={800} height={600} isFractalModeEnabled={true} />;
      case 'glyph_vis':
        return <GlyphVisualizationPanel panelHeight={700} glyphData={{id:'G-01', title:'Primal Eye', description:'...', resonance:'88.3Hz', traits:[], linkedAxioms:[], ritualAffinity:'High'}} pulseDetails={{label:'P-01', glyphId:'G-01', state:'Stable', mode:'Standard', signatureFrequency:'88Hz', shadowArchiveDepth:'Deep', decryptionTraits:[]}} visualizationDetails={{initialPhase:{title:'Phase 1', form:'Circular', visual:'Luminous', animation:'Pulse'}, sonicProfile:{description:'Low Hum'}, finalForm:{description:'Crystalline', sigilPulse:['alpha'], overlay:'Fractal'}}} systemNote={{uses:[], concludingQuote:'Order from Chaos.'}} />;
      case 'crm_dashboard':
        return <CosmicResonanceDashboardPanel width={1100} height={700} addEchoMessage={addEchoMessage} />;
      case 'temporal_ops':
        return <TemporalOperationsConsolePanel width={1100} height={700} addEchoMessage={addEchoMessage} />;
      case 'drift_differential':
        return <DriftDifferentialOverlay currentEntropy={currentEntropy} glyphDriftHistory={[]} glyphMutationNodes={[]} currentRitualContext="Calibration" isGeminiGenerating={isGeminiGenerating} addEchoMessage={addEchoMessage} logGeminiNarrativeDriftEvent={() => {}} />;
      case 'harmonic_core':
        return <HarmonicCorePanel lambdaValue={1.0} status="Stabilized" eleganceIndex={0.95} />;
      case 'entropy_diagnostics':
        return <EntropyDiagnosticsPanel baseEntropy={currentEntropy} effectiveEntropy={currentEntropy} masterEntropyOverridePercent={0} entropyHistory={[]} playbackTime={0} isPlaying={false} />;
      case 'peptide_sim':
        return <PeptideSimulationPanel addEchoMessage={addEchoMessage} width={800} height={600} />;
      case 'codex_pandium':
        return <CodexPandiumPanel width={1100} height={750} />;
      case 'datachega':
        return <DatachegaResthetPanel addEchoMessage={addEchoMessage} />;
      case 'aethel_update':
        return <AethelWeftCodexUpdatePanel panelHeight={700} />;
      case 'phoenix_tablet':
        return <TabletOfThePhoenixPanel panelHeight={400} />;
      case 'shatterpoint_trace':
        return <ShatterpointTracePanel objective="Locate Fracture" triggerGlyph="Ashen" axiomaticLinks={[]} traceParameters={{entropy_signature:"0.1", temporal_filter:"None"}} oracleCommentary="Searching..." />;
      case 'buga_codex':
        return <BugaGlyphCodexPanel width={1000} height={700} />;
      case 'flora_chamber':
        return <BloodInkFloraChamber activeSpeciesName={null} allSpeciesData={{}} />;
      case 'sigil_bloom':
        return <SigilBloomVariantPanel glyphMutationNodes={[]} onRevealBloomVariants={() => {}} sigilBloomVariants={[]} selectedBloomVariantId={null} onSelectBloomVariant={() => {}} isGeneratingBloomVariants={false} isGeminiBusy={isGeminiGenerating} />;
      default:
        return <div className="p-20 text-center text-slate-500 italic">Module interface under construction...</div>;
    }
  };

  if (booting) {
    return <BootSequence onComplete={() => setBooting(false)} />;
  }

  if (stage === 'ONBOARDING') {
    return <OnboardingFunnel onComplete={handleProfileComplete} addEchoMessage={addEchoMessage} />;
  }

  return (
    <div className={`min-h-screen ${activeThemeConfig.bgClass} text-slate-100 flex flex-col font-cormorant transition-colors duration-1000`}>
      <Header 
        currentEntropy={currentEntropy}
        negentropy={1 - currentEntropy}
        lambda={1.0}
        currentTheme={currentTheme}
        onSetTheme={setCurrentTheme}
        onLaunchNexus={() => handleLaunchModule('rpg_nexus')}
        onProvokeThornedRose={() => {}}
        onTuneFrequency={() => {}}
        onRecallAncestor={() => {}}
        onBurnPetals={() => {}}
        onAwakenLotusDream={() => {}}
        onPulseAstralJasmine={() => {}}
        onGraftThorns={() => {}}
        onToggleAutoEcho={() => {}}
        onAmplifyVoices={() => {}}
        onSeedDream={() => {}}
        isAutoEchoPaused={false}
        onInvokeGeminiOracle={() => {}}
        onContextualOracleQuery={() => {}}
        onToggleAshfall={() => {}}
        showAshfall={false}
        showLogicWebDebug={false}
        onToggleLogicWebDebug={() => {}}
        isAuditing={false}
        onToggleAuditMode={() => {}}
        isAuditModeLocked={false}
        currentCodexModeId={currentCodexModeId}
        activateCodexMode={setCurrentCodexModeId}
        onDumpThreadSummary={() => {}}
        showSigilOverlay={false}
        onToggleSigilOverlay={() => {}}
        onTraceThreadcoil={() => {}}
        onReEnterJunction={() => {}}
        onExtractSigil={() => {}}
        isBugaModeActive={false}
        onToggleBugaMode={() => {}}
        isMuted={false}
        onToggleMute={() => {}}
      />

      <main className="flex-grow p-4 md:p-8 space-y-8 relative z-10">
        {activeProfile && (
          <SeekerProfileDashboardPanel 
            profile={activeProfile} 
            onReset={handleResetProfile} 
            onExportShard={() => {}} 
            addEchoMessage={addEchoMessage} 
          />
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           <RitualCanvasContainer 
              addEchoMessage={addEchoMessage}
              placedGlyphs={placedGlyphs}
              connections={connections}
              setPlacedGlyphs={setPlacedGlyphs}
              setConnections={setConnections}
              onRitualActivated={(success, details) => {
                addEchoMessage(AgentName.RitualAlchemist, details, success ? 'text-emerald-400' : 'text-rose-400');
              }}
              availableAxiomElements={[]}
              invokeGemini={invokeGemini}
              isGeminiGenerating={isGeminiGenerating}
              onAnalyzeForRewrite={() => {}}
           />
           <EchoScribePanel echoes={echoLog} />
        </div>

        <SystemModulesPanel onLaunchModule={handleLaunchModule} />
      </main>

      <PanelModal 
        isOpen={!!activeModuleId} 
        onClose={() => setActiveModuleId(null)}
        title={activeModuleId ? activeModuleId.replace(/_/g, ' ').toUpperCase() : ''}
        width={activeModuleId === 'prime_genesis' || activeModuleId === 'codex_pandium' ? '95%' : '90%'}
      >
        {renderActiveModule()}
      </PanelModal>

      <div className={`fixed inset-0 pointer-events-none opacity-20 z-0 ${activeThemeConfig.color.replace('text-', 'bg-')} blur-[120px] transition-all duration-1000`}></div>
