    { id: 'arm-06', name: 'Harmonic Shell', type: 'Armor' as any, rarity: ArtifactRarity.Rare, description: 'Sound-dampening armor; reduces AoE sonic attacks.', visualPromptMod: 'acoustic panel inspired suit with tuning fork accents', cost: 800, icon: 'ri-volume-mute-line', combatStats: { atk: 0, def: 20, res: 45 } },
