    { id: 'high_magic', name: 'Academy of Axioms', icon: 'ri-book-open-line', color: 'from-violet-600/20 to-fuchsia-900/20', accent: 'text-fuchsia-400' },
    { id: 'post_apoc', name: 'Scavengers of Ash', icon: 'ri-fire-line', color: 'from-orange-900/20 to-stone-950/20', accent: 'text-orange-600' },
    { id: 'kaiju', name: 'Monarch Hunters', icon: 'ri-mickey-line', color: 'from-green-800/20 to-stone-900/20', accent: 'text-green-500' },
    { id: 'heist', name: 'Dimension Thieves', icon: 'ri-door-open-line', color: 'from-indigo-900/20 to-slate-900/20', accent: 'text-indigo-300' },
