                <div className="w-full relative">
                    <textarea 
                        value={missionInput}
                        onChange={(e) => setMissionInput(e.target.value)}
                        placeholder="Define your journey..."
                        className="w-full bg-slate-900/20 border border-white/10 rounded-2xl p-6 text-xl text-slate-100 focus:outline-none resize-none h-48 italic backdrop-blur-xl font-cormorant shadow-2xl pr-16"
                    />
                    <button onClick={handleRandomizeMission} className="absolute top-4 right-4 w-10 h-10 bg-indigo-900/40 border border-indigo-400/50 rounded-xl text-indigo-300 hover:text-white flex items-center justify-center">
                        <i className="ri-dice-fill text-xl"></i>
                    </button>
                </div>
                <div className="flex flex-col sm:flex-row gap-4 w-full">
                    <button onClick={() => setInitStep(1)} className="flex-1 bg-slate-800 text-slate-400 font-bold py-4 rounded-xl text-sm">BACK</button>
                    <button onClick={handleScanSector} disabled={isScanning} className="flex-1 bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-xl flex items-center justify-center gap-2">
                        {isScanning ? <i className="ri-loader-4-line animate-spin"></i> : "MATERIALIZE"}
