                <div className="grid grid-cols-1 gap-4 overflow-y-auto custom-scrollbar pb-10">
                    {(Object.entries(scanResults) as [string, RPGScanResultLocation][]).map(([name, data]) => (
                        <button 
                            key={name}
                            onClick={() => { handleTravel(name, data); setInitStep(0); }}
                            className="flex flex-col sm:flex-row p-6 bg-slate-900/20 border border-white/5 rounded-3xl hover:border-cyan-500/50 transition-all text-left gap-6 backdrop-blur-md"
