                <Button onClick={() => fileInputRef.current?.click()} className="w-full py-5 bg-slate-800 border border-white/10 font-bold text-xl rounded-xl">IMPORT REALITY</Button>
                <input type="file" ref={fileInputRef} onChange={handleFileImport} style={{display: 'none'}} accept=".json" />
            </div>
          </motion.div>
        )}

        {step === 'calibration' && (
          <motion.div key="calibration" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="w-full h-full max-w-4xl bg-slate-900/50 p-4 md:p-10 rounded-[2rem] border border-white/10 backdrop-blur-3xl overflow-y-auto custom-scrollbar">
            <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                <h3 className="text-2xl font-cinzel text-indigo-300 uppercase tracking-widest">Calibration</h3>
                <button onClick={handleRandomize} className="w-full md:w-auto px-6 py-3 bg-indigo-900/40 border border-indigo-500/50 rounded-xl text-white font-bold"><i className="ri-dice-fill mr-2"></i>ROLL FATES</button>
            </div>

            <div className="space-y-6">
                <div className="space-y-4">
                    <div className="space-y-1">
                        <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Designation</label>
                        <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-slate-800 border border-white/10 rounded-xl p-4 text-white text-lg" placeholder="Name..."/>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Biomorph</label>
                            <select value={race} onChange={(e) => setRace(e.target.value as SeekerAvatarType)} className={selectClasses}>
                                {AVATAR_RACES.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Archetype</label>
                            <select value={seekerClass} onChange={(e) => setSeekerClass(e.target.value as SeekerClass)} className={selectClasses}>
                                {SEEKER_CLASSES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="space-y-1">
                        <label className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Intention</label>
                        <textarea value={intent} onChange={(e) => setIntent(e.target.value)} className="w-full bg-slate-800 border border-white/10 rounded-xl p-4 text-white italic h-24" placeholder="Your mission..."/>
                    </div>
                </div>

                <div className="pt-6 border-t border-white/10">
                    <h4 className="text-xs font-cinzel text-slate-500 uppercase tracking-widest mb-4">Aetheric Gear</h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-1">
                             <label className="text-[10px] text-rose-400 font-bold uppercase tracking-widest">Weapon</label>
                             <select value={weaponId} onChange={(e) => setWeaponId(e.target.value)} className={selectClasses}>
                                {STARTER_WEAPONS.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
