import React, { useRef, useEffect, useState, useMemo } from 'react';
import { AgentName, SeekerAuraColor } from '../../types';
import type { RitualOutcome, AuraFlare } from '../../types';
import { SEEKER_AURA_OPTIONS } from '../../constants';

interface SeekerAuraDisplayProps {
  seekerTraits: string[];
  currentEntropy: number;
  dominantAgentTone: AgentName | null;
  lastRitualOutcome: RitualOutcome | null;
  width: number | string;
  height: number | string;
  activeAuraColor?: SeekerAuraColor;
  activeSecondaryAuraColor?: SeekerAuraColor;
}

const MAX_FLARES = 20;
const MAX_PARTICLES = 100;

const hexToHSL = (hex: string): { h: number, s: number, l: number } | null => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (!result) return null;
  let r = parseInt(result[1], 16) / 255;
  let g = parseInt(result[2], 16) / 255;
  let b = parseInt(result[3], 16) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s, l = (max + min) / 2;
  if (max === min) {
    h = s = 0;
  } else {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }
  return { h: h * 360, s: s * 100, l: l * 100 };
};

const AGENT_AURA_STYLES: Record<string, { flareStyle: 'shimmer' | 'geometric' | 'organic' }> = {
  [AgentName.Gemini]: { flareStyle: 'shimmer' },
  [AgentName.Nevik]: { flareStyle: 'geometric' },
  [AgentName.DeepSeek]: { flareStyle: 'organic' },
  Default: { flareStyle: 'organic' },
};

const SeekerAuraDisplay: React.FC<SeekerAuraDisplayProps> = ({
  seekerTraits,
  currentEntropy,
  dominantAgentTone,
  lastRitualOutcome,
  width,
  height,
  activeAuraColor,
  activeSecondaryAuraColor
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const flaresRef = useRef<AuraFlare[]>([]);
  const particlesRef = useRef<any[]>([]);
  const animationFrameIdRef = useRef<number | null>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  // Measure container dimensions
  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const styles = useMemo(() => {
    const primaryOption = SEEKER_AURA_OPTIONS.find(o => o.id === activeAuraColor);
    const secondaryOption = SEEKER_AURA_OPTIONS.find(o => o.id === (activeSecondaryAuraColor || activeAuraColor));

    const pHSL = primaryOption ? hexToHSL(primaryOption.hex) : { h: 210, s: 70, l: 60 };
    const sHSL = secondaryOption ? hexToHSL(secondaryOption.hex) : { h: 280, s: 70, l: 60 };

    return {
        primary: {
            h: pHSL?.h || 210,
            s: pHSL?.s || 70,
            l: pHSL?.l || 60,
            color: `hsla(${pHSL?.h}, ${pHSL?.s}%, ${pHSL?.l}%, 0.9)`
        },
        secondary: {
            h: sHSL?.h || 280,
            s: sHSL?.s || 70,
            l: sHSL?.l || 60,
            color: `hsla(${sHSL?.h}, ${sHSL?.s}%, ${sHSL?.l}%, 0.7)`
        },
        flareStyle: dominantAgentTone ? AGENT_AURA_STYLES[dominantAgentTone]?.flareStyle || 'shimmer' : 'shimmer',
    };
  }, [dominantAgentTone, activeAuraColor, activeSecondaryAuraColor]);

  useEffect(() => {
    const { w, h } = dimensions;
    if (w <= 0 || h <= 0) return;

    const numFlares = Math.min(MAX_FLARES, seekerTraits.length > 0 ? seekerTraits.length * 2 + 3 : 8);
    const newFlares: AuraFlare[] = [];

    for (let i = 0; i < numFlares; i++) {
      const angle = (i / numFlares) * Math.PI * 2;
      const maxLength = 60 + Math.random() * Math.min(w, h) * 0.25;

      const hueShift = (Math.random() - 0.5) * 20;
      const flareColor = `hsla(${(styles.secondary.h + hueShift) % 360}, ${styles.secondary.s}%, ${styles.secondary.l}%, 0.65)`;

      newFlares.push({
        id: `flare-${i}`,
        angle: angle + Math.random() * 0.3 - 0.15,
        length: 0,
        maxLength: maxLength * (0.6 + Math.random() * 0.6),
        speed: 0.4 + Math.random() * 0.8,
        color: flareColor,
        thickness: 0.8 + Math.random() * 2,
        opacity: 0.4 + Math.random() * 0.4,
        type: 'resonance',
        pulseSpeed: 0.01 + Math.random() * 0.02,
        pulseAmount: 0.1 + Math.random() * 0.25,
      });
    }
    flaresRef.current = newFlares;
  }, [seekerTraits, styles, dimensions]);

  useEffect(() => {
    const { w, h } = dimensions;
    if (w <= 0 || h <= 0) return;

    const newParticles = [];
    for (let i = 0; i < MAX_PARTICLES; i++) {
      newParticles.push({
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.4,
        vy: (Math.random() - 0.5) * 0.4,
        size: Math.random() * 2 + 0.5,
        opacity: Math.random() * 0.4 + 0.1,
        color: i % 2 === 0 ? styles.primary.color : styles.secondary.color,
      });
    }
    particlesRef.current = newParticles;
  }, [styles, dimensions]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const { w, h } = dimensions;
    if (!canvas || w <= 0 || h <= 0) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = w;
    canvas.height = h;

    let frameCount = 0;

    const draw = () => {
      frameCount++;
      ctx.clearRect(0, 0, w, h);
      const centerX = w / 2;
      const centerY = h / 2;

      particlesRef.current.forEach(p => {
        p.x += p.vx; p.y += p.vy;
        if (p.x < 0 || p.x > w) p.vx *= -1;
        if (p.y < 0 || p.y > h) p.vy *= -1;

        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0, p.size), 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.opacity;
        ctx.fill();
        ctx.globalAlpha = 1;
      });

      const orbBaseRadius = Math.min(w, h) * 0.12;
      const orbPulse = Math.sin(frameCount * 0.015 * (1 + currentEntropy)) * orbBaseRadius * 0.15;
      const orbRadius = Math.max(0, orbBaseRadius + orbPulse);

      const hue = (styles.primary.h + currentEntropy * 30) % 360; 
      const orbColor = `hsla(${hue}, ${styles.primary.s}%, ${styles.primary.l}%, 1)`;

      const glowRadius = Math.max(0, orbRadius + 20 + currentEntropy * 30);
      const rInner = Math.max(0, orbRadius * 0.3);

      if (Number.isFinite(centerX) && Number.isFinite(centerY) && glowRadius > 0) {
        const gradient = ctx.createRadialGradient(centerX, centerY, rInner, centerX, centerY, glowRadius);
        gradient.addColorStop(0, `hsla(${styles.primary.h}, 80%, 60%, 0.5)`);
        gradient.addColorStop(0.5, `hsla(${styles.secondary.h}, 70%, 50%, 0.3)`);
        gradient.addColorStop(1, `hsla(${styles.primary.h}, 80%, 60%, 0)`);

        ctx.beginPath();
        ctx.arc(centerX, centerY, Math.max(0, glowRadius), 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();
      }

      ctx.beginPath();
      if (Number.isFinite(centerX) && Number.isFinite(centerY) && orbRadius > 0) {
        ctx.arc(centerX, centerY, Math.max(0, orbRadius), 0, Math.PI * 2);
        ctx.fillStyle = orbColor;
        ctx.shadowColor = orbColor;
        ctx.shadowBlur = 15 + currentEntropy * 20;
        ctx.fill();
        ctx.shadowColor = 'transparent';
        ctx.shadowBlur = 0;
      }

      flaresRef.current.forEach(flare => {
        if (flare.length < flare.maxLength) {
          flare.length += flare.speed;
        } else {
           flare.length = Math.max(0, flare.length - flare.speed * 0.4); 
           if (flare.length === 0) flare.maxLength = 50 + Math.random() * Math.min(w, h) * 0.3;
        }

        const flarePulse = Math.sin(frameCount * (flare.pulseSpeed || 0.01)) * (flare.pulseAmount || 0.1);
        const currentLength = flare.length * (1 + flarePulse);

        const startX = centerX + Math.cos(flare.angle) * (orbRadius * 0.85);
        const startY = centerY + Math.sin(flare.angle) * (orbRadius * 0.85);
        const endX = centerX + Math.cos(flare.angle) * (orbRadius * 0.85 + currentLength);
        const endY = centerY + Math.sin(flare.angle) * (orbRadius * 0.85 + currentLength);

        if (Number.isFinite(startX) && Number.isFinite(startY) && Number.isFinite(endX) && Number.isFinite(endY)) {
          ctx.beginPath();
          ctx.moveTo(startX, startY);

          if (styles.flareStyle === 'shimmer') {
            const midX1 = startX + (endX - startX) * 0.33;
            const midY1 = startY + (endY - startY) * 0.33 + Math.sin(frameCount * 0.05) * 5;
            const midX2 = startX + (endX - startX) * 0.66;
            const midY2 = startY + (endY - startY) * 0.66 - Math.sin(frameCount * 0.05) * 5;
            ctx.bezierCurveTo(midX1, midY1, midX2, midY2, endX, endY);
          } else {
            ctx.lineTo(endX, endY);
          }

          ctx.strokeStyle = flare.color;
          ctx.lineWidth = Math.max(0.1, flare.thickness);
          ctx.globalAlpha = flare.opacity * (1 - currentEntropy * 0.3);
          ctx.stroke();
          ctx.globalAlpha = 1;
        }
      });

      animationFrameIdRef.current = requestAnimationFrame(draw);
    };

    animationFrameIdRef.current = requestAnimationFrame(draw);
    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [currentEntropy, styles, seekerTraits, lastRitualOutcome, dimensions]);

  const panelWidth = typeof width === 'number' ? `${width}px` : width;
  const panelHeight = typeof height === 'number' ? `${height}px` : height;

  return (
    <div 
        ref={containerRef}
        className="seeker-aura-display-container bg-slate-950/70 border border-slate-700/50 rounded-lg shadow-xl overflow-hidden mx-auto" 
        style={{ width: panelWidth, height: panelHeight }}
    >
      <canvas 
        ref={canvasRef} 
        aria-label="Seeker's Dual-Tone Aura Visualization"
        role="img"
      />
    </div>
  );
};

export default SeekerAuraDisplay;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Planet } from '../../types'; 

interface CelestialEntropyCyclePanelProps {
  currentEntropy: number;
  width: number | string;
  height: number | string;
}

const MAX_PLANETS = 10;
const MIN_PLANETS = 0;
const BASE_SUN_RADIUS_FACTOR = 0.12; 
const BASE_MOON_RADIUS_FACTOR = 0.09; 

const CelestialEntropyCyclePanel: React.FC<CelestialEntropyCyclePanelProps> = ({
  currentEntropy,
  width,
  height,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameIdRef = useRef<number | null>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  const [numPlanetsSetting, setNumPlanetsSetting] = useState(3);
  const [planetSizeFactorSetting, setPlanetSizeFactorSetting] = useState(1);
  const [planets, setPlanets] = useState<Planet[]>([]);

  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

  // Measure container dimensions
  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const initializePlanets = useCallback(() => {
    const { w, h } = dimensions;
    if (w <= 0 || h <= 0) return;

    const sunX = w / 2;
    const sunY = h / 2;

    const newPlanets: Planet[] = [];
    const maxOrbitRadius = Math.min(sunX, sunY) * 0.85; 

    for (let i = 0; i < numPlanetsSetting; i++) {
      const baseOrbit = maxOrbitRadius * (0.3 + Math.random() * 0.65 * (i + 1) / numPlanetsSetting);
      const entropyOrbitFactor = lerp(1, 0.7 + Math.random() * 0.6, currentEntropy); 

      newPlanets.push({
        id: `planet-${i}-${Date.now()}`,
        orbitRadius: baseOrbit * entropyOrbitFactor,
        currentAngle: Math.random() * Math.PI * 2,
        baseSpeed: (0.001 + Math.random() * 0.003) * (1 / Math.sqrt((i + 1) * 0.5)), 
        baseSize: (Math.random() * 8 + 4) * planetSizeFactorSetting, 
        colorHue: Math.random() * 360,
        textureSeed: Math.random(),
      });
    }
    setPlanets(newPlanets);
  }, [numPlanetsSetting, planetSizeFactorSetting, dimensions, currentEntropy]);

  useEffect(() => {
    initializePlanets();
  }, [initializePlanets]); 

  useEffect(() => {
    const canvas = canvasRef.current;
    const { w, h } = dimensions;
    if (!canvas || w <= 0 || h <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = w;
    canvas.height = h;

    let frameCount = 0;

    const drawSky = (entropy: number) => {
      let skyColor1: string, skyColor2: string;
      const t = clamp(entropy * 1.5, 0, 1); 

      if (entropy < 0.25) { 
        skyColor1 = `hsl(200, 70%, ${lerp(80, 70, t*4)}%)`; 
        skyColor2 = `hsl(50, 80%, ${lerp(90, 80, t*4)}%)`; 
      } else if (entropy < 0.5) { 
        skyColor1 = `hsl(${lerp(30, 270, (t-0.25)*4)}, 60%, ${lerp(60, 40, (t-0.25)*4)}%)`; 
        skyColor2 = `hsl(${lerp(60, 300, (t-0.25)*4)}, 50%, ${lerp(70, 50, (t-0.25)*4)}%)`; 
      } else if (entropy < 0.75) { 
        skyColor1 = `hsl(240, 50%, ${lerp(30, 15, (t-0.5)*4)}%)`; 
        skyColor2 = `hsl(270, 60%, ${lerp(20, 10, (t-0.5)*4)}%)`; 
      } else { 
        skyColor1 = `hsl(${lerp(0, -30, (t-0.75)*4)}, 40%, ${lerp(10, 5, (t-0.75)*4)}%)`;
        skyColor2 = `hsl(240, 30%, ${lerp(8, 3, (t-0.75)*4)}%)`; 
      }

      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, skyColor1);
      gradient.addColorStop(1, skyColor2);
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      if (entropy > 0.6) {
        const numStars = Math.floor(lerp(0, 150 + entropy * 100, (entropy - 0.6) / 0.4));
        for (let i = 0; i < numStars; i++) {
          const x = Math.random() * w;
          const y = Math.random() * h * 0.8; 
          const size = Math.random() * 1.5 + 0.5;
          const opacity = Math.random() * 0.5 + 0.3 * clamp((entropy - 0.6) / 0.4, 0, 1) * (1 + Math.sin(Date.now() * 0.0005 + i) * 0.3 * entropy); 
          ctx.fillStyle = `rgba(255, 255, 220, ${clamp(opacity,0,1)})`;
          ctx.beginPath();
          ctx.arc(x, y, size, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    };

    const drawSun = (entropy: number, sunX: number, sunY: number) => {
      const sunRadius = Math.max(0, Math.min(w, h) * BASE_SUN_RADIUS_FACTOR);
      const sunHue = lerp(50, 0, entropy); 
      const sunSaturation = lerp(100, 60, entropy);
      const sunLightness = lerp(70, 30, entropy); 
      const sunAlpha = lerp(1, 0.7, entropy);
      const corePulse = Math.sin(Date.now() * 0.0005) * 0.1 * entropy;

      const calculatedGlowRadius = sunRadius * lerp(1.8, 1.2 + corePulse, entropy);
      const r0_sunGlow = Math.max(0, sunRadius * (0.7 + corePulse * 0.5));
      const r1_sunGlow = Math.max(r0_sunGlow, calculatedGlowRadius);

      if (Number.isFinite(sunX) && Number.isFinite(sunY) && Number.isFinite(r0_sunGlow) && Number.isFinite(r1_sunGlow) && r1_sunGlow > 0) {
        const sunGlow = ctx.createRadialGradient(sunX, sunY, r0_sunGlow, sunX, sunY, r1_sunGlow);
        sunGlow.addColorStop(0, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness + 10}%, ${sunAlpha * 0.8})`);
        sunGlow.addColorStop(0.5, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness}%, ${sunAlpha * 0.4})`);
        sunGlow.addColorStop(1, `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness - 10}%, 0)`);
        ctx.fillStyle = sunGlow;
        ctx.beginPath();
        ctx.arc(sunX, sunY, Math.max(0, r1_sunGlow), 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = `hsla(${sunHue}, ${sunSaturation}%, ${sunLightness}%, ${sunAlpha})`;
      ctx.beginPath();
      ctx.arc(sunX, sunY, Math.max(0, sunRadius * (1 + corePulse * 0.3)), 0, Math.PI * 2);
      ctx.fill();

      const numRays = 12;
      for (let i = 0; i < numRays; i++) {
        const angle = (i / numRays) * Math.PI * 2 + Date.now() * 0.00001 * entropy; 
        const rayLength = sunRadius * lerp(0.8, 0.3, entropy);
        const rayWidth = lerp(5, 2, entropy) * (1 + Math.sin(Date.now()*0.001 + i*0.5) * 0.15 * entropy); 

        const startX = sunX + Math.cos(angle) * sunRadius * (1 + corePulse * 0.3);
        const startY = sunY + Math.sin(angle) * sunRadius * (1 + corePulse * 0.3);
        const endX = sunX + Math.cos(angle) * (sunRadius * (1 + corePulse * 0.3) + rayLength + (entropy > 0.7 ? (Math.random()-0.5)*rayLength*0.6 : 0) );
        const endY = sunY + Math.sin(angle) * (sunRadius * (1 + corePulse * 0.3) + rayLength + (entropy > 0.7 ? (Math.random()-0.5)*rayLength*0.6 : 0) );

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.strokeStyle = `hsla(${sunHue}, ${sunSaturation - 10}%, ${sunLightness + 15}%, ${sunAlpha * lerp(0.6, 0.2, entropy)})`;
        ctx.lineWidth = rayWidth;
        ctx.stroke();
      }
    };

    const drawMoon = (entropy: number) => {
      const moonRadius = Math.max(0, Math.min(w, h) * BASE_MOON_RADIUS_FACTOR);
      const moonOrbitRadius = Math.min(w, h) * 0.35;
      const moonOrbitAngle = Date.now() * 0.0001; 
      const moonX = w / 2 + Math.cos(moonOrbitAngle) * moonOrbitRadius;
      const moonY = h / 2 + Math.sin(moonOrbitAngle) * moonOrbitRadius;

      const phase = entropy; 
      const moonHue = lerp(200, entropy > 0.8 ? 0 : 45, entropy); 
      const moonSaturation = lerp(20, 50 + entropy * 30 , entropy);
      const moonLightness = lerp(80, 50 - entropy * 20, entropy);
      const moonAlpha = lerp(0.4, 0.9, entropy);

      ctx.save();
      ctx.fillStyle = `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness}%, ${moonAlpha})`;
      ctx.beginPath();
      ctx.arc(moonX, moonY, moonRadius, 0, Math.PI * 2);
      ctx.fill();

      if (phase < 1) { 
          ctx.fillStyle = `hsla(${moonHue}, ${moonSaturation-10}%, ${moonLightness - 30}%, ${moonAlpha * 0.9})`; 
          ctx.beginPath();
          const shadowAngleOffset = Math.PI * (1 - phase); 
          ctx.arc(moonX, moonY, moonRadius + 0.5, Math.PI/2 - shadowAngleOffset, Math.PI/2 + shadowAngleOffset, true); 
          ctx.arc(moonX + Math.cos(Math.PI/2 + shadowAngleOffset) * moonRadius *0.1 , moonY +  Math.sin(Math.PI/2 + shadowAngleOffset) * moonRadius*0.1, moonRadius, Math.PI/2 + shadowAngleOffset, Math.PI/2 - shadowAngleOffset, false); 

          ctx.closePath();
          ctx.fill();
      }

      const r0_moonGlow = Math.max(0, moonRadius * 0.8);
      const r1_moonGlow = Math.max(r0_moonGlow, moonRadius * 1.5);
      if (Number.isFinite(moonX) && Number.isFinite(moonY) && Number.isFinite(r0_moonGlow) && Number.isFinite(r1_moonGlow) && r1_moonGlow > 0) {
        const moonGlow = ctx.createRadialGradient(moonX, moonY, r0_moonGlow, moonX, moonY, r1_moonGlow);
        moonGlow.addColorStop(0, `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness + 10}%, ${moonAlpha * 0.3})`);
        moonGlow.addColorStop(1, `hsla(${moonHue}, ${moonSaturation}%, ${moonLightness}%, 0)`);
        ctx.fillStyle = moonGlow;
        ctx.beginPath();
        ctx.arc(moonX, moonY, r1_moonGlow, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    };

    const drawPlanets = (entropy: number, sunX: number, sunY: number) => {
      planets.forEach(p => {
        p.currentAngle = (p.currentAngle + p.baseSpeed * lerp(1, 1 + (Math.random()-0.5)*2*entropy, entropy)) % (Math.PI * 2);
        p.effectiveSize = Math.max(0, p.baseSize * planetSizeFactorSetting * lerp(1.2, 0.5 + Math.random()*0.7, entropy));
        p.effectiveOpacity = lerp(0.9, 0.4 + Math.random()*0.5, entropy);
        p.wobbleX = Math.sin(Date.now() * 0.0002 * (p.id.charCodeAt(7)%5 +1)) * entropy * p.effectiveSize * 0.3;
        p.wobbleY = Math.cos(Date.now() * 0.00015 * (p.id.charCodeAt(8)%5 +1)) * entropy * p.effectiveSize * 0.3;
        p.isUnstable = entropy > 0.7 && Math.random() < entropy * 0.1; 

        if (p.isUnstable && Math.random() < 0.5) return; 

        const x = sunX + Math.cos(p.currentAngle) * p.orbitRadius + p.wobbleX;
        const y = sunY + Math.sin(p.currentAngle) * p.orbitRadius + p.wobbleY;

        const planetLightness = lerp(60, 30 + Math.random()*20, entropy);
        const planetSaturation = lerp(70, 40 + Math.random()*30, entropy);

        ctx.fillStyle = `hsla(${p.colorHue}, ${planetSaturation}%, ${planetLightness}%, ${p.effectiveOpacity})`;
        ctx.beginPath();
        ctx.arc(x, y, Math.max(1, p.effectiveSize), 0, Math.PI * 2);
        ctx.fill();

        if (entropy > 0.8 && p.effectiveSize > 3) {
            const numFragments = Math.floor(Math.random() * 3) + 2;
            for(let i=0; i < numFragments; i++) {
                const fragX = x + (Math.random() - 0.5) * p.effectiveSize * 0.8;
                const fragY = y + (Math.random() - 0.5) * p.effectiveSize * 0.8;
                const fragSize = p.effectiveSize * (Math.random() * 0.3 + 0.2);
                ctx.fillStyle = `hsla(${p.colorHue + (Math.random()-0.5)*40}, ${planetSaturation-10}%, ${planetLightness-10}%, ${p.effectiveOpacity * 0.7})`;
                ctx.beginPath();
                ctx.arc(fragX, fragY, Math.max(0.5, fragSize), 0, Math.PI * 2);
                ctx.fill();
            }
        }

        if (p.effectiveSize > 2) {
            const r0_atmos = Math.max(0, p.effectiveSize * 0.8);
            const r1_atmos = Math.max(r0_atmos, p.effectiveSize * 1.5);
            if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(r0_atmos) && Number.isFinite(r1_atmos) && r1_atmos > 0) {
              const atmosGrad = ctx.createRadialGradient(x,y, r0_atmos, x,y, r1_atmos);
              atmosGrad.addColorStop(0, `hsla(${p.colorHue + 20}, ${planetSaturation + 10}%, ${planetLightness + 10}%, ${p.effectiveOpacity * 0.3 * (1-entropy)})`);
              atmosGrad.addColorStop(1, `hsla(${p.colorHue + 40}, ${planetSaturation}%, ${planetLightness}%, 0)`);
              ctx.fillStyle = atmosGrad;
              ctx.beginPath();
              ctx.arc(x,y, r1_atmos, 0, Math.PI*2);
              ctx.fill();
            }
        }
      });
    };

    const render = () => {
      frameCount++;
      drawSky(currentEntropy);
      drawSun(currentEntropy, w/2, h/2);
      drawMoon(currentEntropy); 
      drawPlanets(currentEntropy, w/2, h/2);
      animationFrameIdRef.current = requestAnimationFrame(render);
    };

    animationFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [currentEntropy, dimensions, planets, planetSizeFactorSetting]);

  const handleNumPlanetsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setNumPlanetsSetting(Number(event.target.value));
  };

  const handlePlanetSizeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setPlanetSizeFactorSetting(Number(event.target.value));
  };

  const panelWidth = typeof width === 'number' ? `${width}px` : width;
  const panelHeight = typeof height === 'number' ? `${height}px` : height;

  return (
    <div ref={containerRef} className="celestial-entropy-cycle-panel bg-slate-950/80 backdrop-blur-md border border-yellow-500/30 rounded-xl shadow-2xl p-6 my-8 text-slate-100" style={{ width: panelWidth }}>
      <h2 className="text-2xl font-['Cinzel'] font-bold mb-4 text-center text-yellow-200 drop-shadow-[0_1px_1px_rgba(255,255,200,0.4)]">
        Celestial Entropy Resonator
      </h2>
      <div className="relative mx-auto mb-6" style={{ width: '100%', height: panelHeight }}>
        <canvas
          ref={canvasRef}
          className="rounded-lg border border-slate-700/30"
          aria-label="Sun, Moon, and Planets simulation based on entropy"
          role="img"
        />
      </div>
      <div className="controls-area grid grid-cols-1 md:grid-cols-3 gap-4 p-4 bg-slate-800/50 rounded-lg border border-slate-700">
        <div>
          <label htmlFor="numPlanets" className="block text-xs font-medium text-slate-300 mb-1">Number of Planets: {numPlanetsSetting}</label>
          <input
            type="range"
            id="numPlanets"
            min={MIN_PLANETS}
            max={MAX_PLANETS}
            value={numPlanetsSetting}
            onChange={handleNumPlanetsChange}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-yellow-500"
            aria-label="Number of planets"
          />
        </div>
        <div>
          <label htmlFor="planetSize" className="block text-xs font-medium text-slate-300 mb-1">Planet Size Factor: {planetSizeFactorSetting.toFixed(1)}x</label>
          <input
            type="range"
            id="planetSize"
            min="0.2"
            max="2.5"
            step="0.1"
            value={planetSizeFactorSetting}
            onChange={handlePlanetSizeChange}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-yellow-500"
            aria-label="Planet size factor"
          />
        </div>
        <div className="flex items-end">
          <button
            onClick={initializePlanets}
            className="w-full px-4 py-2 text-sm rounded-button bg-yellow-600 hover:bg-yellow-500 text-slate-900 font-semibold transition-colors focus:ring-2 focus:ring-yellow-400 focus:outline-none"
            aria-label="Randomize planetary system"
          >
            <i className="ri-refresh-line mr-2"></i>Randomize System
          </button>
        </div>
      </div>
    </div>
  );
};

export default CelestialEntropyCyclePanel;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import type { CrystalGrowth } from '../../types'; 

interface CrystalFormationPanelProps {
  width: number | string;
  height: number | string;
  currentEntropy: number;
}

const NUM_CRYSTALS = 7; 
const MAX_AGE_BASE = 5000; 
const MAX_AGE_VARIANCE = 3000;

const CrystalFormationPanel: React.FC<CrystalFormationPanelProps> = ({ width, height, currentEntropy }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [crystals, setCrystals] = useState<CrystalGrowth[]>([]);
  const animationFrameIdRef = useRef<number | null>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  // Measure container dimensions
  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const initializeCrystal = useCallback((idSuffix: string | number, canvasWidth: number, canvasHeight: number, entropy: number): CrystalGrowth => {
    const t = Math.min(1, Math.max(0, entropy)); 
    return {
      id: `crystal-${idSuffix}-${Date.now()}`,
      x: Math.random() * canvasWidth,
      y: Math.random() * canvasHeight * 0.3 + canvasHeight * 0.6, 
      baseHue: Math.random() * 360,
      maxSize: (Math.random() * (Math.min(canvasWidth, canvasHeight) * 0.15) + (Math.min(canvasWidth, canvasHeight) * 0.05)) * (1 - t * 0.3), 
      currentSize: 0,
      growthSpeed: (Math.random() * 0.1 + 0.05) * (1 + t * 0.5), 
      rotation: Math.random() * Math.PI * 2,
      rotationSpeed: (Math.random() - 0.5) * 0.002 * (1 + t * 2), 
      numSpokes: Math.floor(Math.random() * (5 - t*2)) + (5 - Math.floor(t*2)), 
      spokeLengthVariance: (Math.random() * 0.4 + 0.8) * (1 + t*0.3), 
      spokeWidth: (Math.random() * 3 + 2) * (1 - t*0.5), 
      opacity: 0,
      targetOpacity: (Math.random() * 0.4 + 0.5) * (1 - t*0.4), 
      lifeCycle: 'growing',
      age: 0,
      maxAge: (MAX_AGE_BASE + Math.random() * MAX_AGE_VARIANCE) * (1 - t*0.7), 
    };
  }, []);

  useEffect(() => {
    const { w, h } = dimensions;
    if (w > 0 && h > 0) {
      const initialCrystals = Array.from({ length: NUM_CRYSTALS }, (_, i) =>
        initializeCrystal(i, w, h, currentEntropy)
      );
      setCrystals(initialCrystals);
    }
  }, [dimensions, initializeCrystal, currentEntropy]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const { w, h } = dimensions;
    if (!canvas || crystals.length === 0 || w <= 0 || h <= 0) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = w;
    canvas.height = h;

    let frameCount = 0;

    const draw = () => {
      frameCount++;
      if (!canvasRef.current) return;
      ctx.clearRect(0, 0, w, h);
      const t_entropy = Math.min(1, Math.max(0, currentEntropy));

      const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
      bgGrad.addColorStop(0, `rgba(${Math.round(20 - t_entropy*10)}, ${Math.round(15 - t_entropy*10)}, ${Math.round(40 - t_entropy*20)}, 0.2)`);
      bgGrad.addColorStop(1, `rgba(${Math.round(40 - t_entropy*20)}, ${Math.round(25 - t_entropy*15)}, ${Math.round(80 - t_entropy*30)}, 0.5)`);
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0,0,w,h);

      crystals.forEach((crystal, index) => {
        crystal.age++;
        const crystalEntropyFactor = Math.min(1, Math.max(0, currentEntropy + (Math.sin(frameCount * 0.01 + index) * 0.1)));

        if (crystal.lifeCycle === 'growing') {
          crystal.currentSize = Math.min(crystal.maxSize, crystal.currentSize + crystal.growthSpeed * (1 - crystalEntropyFactor * 0.5));
          crystal.opacity = Math.min(crystal.targetOpacity, crystal.opacity + 0.01);
          if (crystal.currentSize >= crystal.maxSize && crystal.opacity >= crystal.targetOpacity) {
            crystal.lifeCycle = 'stable';
            crystal.age = 0; 
          }
        } else if (crystal.lifeCycle === 'stable') {
          if (crystal.age > crystal.maxAge * (1 - crystalEntropyFactor * 0.5) ) {
            crystal.lifeCycle = 'fading';
            crystal.age = 0; 
          }
        } else if (crystal.lifeCycle === 'fading') {
          crystal.opacity = Math.max(0, crystal.opacity - (0.005 + crystalEntropyFactor * 0.01));
          crystal.currentSize = Math.max(0, crystal.currentSize - crystal.growthSpeed * 0.2);
          if (crystal.opacity <= 0) {
            crystals[index] = initializeCrystal(crystal.id.split('-')[1], w, h, currentEntropy);
            return; 
          }
        }

        crystal.rotation += crystal.rotationSpeed * (1 + crystalEntropyFactor * 2);

        ctx.save();
        ctx.translate(crystal.x, crystal.y);
        ctx.rotate(crystal.rotation);

        const numSpokes = Math.max(3, crystal.numSpokes - Math.floor(crystalEntropyFactor * 2));
        for (let i = 0; i < numSpokes; i++) {
          const angle = (i / numSpokes) * Math.PI * 2 + (crystalEntropyFactor > 0.6 ? (Math.random()-0.5)*0.2 : 0) ;
          const spokeLength = crystal.currentSize * (crystal.spokeLengthVariance - (Math.random() * 0.2 * crystal.spokeLengthVariance)) * (1 - crystalEntropyFactor*0.3);

          const endX = Math.cos(angle) * spokeLength;
          const endY = Math.sin(angle) * spokeLength;

          const baseLightness = 50 - crystalEntropyFactor * 15;
          const facetLightness = baseLightness + (i % 2 === 0 ? 15 : -10) + Math.random() * 10; 
          const saturation = 70 + Math.random()*20 - crystalEntropyFactor * 20;

          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.lineTo(Math.cos(angle - 0.1) * spokeLength * 0.5, Math.sin(angle - 0.1) * spokeLength * 0.5);
          ctx.lineTo(endX, endY);
          ctx.lineTo(Math.cos(angle + 0.1) * spokeLength * 0.5, Math.sin(angle + 0.1) * spokeLength * 0.5);
          ctx.closePath();

          const grad = ctx.createLinearGradient(0,0, endX, endY);
          grad.addColorStop(0, `hsla(${crystal.baseHue + crystalEntropyFactor * 30}, ${saturation}%, ${facetLightness + 10}%, ${crystal.opacity * 0.7})`);
          grad.addColorStop(0.7, `hsla(${crystal.baseHue + 20 + crystalEntropyFactor * 30}, ${saturation}%, ${facetLightness}%, ${crystal.opacity * 0.5})`);
          grad.addColorStop(1, `hsla(${crystal.baseHue + 40 + crystalEntropyFactor * 30}, ${saturation}%, ${facetLightness - 10}%, ${crystal.opacity * 0.3})`);
          ctx.fillStyle = grad;
          if (crystalEntropyFactor > 0.85 && Math.random() < 0.1) continue;
          ctx.fill();

          ctx.beginPath();
          ctx.moveTo(0,0);
          ctx.lineTo(endX, endY);
          ctx.strokeStyle = `hsla(${crystal.baseHue + crystalEntropyFactor * 30}, ${saturation + 20}%, ${facetLightness + 25}%, ${crystal.opacity * 0.8})`;
          ctx.lineWidth = Math.max(0.5, crystal.spokeWidth * 0.2 * (1 - crystalEntropyFactor * 0.7));
          if (crystalEntropyFactor > 0.8 && Math.random() < 0.2) {
            ctx.setLineDash([2 + Math.random()*3, 2+Math.random()*2]);
            ctx.stroke();
            ctx.setLineDash([]);
          } else {
            ctx.stroke();
          }
        }

        const coreR = crystal.currentSize * 0.2;
        if (Number.isFinite(coreR) && coreR > 0) {
          const coreGrad = ctx.createRadialGradient(0,0,0, 0,0, coreR);
          coreGrad.addColorStop(0, `hsla(${crystal.baseHue + crystalEntropyFactor * 30}, 90%, ${85 - crystalEntropyFactor*20}%, ${crystal.opacity * 0.5})`);
          coreGrad.addColorStop(1, `hsla(${crystal.baseHue + crystalEntropyFactor * 30}, 90%, ${70 - crystalEntropyFactor*20}%, 0)`);
          ctx.fillStyle = coreGrad;
          ctx.beginPath();
          ctx.arc(0,0, coreR, 0, Math.PI * 2);
          ctx.fill();
        }

        ctx.restore();
      });

      animationFrameIdRef.current = requestAnimationFrame(draw);
    };

    animationFrameIdRef.current = requestAnimationFrame(draw);
    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [crystals, currentEntropy, dimensions, initializeCrystal]);

  const panelWidth = typeof width === 'number' ? `${width}px` : width;
  const panelHeight = typeof height === 'number' ? `${height}px` : height;

  return (
    <div ref={containerRef} className="crystal-formation-panel bg-slate-900/90 backdrop-blur-sm border border-purple-500/50 rounded-xl shadow-2xl p-6 my-8 text-slate-100" style={{ width: panelWidth }}>
        <h2 className="text-2xl font-['Cinzel'] font-bold mb-4 text-center text-purple-300 drop-shadow-[0_1px_1px_rgba(220,180,255,0.4)]">
            Prime Resonator JuJu's Crystal Garden
        </h2>
        <div className="relative mx-auto" style={{ width: '100%', height: panelHeight }}>
            <canvas 
                ref={canvasRef}
                className="rounded-lg border border-purple-700/30"
                aria-label="Animated crystal formations reacting to entropy"
                role="img"
            />
        </div>
    </div>
  );
};

