const stringToSeed = (str: string): number => {
  let hash = 0;
  if (!str || str.length === 0) return Math.random();
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0; 
  }
  return (hash & 0x7fffffff) / 0x7fffffff;
};

