        ctx.fillText(`Abstract ${artMode} visualization.`, centerX, centerY);
    }
  }, [dimensions, artMode, lambdaValue, negentropyLevel, currentEntropy]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || dimensions.w <= 0 || dimensions.h <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let frameId: number;
    let frameCount = 0;
    const renderLoop = () => {
      frameCount++;
      drawArt(ctx, frameCount);
      frameId = requestAnimationFrame(renderLoop);
    };
    frameId = requestAnimationFrame(renderLoop);
    return () => cancelAnimationFrame(frameId);
  }, [drawArt, dimensions]);

  const panelWidth = typeof width === 'number' ? `${width}px` : width;

  return (
    <div ref={containerRef} className="codex-dream-panel bg-slate-950/90 backdrop-blur-md border border-purple-600/50 rounded-xl shadow-2xl p-4 text-slate-100 flex flex-col relative z-20" style={{ width: panelWidth, minHeight: height }}>
      <h3 className="text-lg font-cinzel font-bold text-purple-300 mb-2 text-center">✦ Codex Dream Panel ✦</h3>
      <ModeSelectorAny currentMode={artMode} onSetMode={setArtMode} availableModes={ART_MODES} />
      <canvas ref={canvasRef} width={dimensions.w} height={dimensions.h} className="w-full rounded-md border border-slate-700/70 bg-black mb-1" style={{ height: `${dimensions.h}px` }} />
      <div className="flex gap-1 my-1">
        <input type="text" value={seekerInput} onChange={(e) => setSeekerInput(e.target.value)} placeholder="Whisper a seed..." className="flex-grow p-1.5 text-[10px] bg-slate-700 border-slate-600 rounded-md text-white" />
        <Button onClick={handleReseed} className="px-3 py-1.5 text-[10px] bg-purple-600">Reseed</Button>
      </div>
      <Button onClick={handleCapture} className="w-full text-xs py-2 bg-cyan-600">CAPTURE DREAMPRINT</Button>
    </div>
  );
};

