  [7, 15], [8, 9], [8, 10], [8, 12], [9, 11], [9, 13], [10, 11], [10, 14],
  [11, 15], [12, 13], [12, 14], [13, 15], [14, 15]
];

interface CommonDrawParams {
  ctx: CanvasRenderingContext2D;
  projected3DVertices: number[][]; 
  colors: number[][]; 
  temporalFactor: number; 
  perspectiveScale: number;
  axiomField: { strength: number; warpType: string; };
  deltaPhase: number; 
  frameCount: number;
  width: number;
  height: number;
  effectiveEntropy: number; 
  timeDilation: number; 
  projectTo2D: (v3D: number[], perspectiveScale: number) => number[];
  particlesRef: React.MutableRefObject<Particle[]>;
  drawFractalBranch: (
    ctx: CanvasRenderingContext2D, x: number, y: number, angle: number, length: number, depth: number, maxDepth: number, color: string
  ) => void;
  resonanceTuning: number; 
}

const VisualizationMatrixPanel: React.FC<ExternalProps> = ({
  width: propWidth = 600, 
  height: propHeight = 600
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  const { 
    currentMode, 
    resonanceTuning, 
    timeDilation, 
    effectiveEntropy, 
    panelStateSetters 
  } = usePanelState(); 
  const particlesRef = useRef<Particle[]>([]);

  const axiomPulser = useMemo(() => new AxiomPulseEngine(), []);
  const tesseractRenderer = useMemo(() => new TesseractRenderer(), []);

  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
      const { width: w, height: h } = entries[0].contentRect;
      setDimensions({ w, h });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const canvasSize = useMemo(() => {
    if (dimensions.w > 0 && dimensions.h > 0) {
      return Math.min(dimensions.w, dimensions.h);
    }
    // Fallback if width/height props are numeric, else a default
    const numW = typeof propWidth === 'number' ? propWidth : 300;
    const numH = typeof propHeight === 'number' ? propHeight : 300;
    return Math.min(numW, numH);
  }, [dimensions, propWidth, propHeight]);

  useEffect(() => {
    axiomPulser.setResonanceLevel(resonanceTuning);
  }, [resonanceTuning, axiomPulser]);

  const handleModeChange = (newMode: VisualizationMatrixMode) => {
    panelStateSetters.setCurrentMode(newMode);
    particlesRef.current = []; 
  };

  const projectTo2D = useCallback((v3D: number[], currentPerspectiveScale: number) => {
    const z_offset = 3 + effectiveEntropy * 1.5; 
    const perspectiveDivisor = z_offset - v3D[2];
    const pFactor = perspectiveDivisor !== 0 ? currentPerspectiveScale / perspectiveDivisor : currentPerspectiveScale * 1000; 
    return [
      canvasSize / 2 + v3D[0] * pFactor,
      canvasSize / 2 + v3D[1] * pFactor
    ];
  }, [canvasSize, effectiveEntropy]);

  const drawFractalBranch = useCallback((
    ctx: CanvasRenderingContext2D,
    x: number, y: number, angle: number, length: number, depth: number, maxDepth: number, color: string
  ) => {
    if (depth > maxDepth || length < (1 - effectiveEntropy * 0.8)) return;
    const endX = x + Math.cos(angle) * length;
    const endY = y + Math.sin(angle) * length;
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(endX) || !Number.isFinite(endY)) return;

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(endX, endY);
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(0.3, (maxDepth - depth + 1) * 0.3 * (1 - effectiveEntropy * 0.7 + Math.random() * effectiveEntropy * 0.4));
    ctx.stroke();

    const branches = 2 + Math.floor(effectiveEntropy * 3);
    const angleSpread = (Math.PI / (2.5 + depth - effectiveEntropy)) * (1 + effectiveEntropy * 0.8);
    for (let i = 0; i < branches; i++) {
        drawFractalBranch(ctx, endX, endY, angle + (i - (branches - 1) / 2) * angleSpread * (1 + (Math.random()-0.5)*effectiveEntropy*0.5), length * (0.6 - effectiveEntropy * 0.2), depth + 1, maxDepth, color);
    }
  }, [effectiveEntropy]);

  const drawSacredLattice = useCallback((params: CommonDrawParams) => {
    const { ctx, projected3DVertices, colors, perspectiveScale, axiomField, deltaPhase, effectiveEntropy, projectTo2D } = params;
    ctx.lineWidth = 0.5 + effectiveEntropy * 1.5 + Math.sin(deltaPhase*0.5) * effectiveEntropy * 0.5;
    TESSERACT_EDGES.forEach(([i1, i2]) => {
      const v1 = projected3DVertices[i1]; const v2 = projected3DVertices[i2];
      if (!v1 || !v2) return;
      const [x1, y1] = projectTo2D(v1, perspectiveScale); 
      const [x2, y2] = projectTo2D(v2, perspectiveScale);
      if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) return;
      const color = colors[i1];
      const alpha = Math.max(0.05, (color[3] !== undefined ? color[3] : 1) * (1 - effectiveEntropy * 0.8) * (0.4 + axiomField.strength * 0.6) * (0.4 + params.temporalFactor * 0.6));
      const hue = (200 + axiomField.strength * 60 + effectiveEntropy * 90) % 360;
      ctx.strokeStyle = `hsla(${hue}, 70%, ${60 + effectiveEntropy * 15}%, ${alpha})`;
      ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    });
  }, [projectTo2D]); 

  const drawDimensionalBloom = useCallback((params: CommonDrawParams) => {
    const { ctx, projected3DVertices, colors, perspectiveScale, axiomField, deltaPhase, effectiveEntropy, projectTo2D } = params;
    projected3DVertices.forEach((v3D, i) => {
      const [px, py] = projectTo2D(v3D, perspectiveScale);
      if (!Number.isFinite(px) || !Number.isFinite(py)) return;
      const pulseSize = (3 + effectiveEntropy * 7 + Math.sin(deltaPhase * (2 + effectiveEntropy*2) + i * 0.5) * (2 + effectiveEntropy*4)) * (1 + axiomField.strength*0.5) ;
      ctx.beginPath();
      ctx.arc(px, py, Math.max(0.1, pulseSize), 0, Math.PI * 2);
      const hue = (colors[i][0] * 120 + effectiveEntropy * 90) % 360; 
      ctx.fillStyle = `hsla(${hue}, ${80 + effectiveEntropy*10}%, ${65 + effectiveEntropy*10}%, ${0.4 + params.temporalFactor * 0.4 - effectiveEntropy*0.1})`;
      ctx.fill();
    });
  }, [projectTo2D]);

  const drawEntropyPulse = useCallback((params: CommonDrawParams) => {
    const { ctx, projected3DVertices, perspectiveScale, deltaPhase, effectiveEntropy, projectTo2D, frameCount } = params;
    ctx.lineWidth = 0.5 + effectiveEntropy * 6;
    TESSERACT_EDGES.forEach(([i1, i2]) => {
      const v1 = projected3DVertices[i1];
      const v2 = projected3DVertices[i2];
      if (!v1 || !v2) return;
      const jitterX1 = (Math.random() - 0.5) * effectiveEntropy * 15;
      const jitterY1 = (Math.random() - 0.5) * effectiveEntropy * 15;
      const jitterX2 = (Math.random() - 0.5) * effectiveEntropy * 15;
      const jitterY2 = (Math.random() - 0.5) * effectiveEntropy * 15;
      const [x1, y1] = projectTo2D(v1, perspectiveScale * (1 + Math.sin(deltaPhase + i1*0.2) * effectiveEntropy * 0.3));
      const [x2, y2] = projectTo2D(v2, perspectiveScale * (1 + Math.sin(deltaPhase + i2*0.2) * effectiveEntropy * 0.3));
      if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) return;
      const hue = (frameCount*2 + effectiveEntropy * 360 + Math.sin(deltaPhase + i1*0.5)*60) % 360;
      const alpha = Math.max(0.05, 0.9 - effectiveEntropy * 0.8 + Math.random()*effectiveEntropy*0.2);
      ctx.strokeStyle = `hsla(${hue}, 95%, ${60 + Math.random()*20}%, ${alpha})`;
      ctx.beginPath(); ctx.moveTo(x1 + jitterX1, y1 + jitterY1); ctx.lineTo(x2 + jitterX2, y2 + jitterY2); ctx.stroke();
    });
  }, [projectTo2D]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || canvasSize <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = canvasSize;
    canvas.height = canvasSize;

    let frameId: number;
    let frameCount = 0;

    const renderLoop = () => {
      frameCount++;
      const deltaPhase = frameCount * 0.01 * timeDilation * (1 + effectiveEntropy * 0.5); 
      const { vertices: projected3DVertices, colors, temporalFactor } = tesseractRenderer.render(deltaPhase);
      const axiomField = axiomPulser.getActiveAxiomField();

      ctx.fillStyle = 'rgb(15, 23, 42)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const currentPerspectiveScale = canvasSize * 0.45;

      const commonDrawParams: CommonDrawParams = {
        ctx, projected3DVertices, colors, temporalFactor, perspectiveScale: currentPerspectiveScale, axiomField, deltaPhase, frameCount,
        width: canvas.width, height: canvas.height, effectiveEntropy, timeDilation, projectTo2D, particlesRef, drawFractalBranch, resonanceTuning
      };

      if (currentMode === VisualizationMatrixMode.SacredLattice) drawSacredLattice(commonDrawParams);
      else if (currentMode === VisualizationMatrixMode.DimensionalBloom) drawDimensionalBloom(commonDrawParams);
      else if (currentMode === VisualizationMatrixMode.EntropyPulse) drawEntropyPulse(commonDrawParams);
      else drawSacredLattice(commonDrawParams);

      frameId = requestAnimationFrame(renderLoop);
    };

    frameId = requestAnimationFrame(renderLoop);
    return () => cancelAnimationFrame(frameId);
  }, [tesseractRenderer, axiomPulser, timeDilation, effectiveEntropy, currentMode, canvasSize, projectTo2D, drawFractalBranch, resonanceTuning, drawSacredLattice, drawDimensionalBloom, drawEntropyPulse]);

  return (
    <div ref={containerRef} className="visualization-matrix-panel bg-slate-950/90 backdrop-blur-md border border-indigo-600/50 rounded-xl shadow-2xl p-4 md:p-6 my-6 text-slate-100 flex flex-col">
       <div className="flex flex-col sm:flex-row justify-between items-center mb-4 gap-3">
        <h2 className="text-xl md:text-2xl font-cinzel font-bold text-indigo-300 drop-shadow-[0_1px_1px_rgba(129,140,248,0.4)]">
          Visualization Matrix Δ
        </h2>
        <div className="w-full sm:w-auto">
          <ModeSelector<VisualizationMatrixMode> 
            currentMode={currentMode} 
            onSetMode={handleModeChange}
            availableModes={[VisualizationMatrixMode.SacredLattice, VisualizationMatrixMode.DimensionalBloom, VisualizationMatrixMode.EntropyPulse]} 
          />
        </div>
      </div>
      <div className="canvas-outer-wrapper mx-auto flex items-center justify-center bg-black border border-slate-700 rounded-md overflow-hidden" style={{ width: canvasSize, height: canvasSize }}>
        <canvas ref={canvasRef} className="block" />
      </div>
       <div className="mt-3 text-center text-xs text-slate-400 font-mono">
        Mode: {currentMode} | Entropy: {effectiveEntropy.toFixed(3)}δ | Resonance: {resonanceTuning.toFixed(2)} | Time: {timeDilation.toFixed(1)}x
      </div>
    </div>
  );
};

export default VisualizationMatrixPanel;

import React, { useRef, useEffect, useState, useCallback } from 'react';
import * as THREE from 'three';
import { AgentName, HistoricalEventType, type CelestialAnomalyWeaverPanelProps, type HistoricalCelestialAnomalyEventData } from '../../types';
import { AGENT_PROFILES } from '../../constants';
import { Button } from '../ui/Button';

const STAR_RADIUS = 5;
const PLANET_C_RADIUS = 2.5; 
const SIBLING_PLANET_RADIUS = 1.5;
const ORBIT_SEGMENTS = 128;

const CelestialAnomalyWeaverPanel: React.FC<CelestialAnomalyWeaverPanelProps> = ({
  width: propWidth,
  height: propHeight,
  addEchoMessage,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const mountRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const animationFrameIdRef = useRef<number | null>(null);

  const planetCRef = useRef<THREE.Mesh | null>(null);
  const siblingPlanetRef = useRef<THREE.Mesh | null>(null);
  const starRef = useRef<THREE.Mesh | null>(null);

  const [showMythicGlyphs, setShowMythicGlyphs] = useState(false);

  useEffect(() => {
    const currentMount = mountRef.current;
    if (!currentMount) return;

    const w = currentMount.clientWidth || 300;
    const h = currentMount.clientHeight || 300;

    const scene = new THREE.Scene();
    sceneRef.current = scene;
    const camera = new THREE.PerspectiveCamera(75, w / h, 0.1, 1000);
    cameraRef.current = camera;
    camera.position.set(0, 15, 35);
    camera.lookAt(new THREE.Vector3(0,0,0));

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    rendererRef.current = renderer;
    renderer.setSize(w, h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    currentMount.appendChild(renderer.domElement);

    scene.add(new THREE.AmbientLight(0x404060, 1));
    const pointLight = new THREE.PointLight(0xffffff, 2, 200);
    pointLight.position.set(0, 10, 10);
    scene.add(pointLight);

    const star = new THREE.Mesh(
      new THREE.SphereGeometry(STAR_RADIUS, 32, 32),
      new THREE.MeshPhongMaterial({ color: 0xffccaa, emissive: 0xffaa88, emissiveIntensity: 0.6, shininess: 50 })
    );
    starRef.current = star;
    scene.add(star);

    const planetC = new THREE.Mesh(
      new THREE.SphereGeometry(PLANET_C_RADIUS, 32, 32),
      new THREE.MeshPhongMaterial({ color: 0x6080a0, shininess: 20 })
    );
    planetCRef.current = planetC;
    scene.add(planetC);

    const siblingPlanet = new THREE.Mesh(
      new THREE.SphereGeometry(SIBLING_PLANET_RADIUS, 32, 32),
      new THREE.MeshPhongMaterial({ color: 0xa0a080 })
    );
    siblingPlanetRef.current = siblingPlanet;
    scene.add(siblingPlanet);

    const createOrbitPath = (a: number, b: number, color: number, rotationY: number = 0) => {
      const curve = new THREE.EllipseCurve(0, 0, a, b, 0, 2 * Math.PI, false, 0);
      const points = curve.getPoints(ORBIT_SEGMENTS);
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      const material = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.5 });
      const ellipse = new THREE.Line(geometry, material);
      ellipse.rotation.x = Math.PI / 2;
      ellipse.rotation.y = rotationY;
      return ellipse;
    };

    scene.add(createOrbitPath(25, 20, 0x88aaff));
    scene.add(createOrbitPath(18, 15, 0xaabbaa, Math.PI / 6));

    const animate = () => {
      animationFrameIdRef.current = requestAnimationFrame(animate);
      const time = Date.now() * 0.0001;

      if (planetCRef.current) {
        planetCRef.current.position.x = Math.cos(time * 0.8) * 25;
        planetCRef.current.position.z = Math.sin(time * 0.8) * 20;
        planetCRef.current.rotation.y += 0.005;
      }
      if (siblingPlanetRef.current) {
        const siblingTime = time * 1.1;
        siblingPlanetRef.current.position.x = Math.cos(siblingTime) * 18 * Math.cos(Math.PI / 6) - Math.sin(siblingTime) * 15 * Math.sin(Math.PI / 6);
        siblingPlanetRef.current.position.z = Math.cos(siblingTime) * 18 * Math.sin(Math.PI / 6) + Math.sin(siblingTime) * 15 * Math.cos(Math.PI / 6);
      }
      if (starRef.current) starRef.current.rotation.y += 0.001;
      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };
    animate();

    const resizeObserver = new ResizeObserver((entries) => {
      const { width: nw, height: nh } = entries[0].contentRect;
      if (cameraRef.current && rendererRef.current && nw > 0 && nh > 0) {
        cameraRef.current.aspect = nw / nh;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(nw, nh);
      }
    });
    if (currentMount) resizeObserver.observe(currentMount);

    return () => {
      resizeObserver.disconnect();
      if (animationFrameIdRef.current) cancelAnimationFrame(animationFrameIdRef.current);
      rendererRef.current?.dispose();
    };
  }, [showMythicGlyphs]);

  const handleActivateGlyphStone = () => {
    addEchoMessage(AgentName.CelestialAnomalyWeaverAgent, "Frozen glyph-stone activated. Thermal shockwave propagating...", AGENT_PROFILES[AgentName.CelestialAnomalyWeaverAgent]?.colorClass);
  };

  const handleGazeIntoMirror = () => {
    setShowMythicGlyphs(prev => !prev);
    addEchoMessage(AgentName.CelestialAnomalyWeaverAgent, `Infrared mirror gaze ${!showMythicGlyphs ? 'engaged' : 'disengaged'}.`, AGENT_PROFILES[AgentName.CelestialAnomalyWeaverAgent]?.colorClass);
  };

  return (
    <div ref={containerRef} className="celestial-anomaly-weaver-panel bg-slate-950/90 backdrop-blur-xl border border-indigo-600/50 rounded-xl shadow-2xl p-3 text-slate-100 flex flex-col" style={{ width: propWidth, height: propHeight }}>
      <h3 className="text-lg font-cinzel font-bold text-indigo-300 mb-2 text-center tracking-wider">
        Δ.Θ8 Celestial Anomaly Weaver: 14 Herculis
      </h3>
      <div ref={mountRef} className="flex-grow relative border border-indigo-500/30 rounded-md overflow-hidden bg-black" />
      <div className="controls-area flex justify-center items-center gap-2 p-1.5 mt-1 bg-slate-800/50 rounded-md border-t border-indigo-700/30 text-[10px]">
        <Button onClick={handleActivateGlyphStone} className="py-1 px-2 text-[10px] bg-sky-600 hover:bg-sky-500">Activate Stone</Button>
        <Button onClick={handleGazeIntoMirror} className={`py-1 px-2 text-[10px] ${showMythicGlyphs ? 'bg-purple-600' : 'bg-slate-600'}`}>Infrared Gaze</Button>
      </div>
    </div>
  );
};

export default CelestialAnomalyWeaverPanel;

import React, { useMemo, useRef, useEffect, useState, useCallback } from 'react';
import type { RitualOutcome, BloodInkSpeciesName, Spark, Sephirah, SourceEchoLogEntry } from '../../types';
import { AgentName } from '../../types';
import { BLOOD_INK_SPECIES_DATA } from '../../constants';

interface TreeOfLifeVisualizerProps {
  currentEntropy: number;
  width: number | string;
  height: number | string;
  seekerTraits?: string[];
  activeFlora?: BloodInkSpeciesName | null;
  dominantAgentTone?: AgentName | null;
  lastRitualOutcome?: RitualOutcome | null;
}

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const generateMysticalIdentity = () => {
    const prefixes = ["Whisper of", "Echo of", "Glyph of", "Seed of"];
    const suffixes = ["the Void Bloom", "Fractal Resonance", "the Unseen Path"];
    return `${prefixes[Math.floor(Math.random() * prefixes.length)]} ${suffixes[Math.floor(Math.random() * suffixes.length)]}`;
};

const SEPHIROT_DATA_BASE: Omit<Sephirah, 'x' | 'y' | 'sourceSparks'>[] = [
  { id: 'keter', name: 'Keter', normalizedX: 0, normalizedY: -0.9, colorBaseHue: 0 }, 
  { id: 'chokmah', name: 'Chokmah', normalizedX: 0.45, normalizedY: -0.65, colorBaseHue: 240 }, 
  { id: 'binah', name: 'Binah', normalizedX: -0.45, normalizedY: -0.65, colorBaseHue: 0 }, 
  { id: 'tiphareth', name: 'Tiphareth', normalizedX: 0, normalizedY: 0.1, colorBaseHue: 60 }, 
  { id: 'malkuth', name: 'Malkuth', normalizedX: 0, normalizedY: 0.95, colorBaseHue: 100 }, 
];

const TreeOfLifeVisualizer: React.FC<TreeOfLifeVisualizerProps> = ({
  currentEntropy, width, height, seekerTraits = [], activeFlora, dominantAgentTone, lastRitualOutcome
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const [sephirotState, setSephirotState] = useState<Sephirah[]>([]);
  const animationFrameIdRef = useRef<number | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const { w, h } = dimensions;
    if (w > 0 && h > 0) {
        const centerX = w / 2;
        const centerY = h / 2;
        const scaleX = w * 0.4;
        const scaleY = h * 0.45;
        setSephirotState(SEPHIROT_DATA_BASE.map(s => ({
            ...s,
            x: centerX + s.normalizedX * scaleX,
            y: centerY + s.normalizedY * scaleY,
            sourceSparks: []
        })));
    }
  }, [dimensions]);

  const drawSephirah = useCallback((ctx: CanvasRenderingContext2D, s: Sephirah, entropy: number) => {
    const t = clamp(entropy, 0, 1);
    const x = s.x || 0; const y = s.y || 0;
    const radius = Math.max(0.1, Math.min(dimensions.w, dimensions.h) * 0.035 * (1 - t * 0.3));
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(radius) || radius <= 0) return;

    const grad = ctx.createRadialGradient(x, y, 0, x, y, radius * 1.5);
    grad.addColorStop(0, `hsla(${s.colorBaseHue}, 70%, 60%, 0.8)`);
    grad.addColorStop(1, `hsla(${s.colorBaseHue}, 70%, 60%, 0)`);
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(x, y, radius * 1.5, 0, Math.PI * 2); ctx.fill();

    ctx.fillStyle = `hsla(${s.colorBaseHue}, 80%, 70%, 1)`;
    ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.fill();
  }, [dimensions]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || dimensions.w <= 0 || dimensions.h <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    canvas.width = dimensions.w;
    canvas.height = dimensions.h;

    const render = () => {
      ctx.clearRect(0, 0, dimensions.w, dimensions.h);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, dimensions.w, dimensions.h);
      sephirotState.forEach(s => drawSephirah(ctx, s, currentEntropy));
      animationFrameIdRef.current = requestAnimationFrame(render);
    };
    render();
    return () => { if (animationFrameIdRef.current) cancelAnimationFrame(animationFrameIdRef.current); };
  }, [dimensions, sephirotState, currentEntropy, drawSephirah]);

  return (
    <div ref={containerRef} className="tree-of-life-visualizer-panel bg-slate-900/90 border border-sky-600/50 rounded-xl shadow-2xl p-4 my-8 text-slate-100" style={{ width, height }}>
      <canvas ref={canvasRef} className="rounded-lg w-full h-full" />
    </div>
  );
};

export default TreeOfLifeVisualizer;

import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import type { CodexDreamPanelProps, EchoMessage, Axiom, HistoricalCodexDreamSeedEventData, CodexArtifact } from '../../types';
import { ArtMode, AgentName, HistoricalEventType, ArtifactType, ArtifactRarity } from '../../types';
import { AGENT_PROFILES } from '../../constants';
import ModeSelectorAny from '../core/ModeSelectorAny';
import { Button } from '../ui/Button'; 
import { GoogleGenAI } from "@google/genai";

const ART_MODES = Object.values(ArtMode);

const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const CodexDreamPanel: React.FC<CodexDreamPanelProps> = ({
  currentEntropy,
  currentAxioms,
  lambdaValue,
  negentropyLevel,
  echoLog,
  addEchoMessage,
  width, 
  height, 
  onArtifactCreated,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [artMode, setArtMode] = useState<ArtMode>(ArtMode.DreambloomPulse);
  const [seekerInput, setSeekerInput] = useState<string>("");
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });

  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h: h - 180 }); 
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const drawArt = useCallback((ctx: CanvasRenderingContext2D, frameCount: number) => {
    const { w, h } = dimensions;
    if (w <= 0 || h <= 0) return;

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = `rgb(10, 15, 25)`;
    ctx.fillRect(0, 0, w, h);

    const centerX = w / 2;
    const centerY = h / 2;
    const t_negentropy = clamp(negentropyLevel, 0, 1);

    if (artMode === ArtMode.DreambloomPulse) {
        for (let i = 0; i < 10; i++) {
          const x = centerX + Math.sin(frameCount * 0.01 + i) * (w * 0.3);
          const y = centerY + Math.cos(frameCount * 0.01 + i) * (h * 0.3);
          const radius = (10 + Math.sin(frameCount * 0.02 + i) * 5) * t_negentropy;
          if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(radius) || radius <= 0) continue;
          ctx.fillStyle = `hsla(${(frameCount + i*30)%360}, 70%, 60%, 0.5)`;
          ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.fill();
        }
    } else {
        ctx.fillStyle = 'white';
        ctx.font = '12px serif';
        ctx.textAlign = 'center';
        if (Number.isFinite(centerX) && Number.isFinite(centerY)) {
          ctx.fillText(`Abstract ${artMode} visualization.`, centerX, centerY);
        }
    }
  }, [dimensions, artMode, negentropyLevel]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || dimensions.w <= 0 || dimensions.h <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    canvas.width = dimensions.w;
    canvas.height = dimensions.h;

    let frameId: number;
    let frameCount = 0;
    const renderLoop = () => {
      frameCount++;
      drawArt(ctx, frameCount);
      frameId = requestAnimationFrame(renderLoop);
    };
    frameId = requestAnimationFrame(renderLoop);
    return () => cancelAnimationFrame(frameId);
  }, [drawArt, dimensions]);

  const panelWidth = typeof width === 'number' ? `${width}px` : width;
  const panelHeight = typeof height === 'number' ? `${height}px` : height;

  return (
    <div ref={containerRef} className="codex-dream-panel bg-slate-950/90 backdrop-blur-md border border-purple-600/50 rounded-xl shadow-2xl p-4 text-slate-100 flex flex-col relative z-20" style={{ width: panelWidth, minHeight: panelHeight }}>
      <h3 className="text-lg font-cinzel font-bold text-purple-300 mb-2 text-center">✦ Codex Dream Panel ✦</h3>
      <ModeSelectorAny currentMode={artMode} onSetMode={setArtMode} availableModes={ART_MODES} />
      <canvas ref={canvasRef} className="w-full rounded-md border border-slate-700/70 bg-black mb-1 flex-grow" />
      <div className="flex gap-1 my-1">
        <input type="text" value={seekerInput} onChange={(e) => setSeekerInput(e.target.value)} placeholder="Whisper a seed..." className="flex-grow p-1.5 text-[10px] bg-slate-700 border-slate-600 rounded-md text-white" />
        <Button onClick={() => setSeekerInput("")} className="px-3 py-1.5 text-[10px] bg-purple-600">Clear</Button>
      </div>
      <Button onClick={() => {}} className="w-full text-xs py-2 bg-cyan-600">CAPTURE DREAMPRINT</Button>
    </div>
  );
};

export default CodexDreamPanel;

import React, { useRef, useEffect, useMemo, useCallback, useState } from 'react';
import { GeoMode, VisualizationMatrixMode, type CosmicEntropyGeometryGeneratorProps as ExternalProps, type Particle, type PanelDisplayMode } from '../../types'; 
import ModeSelector from '../core/ModeSelector'; 

interface CosmicEntropyGeometryGeneratorProps extends ExternalProps {}

const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const CosmicEntropyGeometryGenerator: React.FC<CosmicEntropyGeometryGeneratorProps> = ({ 
  currentEntropy, currentPhase, chaliceStatus, width: propWidth, height: propHeight, currentGeoMode, onSetGeoMode
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [dimensions, setDimensions] = useState({ w: 0, h: 0 });
  const animationFrameIdRef = useRef<number | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
        const { width: w, height: h } = entries[0].contentRect;
        setDimensions({ w, h: h - 120 });
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  const drawBackground = useCallback((ctx: CanvasRenderingContext2D, entropy: number, w: number, h: number) => {
    const t = clamp(entropy, 0, 1);
    const cx = w / 2; const cy = h / 2; const r = Math.max(w, h) / 1.5;
    if (!Number.isFinite(cx) || !Number.isFinite(cy) || !Number.isFinite(r) || r <= 0) {
        ctx.fillStyle = '#0f172a'; ctx.fillRect(0,0,w,h); return;
    }
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    grad.addColorStop(0, `hsla(220, 50%, ${10 - t*5}%, 1)`);
    grad.addColorStop(1, `hsla(260, 60%, 5%, 1)`);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || dimensions.w <= 0 || dimensions.h <= 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    canvas.width = dimensions.w;
    canvas.height = dimensions.h;

    const render = () => {
      ctx.clearRect(0, 0, dimensions.w, dimensions.h);
      drawBackground(ctx, currentEntropy, dimensions.w, dimensions.h);

      const cx = dimensions.w / 2; const cy = dimensions.h / 2;
      const r = Math.min(dimensions.w, dimensions.h) * 0.2;
      if (Number.isFinite(cx) && Number.isFinite(cy) && Number.isFinite(r) && r > 0) {
          ctx.strokeStyle = '#38bdf8';
          ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
      }

      animationFrameIdRef.current = requestAnimationFrame(render);
    };
    render();
    return () => { if (animationFrameIdRef.current) cancelAnimationFrame(animationFrameIdRef.current); };
  }, [dimensions, currentEntropy, drawBackground]);

  return (
    <div ref={containerRef} className="bg-slate-900/90 backdrop-blur-md border border-blue-500/30 rounded-xl shadow-2xl p-6 my-8 text-slate-100 flex flex-col" style={{ width: propWidth, height: propHeight }}>
      <h2 className="text-2xl font-cinzel font-bold mb-4 text-center text-blue-200">Cosmic Geometry Generator</h2>
      <ModeSelector<GeoMode> currentMode={currentGeoMode} onSetMode={onSetGeoMode} availableModes={Object.values(GeoMode)} />
      <canvas ref={canvasRef} className="rounded-lg border border-slate-700/30 flex-grow" />
    </div>
  );
};

export default CosmicEntropyGeometryGenerator;

