                                    <button onClick={handleEndQuest} className="p-3 rounded-xl bg-rose-900/40 border border-rose-500/40 text-rose-300 hover:bg-rose-800 transition-all">
                                        <i className="ri-close-line"></i>
                                    </button>
                                </div>
                            </div>

                            <AnimatePresence>
                                {showChronicleMenu && (
                                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-4 pt-4 border-t border-white/10 grid grid-cols-2 sm:grid-cols-4 gap-2">
                                        <button onClick={handleExportComic} disabled={isExportingComic} className="flex flex-col items-center justify-center p-2 bg-slate-800/80 rounded-xl border border-white/5 hover:border-amber-500/50 transition-all text-amber-200">
                                            <i className={`ri-file-image-line text-lg mb-1 ${isExportingComic ? 'animate-spin' : ''}`}></i>
